SELECT 'moj-all-verified-judgments-review-002-chunk-036' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"38eeea7b-7b60-53b8-b13f-ba69528e03d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -مطالبة ورثة لبيت املال بدفع دية -وفاة املورث نتيجة حادث مروري -إدانة التحقيقات قائد السيارة املتسبب يف احلادث -املتسبب يف احلادث مجهول -موافقة املقام السامي على سماع الدعوى ضد بيت املال -إلزام بيت املال بدفع الدية .","document_number":"34214049","case_number":"3418342","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/15","year":"1434","subject":"مطالبة بيت املال -مطالبة ورثة لبيت املال بدفع دية -وفاة املورث نتيجة حادث مروري -إدانة التحقيقات قائد السيارة املتسبب يف احلادث -املتسبب يف احلادث مجهول -موافقة املقام السامي على سماع الدعوى ضد بيت املال -إلزام بيت املال بدفع الدية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/5/15 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34214049 :‬‬\n                         ‫َر ْق ُم الدعوى‪3418342 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34386020‬تاريخه‪1434/12/24 :‬هـ‬\n\n\n     ‫مطالبــة بيــت املــال ‪ -‬مطالبــة ورثــة لبيــت املــال بدفــع ديــة‪ -‬وفــاة املــورث‬\n     ‫نتيجــة حــادث مــروري‪ -‬إدانــة التحقيقــات قائــد الســيارة املتســبب يف‬\n     ‫احلــادث‪ -‬املتســبب يف احلــادث مجهــول‪ -‬موافقــة املقــام الســامي علــى‬\n              ‫ســماع الدعــوى ضــد بيــت املــال‪ -‬إلــزام بيــت املــال بدفــع الديــة ‪.‬‬\n\n\n\n\n     ‫‪-1‬قــول علــى رضــي اهلل عنــه لعمــر رضــي اهلل عنــه يــا أميــر املؤمنــن( ال‬\n      ‫يعطــل دم امــرئ مســلم فــإن علمــت قاتلــه وإال فأعطــه مــن بيــت املــال)‬\n     ‫‪ _2‬قــول الفقهــاء (إن مــن هلــك بفعــل نفســه وفعــل صاحبــه فيهــدر‬\n                                              ‫فعــل نفســه) الشــرح الكبيــر ‪336/25‬‬\n     ‫‪-3‬قــول الفقهــاء (امليــت يف زحمــة كجمعــة وطــواف فيفــدى مــن بيــت‬\n                                             ‫املــال إلــخ ‪)...‬كشــاف القنــاع ‪482/13‬‬\n     ‫‪-4‬ماقــرره الفقهــاء انــه يف حالــة ثبــوت الوفــاة بســبب جنايــة ادمــي‬\n     ‫مجهــول فــإن الضمــان يكــون يف بيت املال )شــرح منتهــى اإلرادات ‪136/6‬‬\n                             ‫‪ -5‬املادة ‪ ،179‬واملادة ‪ 39‬من نظام املرافعات الشرعية‬\n\n\n\n     ‫أقــام وكيــل ورثــة دعــوى علــى ممثــل بيــت املــال يطالبــه بديــة مــورث‬\n     ‫موكليــه الــذي تــويف يف حــادث دهــس بســيارة أثبــت التحقيقــات إدانــة‬\n\n‫‪89‬‬\n\f‫قائــد الســيارة بنســبة خمســه وســبعني باملائــة وقائــد الســيارة املتســبب‬\n‫بالوفــاة مختفــي وطلــب إلــزام بيــت مــال املســلمني بدفــع خمــس وســبعني‬\n‫باملائــة مــن الدية‪-‬صــدرت املوافقــة الســامية يف ســماع الدعــوى وعليــه‬\n‫أجــاب مديــر بيــت املــال بأنــه ال مانــع لــدى بيــت املــال مــن دفــع الديــه نظــرا‬\n‫لعــدم معرفــة اجلانــي ‪-‬نظــرا الن نســبة اخلطــأ يف احلــادث املذكور خمســة‬\n‫وســبعون باملائــة ونظــرا ملــا قــرره الفقهــاء ان مــن هلــك بفعــل نفســه وفعــل‬\n‫صاحبــه فيهــدر فعــل نفســه‪ -‬وان الوفــاة بســبب جنايــة مجهــول فــإن‬\n‫الضمــان يكــون يف بيــت املــال‪ -‬ونظــرا ملوافقــة املقــام الســامي لــذا‬\n‫حكمــت احملكمــة الــزام بيــت املــال بدفــع خمســه وســبعني باملائــة مــن‬\n    ‫لديــة لورثــة املتوفــى ‪ -‬اعتــرض مديــر بيــت املــال ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬رئيــس احملكمــة العامــة‬\n‫ـاء علــى املعاملــة احملالــة لنــا بتاريــخ ‪1434/01/11‬ه ـ‬\n                                                          ‫مبحافظــة وبنـ ً‬\n‫املقيــدة باحملكمــة بتاريــخ ‪1434/01/11‬ه ـ ففــي يــوم األحــد‬\n‫املوافق‪1434/01/11‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬صباحــا‬\n‫وفيهــا ‪ ..........‬حضــر هنــدي اجلنســية مبوجــب رخصــة االقامــة رقــم ‪......‬‬\n‫تنتهــي بتاريــخ ‪1434/6/19‬ه ـ بالوكالــة عــن حامــل الرقــم االنتخابــي‬\n‫الهندي ‪ 300557/051/07 .....‬و حامل رخصة القيادة الهندية مبوجب‬\n‫الوكالــة الصــادرة مــن كاتــب عــدل مقاطعــة بــاالكاد واليــة كيــراال‬\n‫بالهنــد برقــم وتاريــخ ‪ /16‬مايــو‪2010/‬م واملخولــة له مبراجعة احملكمة‬\n‫الســتالم ديــة املتوفــى واســتالم أي تعويضــات أخــرى تخــص املتوفــى ‪...‬‬\n‫الــخ املصدقــة مــن فــرع وزارة اخلارجيــة برقــم ‪ 25‬وتاريــخ ‪1431/6/2‬ه ـ‬\n\n                                                                                             ‫‪90‬‬\n\f     ‫وكذلــك املصدقــة مــن فــرع وزارة العــدل مبنطقــة جــازان بتاريــخ‬\n     ‫‪1433/11/9‬ه ـ وموكلــي املدعــي أصالــه همــا ورثــة ‪ ............‬املتوفــى‬\n     ‫بتاريــخ ‪1431/5/25‬ه ـ والدتــه و والــده مبوجــب الوكالــة املشــار إليهــا‬\n     ‫أعــاه وحضــر حلضــوره ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫ممثــل بيــت املــال بفــرع وزارة املاليــة مبنطقــة مبوجــب خطــاب التكليــف‬\n     ‫الصــادر مــن مديــر عــام فــرع وزارة املاليــة املكلــف يف ‪1434/1/11‬ه ـ‬\n     ‫وقــد صــدر األمــر الســامي رقــم ‪/14323‬م ب وتاريــخ ‪1433/5/2‬ه ـ‬\n     ‫باملوافقــة علــى ســماع دعــوى املطالبــة بالديــة يف مواجهــة منــدوب عــن‬\n     ‫بيــت املــال وفقــا لألمــر الســامي رقــم ‪ 13400‬وتاريــخ ‪1402/6/6‬ه ـ‬\n     ‫وبســؤال املدعــي عــن دعــواه أنــه بتاريــخ ‪1431/5/25‬ه ـ حصــل ملــورث‬\n     ‫موكلــي حــادث دهــس جنــم عــن وفاتــه وقــد أدانــت التحقيقــات قائــد‬\n     ‫الســيارة املتســببة بالدهــس بنســبة خمســة وســبعني باملائــة ولــم يعــرف‬\n     ‫املتســبب بوفــاة مــورث موكلــي حتــى تاريخــه لــذا أطلــب إلــزام بيــت مــال‬\n     ‫املســلمني بدفــع الديــة ملوكلــي وقدرهــا مائتــان وخمســة وعشــرون ألــف‬\n     ‫ريــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا‬\n     ‫بنــاء علــى صــدور املوافقــة الســامية برقــم ‪ 14323‬يف ‪1433/2/2‬ه ـ عــن‬\n     ‫ســماع الدعــوى فــا مانــع مــن دفــع الديــة من بيــت املال نظرا لعــدم معرفة‬\n     ‫اجلانــي هكــذا أجــاب ويف يــوم الســبت ‪1433/1/24‬ه ـ الســاعة التاســعة‬\n     ‫والنصــف صباحــا افتتحــت اجللســة الثانيــة وفيهــا حضر الطرفــان‪ ،‬فبناء‬\n     ‫علــى مــا تقــدم مــن الدعــوى واالجابــة ونظــرا لكــون نســبة اخلطــأ علــى‬\n     ‫املدهــوس خمســة وعشــرون باملائــة ونظــرا ملــا قــرره الفقهــاء أن مــن هلــك‬\n     ‫بفعــل نفســه وفعــل صاحبــه فيهــدر فعــل نفســه انظــر كشــاف القنــاع‬\n     ‫‪ 325/13‬والشــرح الكبيــر ‪ 336/25‬ونظــرا لكــون الديــة يف هــذه‬\n\n\n‫‪91‬‬\n\f‫احلالــة مائتــان وخمســة وعشــرون الــف ريــال ونظــرا ملــا قــرره الفقهــاء أن‬\n‫يف حالــة ثبــوت الوفــاة بســبب جنايــة آدمــي مجهــول فــإن الضمــان يكــون‬\n‫يف بيــت املــال فقــد جــاء يف شــرح منتهــى االيــرادات ‪( 136/6‬كميــت يف‬\n‫زحمــة كجمعــة وطــواف فيفــدى مــن بيــت املــال نصــا واحتــج مبــا روي‬\n‫عــن عمــر وعلــي ومنــه مــا روى ســعيد يف ســننه عــن قــال قتــل رجــل يف‬\n‫زحــام النــاس بعرفــة فجــاء أهلــه إلــى عمــر فقــال بينتكــم علــى مــن قتلــه‬\n‫فقــال علــي يــا أميــر املؤمنــن ال يطــل دم أمــرئ مســلم فــإن علمــت قاتلــه‬\n‫وإال فأعطيتــه مــن بيــت املــال ) أ ه ــو أنظــر كذلــك كشــاف القنــاع‬\n‫‪ 482/13‬ونظــرا ملوافقــة املقــام الســامي علــى ســماع هــذه الدعــوى لــذا‬\n‫فقــد أمــرت بــأن يدفــع بيــت املــال بــوزارة املاليــة لورثــة ‪ ........‬مبلــغ وقــدره‬\n‫مائتــان وخمســة وعشــرون الــف ريــال ألمــه مبلــغ وقــدره خمســة وســبعون‬\n‫الــف ريــال ولوالــده مبلــغ وقــدره مائــة وخمســون الــف ريــال وبــه حكمــت‬\n‫وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم املعارضــة وأمــرت برفــع‬\n‫كامــل املعاملــة إلــى محكمــة اإلســتئناف مبنطقــة عســير اســتنادا‬\n‫للمــادة التاســعة والســبعون بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n‫واهلل املوفــق وقــد اغلقــت اجللســة الســاعة العاشــرة صباحــا وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم األربعــاء ‪1434/4/17‬ه ـ افتتحــت اجللســة‬\n‫الثالثــة الســاعة الثامنــة والنصــف صباحــا وفيهــا حضــر الطرفــان وقــد‬\n‫جــرى منــا رفــع املعاملــة إلــى محكمــة االســتئناف وقــد أعيــدت إلينــا‬\n‫مــن رئيــس محكمــة االســتئناف مبنطقــة عســير برقــم ‪ 34404378‬يف‬\n‫‪1434/8/11‬ه ـ واملقيــدة باحملكمــة يف ‪1434/3/17‬ه ـ واملرفــق بهــا‬\n‫قــرار املالحظــة يف ‪1434/2/26‬ه ـ الصــادر مــن قضــاة الدائــرة الثالثــة‬\n\n\n                                                                                             ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":89,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3a92eb253e4c9334774759f3d55bdd01c1a4388257664e9a7c5ef14d08dc02f1","normalized_text_hash":"b0055edd38390170f4b89b1563ecfd50ddb0be1521d1048669ad5db729422bb9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p89-34214049"},{"id":"18988786-44f4-5fa1-8fa9-30be0e11d08d","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى ضد بيت املال -مطالبة أمن بيت املال بتسليم مبلغ مالي من الدولة لصالح املدعن -شراء عقار لقاصر -استعانة برأي اخلبراء -سداد الديون مقدم على حقوق الورثة -ثبوت الدعوى - وجوب تزكية الشهود -رعاية الدولة ألسر الشهداء -إمتام عقد البيع أمام المحكمة صونا حلقوق القصر.","document_number":"3427561","case_number":"3453148","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"دعوى ضد بيت املال -مطالبة أمن بيت املال بتسليم مبلغ مالي من الدولة لصالح املدعن -شراء عقار لقاصر -استعانة برأي اخلبراء -سداد الديون مقدم على حقوق الورثة -ثبوت الدعوى - وجوب تزكية الشهود -رعاية الدولة ألسر الشهداء -إمتام عقد البيع أمام المحكمة صونا حلقوق القصر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3427561 :‬‬\n                    ‫َر ْق ُم الدعوى‪3453148 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34241417‬تاريخه‪1434/6/14 :‬هـ‬\n\n\n‫دعــوى ضــد بيــت املــال‪ -‬مطالبــة أمــن بيــت املــال بتســليم مبلــغ مالــي‬\n‫مــن الدولــة لصالــح املدعــن‪ -‬شــراء عقــار لقاصــر‪ -‬اســتعانة بــرأي‬\n‫اخلبــراء‪ -‬ســداد الديــون مقــدم علــى حقــوق الورثــة ‪ -‬ثبــوت الدعــوى ‪-‬‬\n‫وجــوب تزكيــة الشــهود ‪ -‬رعايــة الدولــة ألســر الشــهداء ‪ -‬إمتــام عقــد‬\n                             ‫البيــع أمــام احملكمــة صونــا حلقــوق القصــر‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة املســتقر‬\n                                                   ‫عليهــا يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــون أن الدولــة قــد أودعــت يف بيــت مــال احملكمــة املبلــغ‬\n‫املذكــور يف الدعــوى لصالــح أســرة مورثهــم لتأمــن منــزل وســداد ديونــه‬\n‫وأنهــم وجــدوا منــز ًال مناســب ًا ويرغبــون شــرائه‪ ،‬لــذا طلبــوا إلــزام بيــت‬\n‫مــال احملكمــة بتســليمهم املبلــغ املذكــور ليقومــوا بتســليمه لصاحــب‬\n‫املنــزل‪ -‬أقــر أمــن بيــت مــال احملكمــة بإيــداع املبلــغ املذكــور لصالــح‬\n‫املدعــن وأنــه ال مانــع مــن تســليمه لهــم إذا صــدر حكــم قضائــي‬\n‫بذلــك‪ -‬قــرر املدعــون بأنــه ال يوجــد ديــون علــى املــورث وأنهــم ســيتحملون‬\n‫ســدادها لــو وجــدت‪ -‬حتققــت احملكمــة مــن وجــود غبطــة ومصلحــة‬\n\n                                                                                      ‫‪98‬‬\n\f     ‫للقاصريــن مــن الورثــة يف شــراء املنــزل املذكــور لهــم واطلعــت علــى‬\n     ‫املســتندات الالزمــة للســير يف الدعــوى‪ -‬قضــت احملكمــة بإلــزام بيــت‬\n     ‫املــال باحملكمــة بدفــع املبلــغ املذكــور لصالــح الورثــة املدعــن ويســلم‬\n     ‫ملالــك املنــزل‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم بعــد‬\n                                                                 ‫االجــراء األخيــر‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي باحملكمــة العامــة بأبــو‬\n     ‫عريــش وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بأبــو عريــش برقــم ‪ 3453148‬وتاريــخ ‪ 1434/02/02‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34263523‬وتاريــخ ‪ 1434/02/02‬ه ـ ففــي يــوم‬\n     ‫الســبت املوافق‪1434/02/02‬ه ـ افتتحــت اجللســة األولــى يف متام الســاعة‬\n     ‫الثانيــة عشــر والنصــف وفيهــا حضــرت ‪ .....‬ســعودية اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال صامطــة أصالــة عــن نفســها‬\n     ‫وبالواليــة عــن ‪ .....‬و ‪ .....‬و ‪ ..... .....‬و ‪ .....‬و ‪ .....‬مبوجــب صــك الواليــة رقــم‬\n     ‫‪ 10‬و تاريــخ ‪1432/11/20‬ه ـ الصــادر مــن احملكمــة العامــة باحلــرث‬\n     ‫كمــا حضــرت‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n     ‫‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و‪ .....‬ســعودية‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و‪ .....‬ســعودية اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ .....‬و املعــرف بهــم مــن قبــل ‪ .....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال صامطــة وحضــر‬\n     ‫حلضورهــم أمــن بيــت املــال باحملكمــة‪ .....‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ .....‬وقــرروا يف دعواهــم قائلــن إن مورثنــا ‪ .....‬تــويف‬\n\n‫‪99‬‬\n\f‫بتاريخ ‪1432/2/28‬هـ و أنحصر إرثه يف زوجته ‪ .....‬ويف أوالده البالغني‬\n‫وهــم ‪.....‬و ‪.....‬و ‪ .....‬و‪ .....‬ويف القاصريــن وهــم ‪.....‬و ‪ .....‬و‪ .....‬و‪ .....‬و‪.....‬‬\n‫مبوجــب صــك حصــر الورثــة رقم ‪ 3/9‬وتاريــخ ‪1432/3/2‬هـ الصادر من‬\n‫احملكمــة العامــة مبحافظــة صامطــة وقــد صــدرت توجيهــات صاحــب‬\n‫الســمو امللكــي مســاعد وزيــر الداخليــة للشــؤون األمنيــة مبســاعدة‬\n‫أســرة الشــهيد ‪ .....‬بتأمــن منــزل وســداد ديونــه مببلــغ وقــدره مليــون‬\n‫وثالثمائــة ألــف ريالــ‪ 1300000‬وقــد جــرى البحــث عــن منــزل مــن أجــل‬\n‫شــرائه ووجــد مبحافظــة أبــو عريــش مببلــغ وقــدره مليــون ومائتــا ألــف‬\n‫ريــال ‪ 1200000‬وقــد أودع املبلــغ يف بيــت مــال احملكمــة أطلــب إلــزام‬\n‫بيــت مــال احملكمــة بتســليمنا مبلــغ وقــدره مليــون ومائتــا ألــف ريــال‬\n‫‪ 1200000‬لتســليمه لصاحــب املنــزل املشــترى هكــذا ادعــوا عقــب ذلــك‬\n‫طلبــت مــن املدعيــات صــك حصــر الورثــة وصــك الواليــة فأبــرزن صــك‬\n‫حصــر الورثــة رقــم ‪ 3/9‬و تاريــخ ‪1432/3/2‬ه ـ الصــادر مــن احملكمــة‬\n‫العامــة بصامطــة و املتضمــن وفــاة ‪ .‬و انحصــار إرثــه يف زوجتــه ‪ .....‬ويف‬\n‫أوالده البالغــن وهــم ‪ .....‬و ‪ .....‬و ‪ ..........‬و‪ .....‬ويف القاصريــن وهــم ‪ .....‬و‬\n‫‪...... .....‬و‪ ....‬و‪.....‬و‪ .....‬وصــك الواليــة رقــم ‪ 10‬وتاريــخ ‪1432/11/20‬ه ـ‬\n‫الصــادر مــن احملكمــة العامــة باحلــرث و املتضمــن إقامــة ‪ .....‬وليــة‬\n‫علــى أوالدهــا القصــر ‪ .....‬و ‪ .....‬و ‪ .....‬و ‪ .....‬و ‪ .....‬و باالطــاع عليــه‬\n‫وجدتــه طبقــا ملــا ذكــر وبعــرض دعــوى املدعيــات علــى أمــن بيــت املــال‬\n‫باحملكمــة أجــاب قائــا مــا ذكرتــه املدعيــات مــن إيــداع مبلــغ وقــدره‬\n‫مليــون وثالثمائــة الــف ريالــ‪ 1300000‬فصحيــح وذلــك مبوجــب الســند‬\n‫رقــم ‪ 2/589347‬و تاريــخ ‪1433/5/26‬ه ـ و احلــاوي مبلــغ وقــدره مليــون‬\n‫وثالثمائــة ألــف ريالــ‪ 1300000‬مبوجــب الشــيكني رقــم ‪873418‬‬\n\n\n                                                                                          ‫‪100‬‬\n\f      ‫و ‪ 873419‬وتاريــخ ‪1433/5/21‬ه ـ و العائــد لورثــة املتوفــى ‪ .....‬وال‬\n      ‫مانــع لــدي مــن تســليم املبلــغ بعــد صــدور حكــم بذلــك علــى بيــت املــال‬\n      ‫هكــذا أجــاب عقــب ذلــك جــرى االطــاع خطــاب مديــر عــام الشــؤون‬\n      ‫العســكرية رقــم ‪ 47105‬وتاريــخ ‪1433/4/26‬ه ـ و املوجــه إلــى رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة أبــو عريــش املتضمــن آمــل مــن فضيلتكــم‬\n      ‫التكــرم بســداد الديــون التــي يف ذمــة الشــهيد ويف حــال عــدم وجــود‬\n      ‫ديــون علــى الشــهيد يأخــذ إقــرار بذلــك ويتــم تأمــن ســكن ألســرة‬\n      ‫الشــهيد و تســجيله باســم زوجة الشــهيد ‪ .....‬و أبنائه ‪ .....‬و‪ .....‬و‪ .....‬و‪.....‬‬\n      ‫و‪ .....‬و‪ ..... .....‬و‪ .....‬و‪.....‬و‪ .....‬بالتســاوي علــى أن يهمــش علــى الصــك‬\n      ‫بعــدم بيــع املنــزل حتــى بلــوغ القصــر ســن الرشــد و تزويدنــا بنســخه مــن‬\n      ‫ملكيــة املنــزل عليــه جــرى ســؤال املدعيــات هــل يوجــد علــى مورثكــم‬\n      ‫املتوفــى أي ديــون فأجابــت كل واحــدة مبفردهــا قائلــة ال يوجــد عليــه‬\n      ‫أي ديــون ويف حــال ظهــور ذلــك نتحمــل ســدادها وقــد مت أخــذ إقــرار‬\n      ‫بذلــك عليهــم مرفــق باملعاملــة هكــذا أجابــت كل واحــده مبفردهــا‬\n      ‫عقــب ذلــك ســألت املدعيــات عــن املنــزل الذيــن يرغبــون يف شــرائه‬\n      ‫فأجــن قائــات أن املنــزل يقــع يف محافظــة أبــو عريــش شــمال للشــقق‬\n      ‫املفروشــة و اململــوك ل‪ .....‬مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n      ‫أبــو عريــش برقــم ‪ 105‬وتاريــخ ‪1408/6/14‬ه ـ جلــد ‪ 41‬صحيفــة رقــم‬\n      ‫‪ 156-155‬مببلــغ وقــدره مليــون و مائتــا ألــف ريــال ‪ 1200000‬هكــذا‬\n      ‫أجــن عليــه فقــد حضــرت ‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....‬واملعــرف بهــا مــن قبــل زوجهــا س‪ .....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال جــازان و بســؤالها عمــا‬\n      ‫ذكــرت املدعيــات أجابــت قائلــة أنــه مت االتفــاق مــع ورثــة ‪ .....‬علــى بيــع‬\n\n\n‫‪101‬‬\n\f‫املنــزل عليهــم مببلــغ وقــدره مليــون و مائتــا ألــف ريــال ‪ 1200000‬وال مانــع‬\n‫لــدي مــن بيعــه عليهــم هكــذا أجابــت عقــب ذلــك جــرى عقــد البيــع يف‬\n‫مجلــس احلكــم بقــول أنــا ف‪ .....‬بعــت املنــزل اململــوك لــي بالصــك رقــم‬\n‫‪ 105‬و وتاريــخ ‪1408/6/14‬ه ـ جلــد ‪ 41‬صحيفــة رقــم ‪ 156-155‬مببلــغ‬\n‫وقــدره مليــون و مائتــا ألــف ريــال ‪ 1200000‬علــى ورثــة ‪ .....‬و حصــل‬\n‫القبــول مــن املدعيــات بقولهــن قبلنــا هــذا البيــع و رضينــا بــه وقــد اطلعنــا‬\n‫وشــاهدنا املنــزل املذكــور و كان ذلــك بحضــور و شــهادة ‪ .....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال ‪ .....‬و ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي ‪ .....‬الصــادر مــن أحــوال ‪.....‬‬\n‫ذلــك جــرى ســؤال البائعــة عــن صــك املنــزل فأبــرزت الصــك رقــم ‪105‬‬\n‫وتاريــخ ‪1408/6/14‬ه ـ واحلــاوي لقطعــة األرض رقــم ‪ 5‬مــن مخطــط‬\n‫أرضــه املعتمــد واحلــدود و األطــوال و املســاحة كالتالــي شــماال القطعــة‬\n‫رقــم ‪ 3‬و طــول الضلــع ‪ 21‬متــر جنوبــا شــارع مقتــرح عــرض ‪ 10‬متــر‬\n‫وطــول الضلــع ‪ 18‬شــرقا شــارع عــرض ‪ 10‬متــر و طــول الضلــع ‪ 13,5‬ثــم‬\n‫ينحنــي بطــول ‪ 4‬متــر غربــا القطعــة رقــم ‪ 4‬وطــول الضلــع ‪ 16.5‬متــر و‬\n‫املســاحة الكليــة ‪ 340,5‬ثالثمائــة وأربعــون متــر و نصــف املتــر وجــرى‬\n‫االستفســار عــن ســامة الصــك فــورد اجلــواب برقــم ‪/134/879‬ج و‬\n‫تاريــخ ‪1433/7/22‬ه ـ و املتضمــن أن الصــك ســليم و مطابــق لســجله‬\n‫وســاري املفعــول كمــا جــرى الكتابــة لهيئــة النظــر باحملكمــة‬\n‫باخلطــاب رقــم ‪ 2/2362‬وتاريــخ ‪1433/7/29‬ه ـ لالستفســار هــل يف‬\n‫شــرائه مبلــغ وقــدره مليــون ومائتــا ألــف ريــال غبطــة و مصلحــه للقصــر‬\n‫فوردنــا جوابهــم باخلطــاب رقــم ‪/156‬ه ـ يف ‪1433/8/4‬ه ـ واملتضمــن أنــه‬\n‫مت الوقــوف علــى املنــزل الواقــع باحلــي ‪ ..........‬مبحافظــة أبــو عريــش وهــو‬\n\n\n                                                                                        ‫‪102‬‬\n\f      ‫عبــارة عــن عمــاره ســكنية دوريــن وملحــق حتتــوي علــى خمــس شــقق‬\n      ‫ومحاطــة بســور مــن جميــع اجلهــات وقيمــة الشــراء مببلــغ وقــدره مليــون‬\n      ‫ومائتــا ألــف ريــال بــه غبطــة ومصلحــه للقصــر ويجــود بالســكن جميــع‬\n      ‫اخلدمــات مــن كهربــاء ومــاء و خالفــه أ‪.‬ه ـ كمــا جــرت الكتابــة ملديــر‬\n      ‫عــام الشــؤون العســكرية بــوزارة الداخليــة باخلطــاب رقــم ‪331983767‬‬\n      ‫وتاريــخ ‪1433/11/10‬ه ـ لإلفــادة عــن باقــي املبلغ فورد اجلــواب باخلطاب‬\n      ‫رقــم ‪ 3411‬وتاريــخ ‪1434/1/7‬ه ـ و املتضمــن أنــه بعــد تأمــن املنــزل بنــاء‬\n      ‫علــى البرقيــة الســابقة بعــث املبلــغ املتبقــي بشــيك باســم اإلدارة العامــة‬\n      ‫للنفقــات األمنيــة ليتــم توزيعــه مــن قبــل اجلهــة املختصــة بالــوزارة فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى و اإلجابــة ومبــا أن املدعيــات طلــن إلــزام‬\n      ‫أمــن بيــت املــال باحملكمــة بتســليم مبلــغ وقــدره مليــون ومائتــا ألــف ريال‬\n      ‫لصاحلهــم مقابــل شــراء املنــزل مــن البائعــة ف‪ .....‬و مبــا أن أمــن بيــت‬\n      ‫املــال أقــر بوجــود املبلــغ ببيــت مــال احملكمــة وال مانــع لديــه مــن تســليمه‬\n      ‫بعــد صــدور حكــم عليــه و مبــا أن البائعــة قــد حضــرت و مت إجــراء عقــد‬\n      ‫البيــع مبجلــس احلكــم علــى مبلــغ وقــدره مليــون ومائتــا ألــف ريــال و بعــد‬\n      ‫االطــاع علــى صــك حصــر الورثــة وصــك الواليــة وصــك ملكيــة العقــار‬\n      ‫املــدون بعاليــه و خطــاب هيئــة النظــر و خطــاب مديــر عــام الشــؤون‬\n      ‫العســكرية بــوزارة الداخليــة وطلبــه بعــث باقــي املبلــغ باســم اإلدارة‬\n      ‫العامــة للنفقــات األمنيــة لذلــك كلــه و لــكل مــا تقــدم فقــد ألزمــت‬\n      ‫أمــن بيــت املــال باحملكمــة ‪ .....‬أوال بدفــع مبلــغ وقــدره مليــون مائتــا‬\n      ‫ألــف ريــال لصالــح ورثــة ‪ .....‬و يســلم للبائعــة ‪ .....‬ثانيــا دفــع مبلــغ وقــدره‬\n      ‫مائــة ألــف ريــال لــإدارة العامــة للنفقــات األمنيــة وأمــرت بالتهميــش علــى‬\n      ‫صــك املنــزل بانتقــال امللكيــة ل‪ .....‬و ‪ .....‬و‪ .....‬و‪ .....‬و‪..... .....‬و ‪ .....‬و‪.....‬و‬\n\n\n‫‪103‬‬\n\f‫‪ .....‬و‪ .....‬أبنــاء ‪ .....‬بالتســاوي وعــدم بيــع املنــزل حتــى بلــوغ القصــر ســن‬\n‫الرشــد وبــه حكمــت و بعــرض احلكــم علــى املدعيــات قــررن القناعــة‬\n‫بــه وقــرر أمــن بيــت املــال عــدم القناعــة بــدون الئحــة اعتراضيــة عليــه‬\n‫أمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف لتدقيــق‬\n‫احلكــم و حتــى ال يخفــى جــرى تدوينــه و بــاهلل التوفيــق و أقفلــت اجللســة‬\n‫يف متــام الســاعة الواحــدة و خمســة وأربعــون دقيقــة وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد و علــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/2/2‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي باحملكمــة العامــة بأبــو‬\n‫عريــش ففــي يــوم الســبت املوافــق‪ 1434/03/28‬ه ـ افتتحــت اجللســة‬\n‫الثانيــة يف متــام الســاعة احلاديــة عشــر و النصــف وفيها حضــرت املدعيات‬\n‫و املعــرف بهــن املثبــت هوياتهــم يف اجللســة األولــى بنــاء علــى املعاملــة‬\n‫الــواردة إلينــا مــن محكمــة االســتئناف برقــم ‪ 34348433‬وتاريــخ‬\n‫‪1434/3/10‬ه ـ و املرفــق بهــا قــرار املالحظــة رقــم ‪ 3454869‬وتاريــخ‬\n‫‪1434/3/3‬ه ـ و املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه و أوراق‬\n‫املعاملــة لوحــظ مــا يلــي لــم يطلــب فضيلــة ناظــر القضيــة بينــة مــن أهــل‬\n‫اخلبــرة تشــهد بــأن يف شــراء الــدار املوصوفــة بالصــك غبطــه ومصلحــة‬\n‫للقصــر والبــد مــن ذلــك فلمالحظــة مــا ذكــر و إحلــاق مــا يســتجد‬\n‫بالضبــط وصورتــه وخالصتــه بالصــك وســجله و اهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد و آلــه وصحبــه وســلم دائــرة األحــوال الشــخصية و‬\n‫األوقــاف و الوصايــا والقصــار وبيــوت املــال قاضــي اســتئناف ‪ .....‬ختمــه‬\n‫و توقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .....‬ختمــه‬\n‫وتوقيعــه أ‪.‬ه ـ عليــه أجيــب أصحــاب الفضيلة نفعني اهلل بعلمهم أنه جرى‬\n‫إحضــار كال مــن ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n\n\n                                                                                        ‫‪104‬‬\n\f      ‫الصــادر أحــوال أبــو عريــش وبســؤاله عــن عمــره و عملــه ومحــل إقامتــه‬\n      ‫ا عمــري ثالثــة وخمســون عام ـ ًا و‬       ‫وصلــة قرابتــه باملدعــن أجــاب قائ ـ ً‬\n      ‫أعمــل صاحــب مكتــب عقــار ومــن ســكان أبــو عريــش وال توجــد بينــي‬\n      ‫وبــن املدعــن أي صلــة قرابــة كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال أبــو عريــش وبســؤاله عــن‬\n      ‫ا عمري‬    ‫عمــره و عملــه ومحــل إقامتــه وصلــة قرابتــه باملدعــن أجــاب قائـ ً‬\n      ‫واحــد وأربعــون عامـ ًا وأعمــل موظــف يف وزارة العــدل وصاحــب مكتــب‬\n      ‫عقــار وأســكن محافظــة أبــو عريــش وال يوجــد بينــي وبــن املدعــن أي‬\n      ‫صلــة قرابــة وبســؤال كل واحــد منهمــا مبفــرده هــل يف شــراء الــدار‬\n      ‫املوصوفــة بالصــك غبطــه ومصلحــة للقصــر أم ال أجــاب كل واحــد‬\n      ‫منهمــا مبفــرده قائــا نعــم يوجــد يف شــراء املنــزل املذكــور بعاليــة‬\n      ‫مصلحــة و غبطــه للقصــر هكــذا أجــاب كل واحــد منهمــا مبفــرده‬\n      ‫عليــه أمــرت بإحلــاق ذلــك علــى الصــك وســجله وصــورة الضبــط و أمــرت‬\n      ‫بإعــادة كامــل أوراق املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكم‬\n      ‫و بــاهلل التوفيــق وحتــى ال يخفــى جــرى تدوينــه و أقفلــت اجللســة يف متــام‬\n           ‫الســاعة الثانيــة عشــر و صلــى اهلل وســلم حــرر يف ‪28/03/1434‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n      ‫فلــدي أنــا ‪ .....‬القاضــي باحملكمــة العامــة بأبــو عريــش ففــي يــوم األحــد‬\n      ‫املوافق‪1434/05/12‬ه ـ افتتحــت اجللســة الثالثــة يف متــام الســاعة احلاديــة‬\n      ‫عشــر والنصــف بنــاء علــى املعاملــة الــواردة إلينا من محكمة االســتئناف‬\n      ‫مبوجــب خطــاب فضيلــة رئيســها رقــم ‪ 34875185‬وتاريخ‪1434/5/1‬ه ـ‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 34875185‬وتاريخ ‪1434/5/8‬هـ واملرفق به‬\n      ‫قــرار املالحظــة الصــادر مــن دائــرة األحوال الشــخصية رقــم ‪34194860‬‬\n\n\n‫‪105‬‬\n\f‫وتاريــخ ‪1434/4/22‬ه ـ واملتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة لوحــظ مــا يلــي لــم جنــد أن فضيلتــه طلــب تزكيــة‬\n‫الشــاهدين والبــد مــن ذلــك فلمالحظــة مــا ذكــر وإحلــاق مــا يســتجد‬\n‫يف الضبــط وصورتــه وملخصــه بالصــك وســجله واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم دائــرة األحــوال الشــخصية‬\n‫واألوقــاف والقصــار وبيــوت املــال قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه‬\n‫قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .....‬ختمــه وتوقيعــه‬\n‫عليــه أجيــب أصحــاب الفضيلــة نفعنــي اهلل بعلمهــم أن القرائــن مــن‬\n‫شــهادة الشــاهدين وخطــاب قســم اخلبــراء جــاء فيــه مــا يحقــق الغبطــة‬\n‫واملصلحــة ولطلــب أصحــاب الفضيلــة تزكيــة الشــاهدين فقــد حضــر‬\n‫كال مــن ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬الصــادر‬\n‫مــن أحــوال أبــو عريــش و‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬الصــادر مــن أحــوال أبــو عريــش وبســؤال كل واحــد مبفــرده‬\n‫عــن الشــاهدين أجــاب قائــا الشــاهدين عدلــن مرضيــي الشــهادة‬\n‫هكــذا أجــاب كل واحــد مبفــرده عليــه أمــرت بإحلــاق ذلــك بالصــك‬\n‫وســجله وإعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف وأقفلــت‬\n‫اجللســة يف متــام الســاعة الثانيــة عشــر وحتــى ال يخفــى جــرى تدوينــه‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                  ‫حــرر يف ‪121434/05/‬ه ـ ‪.‬‬\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34241417‬وتاريــخ‬\n                                               ‫‪1434/6/14‬هـ ‪.‬‬\n\n\n\n                                                                                  ‫‪106‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":98,"source_page_end":106,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9fee818b7a7042a261942c5a0ed7a4319389945425e7f8fd3057012f9a35f77d","normalized_text_hash":"4b09ed31c7d1ad3632238303b01df629a8248c409f4b851cdea8c62988a503af","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p98-3427561"},{"id":"9230a9eb-9560-56c3-927e-28d0866de844","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -نزع ملكية عقار لتوسعة احلرم -إيداع قيمة تعويض ببيت املال -مطالبة بيت املال باملبلغ -إقرار بيت املال بحيازته املبلغ -إلزام بيت املال بتسليم املبلغ للمدعن .","document_number":"34227320","case_number":"3456138","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"مطالبة بيت املال -نزع ملكية عقار لتوسعة احلرم -إيداع قيمة تعويض ببيت املال -مطالبة بيت املال باملبلغ -إقرار بيت املال بحيازته املبلغ -إلزام بيت املال بتسليم املبلغ للمدعن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34227320 :‬‬\n                          ‫َر ْق ُم الدعوى‪3456138 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34388622‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n      ‫مطالبــة بيــت املــال‪ -‬نــزع ملكيــة عقــار لتوســعة احلــرم‪ -‬إيــداع قيمــة‬\n      ‫تعويــض ببيــت املــال‪ -‬مطالبــة بيــت املــال باملبلــغ‪ -‬إقــرار بيــت املــال‬\n               ‫بحيازتــه املبلــغ‪ -‬إلــزام بيــت املــال بتســليم املبلــغ للمدعــن ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫أقــام رجــل دعــوى يطالــب بيــت املــال بنصيــب موكليــه مــن العقــار املنزوع‬\n      ‫لصالــح توســعة الســاحة الشــمالية للحــرم ‪ -‬أقــر مندوب بيــت املال بوجود‬\n      ‫مــال مــودع يف بيــت املــال لصالــح مــورث املدعــن وأنــه ال مانــع لــدى بيــت‬\n      ‫املــال مــن دفعــه ملســتحقه إذا ثبــت لــدى احملكمــة اســتحقاق املدعــي‬\n      ‫مبــا يطالــب بــه اطلعــت احملكمــة علــى كافــة األوراق واملســتندات‬\n      ‫والصكــوك فثبــت لديهــا اســتحقاق املدعــي ملــا يطالــب بــه فحكمــت‬\n      ‫علــى بيــت املــال بتســليم املدعــي حقــوق موكليــه والن احلكــم علــى بيــت‬\n                ‫املــال رفــع هــذا اإلجــراء حملكمــة االســتئناف وصــدق احلكــم‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n‫العامــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة برقــم وتاريــخ ‪1434/02/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪1434/02/03‬ه ـ حضــر بصفتــه وكيــا عــن كل مــن‬\n‫واملســتكملة للتصديقــات الرســمية مــن فـ ـ ـ ـ ــرع وزارة اخلارجيــة برقـ ـ ــم‬\n‫يف ‪1433/7/1‬ه ـ ومــن فـ ـ ـ ــرع وزارة الع ـ ـ ــدل مبكـ ــة املكرمـ ـ ـ ــة يف‬\n‫‪1433/7/1‬ه بصفتهــم أوالد وبصفتــه وكيــا وهــم ورثــة ‪ ......‬مبوجــب‬\n‫صــك حصــر االرث يف ‪ 12‬اغســطس ‪2010‬م والصــادر مــن رئيــس ناحيــة‬\n‫بوكيتكتشــيل بجمهوريــة اندونيســيا وذلــك بالوكالــة يف ‪ 8‬أغســطس‬\n‫‪2011‬م والصــادرة مــن كتابــة عــدل أريانــي كومــا إلســاري بجمهوريــة‬\n‫اندونيســيا واملســتكملة للتصديقــات الرســمية مــن فــرع وزارة اخلارجيــة‬\n‫مبكــة يف ‪1433/7/14‬ه ـ ومــن فــرع وزارة العــدل مبكــة املكرمــة‬\n‫يف ‪1433/7/12‬ه ـ واملخولــة لــه حــق املتابعــة واالســتالم والتســليم‬\n‫الــخ وادعــى قائــا انــه كان مــن اجلــاري يف العقــار الواقــع يف الفلــق‬\n‫واحملــدود شــما ًال ملــك وجنوب ـ ًا ســكة نافــذة و شــرق ًا جــاء فــارغ ومتــام‬\n‫احلــد الرحبــة العامــة وغرب ـ ًا ســكة غيــر نافــذة والواقــع بحــي الششــة‬\n‫مبكــة وقــد نــزع هــذا العقــار لصالــح توســعة الســاحات الشــمالية للحــرم‬\n‫وعــوض عنــه ثــم تــويف وانحصــر ارثــه يف زوجتــه ويف ابنتــه لــه مــن زوجتــه‬\n‫املطلقــة منــه حــال حياتــه ويف أخيــه الشــقيق وذلــك مبوجــب صــك حصــر‬\n‫اإلرث يف ‪1407/6/2‬ه ـ الصــادر مــن هــذه احملكمــة ثــم تــويف وانحصــر‬\n‫ارثــه يف زوجتــه ويف أوالده منهــا وذلــك مبوجــب صــك حصــر اإلرث يف‬\n\n                                                                                      ‫‪108‬‬\n\f      ‫‪ 2‬ابريــل ‪2012‬م والصــادر مــن كاتــب عــدل أريانــي كومــا إلســاري ثــم‬\n      ‫توفيــت وانحصــر ارثهــا وذلــك مبوجــب صــك حصــر اإلرث يف ‪ 2‬ابريــل‬\n      ‫‪2012‬م والصــادر مــن كاتــب عــدل أريانــي كومــا إلســاري بجمهوريــة‬\n      ‫اندونيســيا ثــم تــويف وانحصــر إرثــه يف زوجتــه وذلــك مبوجــب صــك‬\n      ‫حصــر اإلرث الصــادر مــن رئيــس ناحيــة بوكيــت كتشــيل بجمهوريــة‬\n      ‫اندونيســيا يف ‪ 12‬أغســطس ‪2010‬م وقــد أزيــل العقــار املذكــور ويخــص‬\n      ‫موكلــي مــن التعويــض ‪ ....‬أطلــب احلكــم علــى املدعــى عليــه بتســليمها‬\n      ‫لــي واســأله اجلــواب هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال مــا‬\n      ‫ذكــره املدعــي وكالــه يف دعــواه أن املبلــغ املذكــور مــودع يف بيــت‬\n      ‫مــال احملكمــة فهــذا صحيــح وقــد مت إيداعــه بنــاء علــى خطــاب رئيــس‬\n      ‫كتابــة العــدل األولــى مبكــة املكرمــة يف ‪1432/2/21‬ه ـ لصالــح‬\n      ‫الغائــب ‪ .....‬باعتبــار أنــه غائــب وليــس متوفــى وإذا اتضــح لكــم وفاتــه‬\n      ‫وورثتــه فــا مانــع لــدى بيــت املــال مــن تســليمه للورثــة أو لوكيلهــم إذا‬\n      ‫صــدر حكــم مــن احملكمــة بذلــك هكــذا أجــاب ثــم اطلعــت علــى‬\n      ‫الصــك فوجدتــه كمــا ذكــر املدعــي يتضمــن ‪ ....‬يف ‪1406/11/27‬ه ـ‬\n      ‫وانحصــار إرثــه فيمــن ذكرهــم املدعــي كمــا اطلعــت علــى صــك‬\n      ‫حصــر اإلرث واملســتكمل للتصديقــات الرســمية مــن فــرع وزارة‬\n      ‫اخلارجيــة مبكــة يف ‪1433/7/1‬ه ـ ومــن فــرع وزارة العــدل مبكــة يف‬\n      ‫‪1433/7/1‬ه ـ ومــن ســفارة اململكــة العربيــة الســعودية يف جاكرتــا يف‬\n      ‫‪1433/6/2‬ه ـ وصــك حصــر اإلرث يف ‪ 2‬ابريــل ‪2012‬م واملســتكمل‬\n      ‫للتصديقــات الرســمية مــن فــرع وزارة اخلارجيــة مبكــة يف ‪1433/7/1‬هـ‬\n      ‫ومــن فــرع وزارة العــدل مبكــة يف ‪1433/7/1‬ه ـ ومــن ســفارة اململكــة‬\n      ‫العربيــة الســعودية يف جاكرتــا يف ‪1433/6/2‬ه ـ والصــك حلصــر ورثــة‬\n\n\n‫‪109‬‬\n\f‫يف ‪ 12‬أغســطس ‪2010‬م واملســتكمل للتصديقــات الرســمية مــن‬\n‫فــرع وزارة اخلارجيــة ‪ 30‬يف ‪1433/7/14‬ه ـ ومــن فــرع وزارة العــدل‬\n‫مبكــة يف ‪1433/7/12‬ه ـ ومــن ســفارة اململكــة العربيــة الســعودية‬\n‫يف جاكرتــا يف ‪1431/11/10‬ه ـ ثــم اطلعــت علــى ايصــال االســتالم يف‬\n‫‪1432/3/19‬ه ـ الصــادر مــن بيــت املــال بهــذه احملكمــة لصالــح الغائــب‬\n‫بنــاء علــى خطــاب رئيــس كتابــة العــدل األولى مبكــة يف ‪1432/2/21‬ه‬\n‫وبعــد النظــر يف الدعــوى واإلجابــة ومــا تضمنــه إقــرار املدعــى عليــه‬\n‫أن بيــت املــال يف هــذه احملكمــة يف حوزتــه املبلــغ املدعــى بــه ونظــرا‬\n‫ملــا ثبــت شــرعا تــويف و مــن ضمــن ورثتــه أخــوه الشــقيق وهــو املدعــى‬\n‫بنصيبــه ونظــرا ملــا أفــادت بــه كتابــة العــدل أن املبلــغ املرصــود ونظــرا‬\n‫لثبــوت وفاتــه وانحصــار إرثــه فيمــن ذكــر بعاليــه وألن بيــت املــال جهــة‬\n‫حافظــة ألمــوال الغيــب واملفقوديــن واملتوفــن وألنــه ظهــر لهــذا الغائــب‬\n‫وارث مبوجــب الصكــوك املشــار إليهــا وهــم املــدون فلــذا يجــب شــرعا‬\n‫علــى بيــت املــال تســليم املدعــن هــذا املبلــغ النتقالــه إليهــم بــاإلرث لذلــك‬\n‫كلــه فقــد حكمــت علــى بيــت املــال بهــذه احملكمــة بتســليم املدعــن‬\n‫املبلــغ احملفــوظ لديــه لصالــح مــورث املدعــن وبعرضــه علــى منــدوب بيت‬\n‫املــال قــرر عــدم القناعــة وطلــب رفعهــا حملكمــة االســتئناف دون الئحــة‬\n‫فأجبتــه لطلبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/27‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء ‪1434/11/11‬ه ـ‬\n‫فتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف يف‬\n‫‪1434/10/7‬ه ـ وبرفقهــا القــرار يف ‪1434/9/17‬ه ـ واملتضمــن أنــه‬\n‫بدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر مالحظــة‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫مــا يلــي ‪ -1 :‬القضيــة ســبق نظرهــا من فضيلــة القاضي مبكة املكرمة‬\n      ‫مبوجــب الصــك يف ‪1433/8/5‬ه ـ وانتهــت بنقــض احلكــم مــن محكمــة‬\n      ‫االســتئناف يف ‪1434/1/4‬ه ـ علــى أن حتــال لقــاض آخــر مــع مراعــاة‬\n      ‫مــا جــاء يف قــرارات محكمــة االســتئناف ولــم يشــر فضيلتــه لذلــك يف‬\n      ‫ضبــط القضيــة وال يف الصــك ولــم يــراع مــا جــاء يف قــرارات محكمــة‬\n      ‫االســتئناف ‪ -2‬لــم يطلــب مــن املدعــي اثبــات متلــك املتــويف املذكــور‬\n      ‫لهــذا العقــار ومقــدار التعويــض والبــد مــن ذلــك قبــل احلكــم علــى بيــت‬\n      ‫املــال ‪ -3‬لــم يوضــح نصيــب كل وارث واهلل املوفــق وعليــه أجيــب بانــه‬\n      ‫ســبق نظــر هــذه الدعــوى مــن فضيلــة الشــيخ بهــذه احملكمــة بالصــك‬\n      ‫املذكــور ونقــض مبوجــب قــرار محكمــة االســتئناف املشــار إليــه وأمــا‬\n      ‫مراعــاة مــا جــاء يف قــرار محكمــة االســتئناف فغيــر الزم مالــم يقنــع بــه‬\n      ‫ناظــر القضيــة علمــا أننــي طلبــت صــك التملــك وأجلــت النظــر واحلكــم‬\n      ‫لذلــك ورصــدت مضمونــه وهــو ضمــن أهــم مالحظــات الدائــرة علــى‬\n      ‫احلكــم املنقــوض وأزيــد بيانــا هنــا أنــه جــرى اطالعــي علــى صــك العقــار‬\n      ‫املنــزوع فوجدتــه يف ‪1393/6/14‬ه ـ الصــادر مــن كاتــب عــدل مكــة‬\n      ‫فوجدتــه كمــا جــاء يف دعــوى املدعــي ســوى وقــد أقحــم يف ضمــن دعــواه‬\n      ‫أنــه واقــع يف الششــه وهــذا ســهو والصــواب مــا ذكــره يف أول دعــواه‬\n      ‫أنــه واقــع يف الفلــق وأيضــا فقــد رصــدت حصــر وأمــا مقــدار التعويــض‬\n      ‫فقــد ذكرتــه يف ضمــن إجابــة مديــر بيــت املــال أنــه يخــص وأمــا قســمة‬\n      ‫املبلــغ بــن الورثــة فلــم يطلبــه املدعــي ومعلــوم أن القاضــي إمنــا يتبــع دعــوى‬\n      ‫املدعــي وال يخــرج يف النظــر عنهــا ثــم إن قســمة املبلــغ ال تخضــع للنظــر‬\n      ‫القضائــي مــا لــم تدخلهــا اخلصومــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/11/11‬هــ‪.‬‬\n\n\n‫‪111‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثاءاملوافــق‪ 1435/01/16‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11.30‬وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف يف ‪1435/1/4‬ه ـ وبرفقهــا القــرار يف ‪1434/12/25‬ه ـ‬\n‫واملتضمــن املوافقــة باألكثريــة املوافقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر‪ .‬وبــاهلل التوفيــق ‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1435/1/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء ‪1435/1/30‬ه ـ فتحــت‬\n‫اجللســة وفيهــا وردنــا خطــاب مديــر بيــت املــال يف ‪1435/1/30‬ه ـ‬\n‫واملتضمــن مــا نصــه‪ :‬نرفــق لكــم الشــيك يف ‪1435/1/30‬ه ـ الصــادر‬\n‫مــن فــرع مؤسســة النقــد مبكــة مقابــل للشــيك الصــادر مــن بيــت املــال‬\n‫يف ‪1435/1/29‬ه ـ ألمــر الوكيــل ‪ ....‬وذلــك لقــاء املبلــغ املــودع لصالــح‪.‬‬\n‫مــع أصــل الصــك الصــادر مــن فضيلتــك يف ‪1434/5/29‬ه ـ ونأمــل مــن‬\n‫فضيلتكــم التكــرم بإعادتــه إلينــا حلفظــه بعــد إكمــال الــازم أ‪.‬ه ـ‬\n‫لــذا فقــد جــرى تســليم الشــيك املذكــور لوكيــل وســوف يهمــش علــى‬\n      ‫صكــه وســجله مبوجبــه وبــاهلل التوفيــق حــرر يف ‪1435/1/30‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ‪ ..........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫وتاريــخ ‪1434/5/29‬ه ـ املتضمــن دعــوى‪ ..........‬ضــد‪ .....‬احملكــوم‬\n‫في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة ضبط ــه تق ــرر‬\n‫باألكثريــة املوافق ــة عل ــى احلكــم بعــد االجــراء االخيــر ‪ .‬وبــاهلل التوفيق‬\n                  ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n                                                                                       ‫‪112‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":107,"source_page_end":112,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f8859c669641a639433796704887f41b446545f69bb5738ba41af811765f077a","normalized_text_hash":"9c3b0f60faf575055bcd6e2120b1bd2d834c5911d0579b197d9acdf12c6c372f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p107-34227320"},{"id":"f415271f-b443-5a7d-b1d6-70ee70a46bb2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -مطالبة ورثة بيت املال ببيع عقار باملزاد العلني- بيت املال أحد الورثة -موافقة اجلهات احلكومية على البيع باملزاد العلني لكون أحد الورثة جهة حكومية -احلكم ببيع العقار باملزاد العلني وقسمة الثمن بن الورثة حسب الفريضة الشرعية .","document_number":"34190721","case_number":"33103300","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"مطالبة بيت املال -مطالبة ورثة بيت املال ببيع عقار باملزاد العلني- بيت املال أحد الورثة -موافقة اجلهات احلكومية على البيع باملزاد العلني لكون أحد الورثة جهة حكومية -احلكم ببيع العقار باملزاد العلني وقسمة الثمن بن الورثة حسب الفريضة الشرعية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34190721 :‬‬\n                         ‫َر ْق ُم الدعوى‪33103300 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34205479‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n      ‫مطالبــة بيــت املــال ‪ -‬مطالبــة ورثــة بيــت املــال ببيع عقار باملــزاد العلني‪-‬‬\n      ‫بيــت املــال أحــد الورثــة‪ -‬موافقــة اجلهــات احلكوميــة علــى البيــع باملــزاد‬\n      ‫العلنــي لكــون أحــد الورثــة جهــة حكوميــة ‪ -‬احلكــم ببيــع العقــار باملــزاد‬\n                 ‫العلنــي وقســمة الثمــن بــن الورثــة حســب الفريضــة الشــرعية ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫أقــام الورثــة دعــوى علــى بيــت املــال إللزامــه ببيــع عقــار ال ينقســم مبــزاد‬\n      ‫علنــي ألن بيــت املــال أحــد الورثــة حيــث توفيــت املــرأة التــي كانــت متلــك‬\n      ‫العقــار وانحصــر إرثهــا يف زوجهــا وابنتيهــا مبوجــب صــك حصــر ورثــه‬\n      ‫صــادر مــن احملكمــة ثــم تــويف زوجهــا وانحصــر إرثــه يف بيــت املــال وذلــك‬\n      ‫مبوجــب صــك صــادر مــن احملكمــة حضــر املدعــى عليــه منــدوب بيــت‬\n      ‫املــال وأقــر بصحــة الدعــوى وقــرر بأنــه ال مانــع لديــه مــن بيــع العقــار‬\n      ‫إذا وافقــت اجلهــات الرســمية‪ -‬اطلعــت احملكمــة علــى صــك امللكيــة‬\n      ‫وصكــوك حصــر الورثــة فوجدتهــا مطابقــة ملــا جــاء يف الدعــوى‪ -‬قــررت‬\n      ‫احملكمــة الكتابــة للجهــات الرســمية لإلفــادة عــن موافقتهــا علــى بيــع‬\n      ‫العقــار فــورد األمــر الســامي باملوافقــة علــى البيــع مبــزاد علنــي وقســمة‬\n\n‫‪113‬‬\n\f‫الثمــن بــن الورثــة حســب الفريضــة الشــرعية‪ -‬حكمــت احملكمــة ببيــع‬\n‫العقــار مبــزاد علنــي وقســمة ثمنــه بــن الورثــة ومــن ضمنهــم بيــت املــال‬\n               ‫رفــع هــذا اإلجــراء حملكمــة االســتئناف وجــرى تصديقــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪ 1433/02/09‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/02/09‬ه ـ‬\n‫حضــر بوكالتــه بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة يف‬\n‫‪1430/3/26‬ه ـ والتــي تخولــه إقامــة وســماع الدعــاوي واملرافعــة‬\n‫واملدافعــة والبيــع واإلفــراغ واســتالم الثمــن ‪ ...‬ادعــى علــى احلاضــر معــه‬\n‫مديــر بيــت املــال قائــا يف دعــواه عليــه إن مورثــة موكلــي كانــت متلــك‬\n‫العقــار الواقــع مبحلــة املعابــدة حــارة بنــي عامــر واحملــدود واملــذروع‬\n‫مبوجــب الصــك الصــادر مــن احملكمــة الكبــرى يف ‪14395/5/3‬ه ـ‬\n‫وقــد توفيــت منــذ ثالثــن ســنة وأنحصــر إرثهــا يف زوجهــا ويف بنتيهــا‬\n‫ال وارث لهــا ســواهم ‪،‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن‬\n‫احملكمــة العامــة يف ‪1430/3/5‬ه ـ ثــم تــويف يف عــام ‪1409‬ه ـ وأنحصــر‬\n‫إرثــه يف بيــت املــال وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن‬\n‫احملكمــة العامــة برقــم ‪ 3/100/224‬يف ‪1430/7/29‬ه ـ وألن العقــار‬\n‫ال ينقســم بــن الورثــة فأطلــب احلكــم ببيعــه باملــزاد العلنــي هــذه دعــواي‬\n‫وبســؤال مديــر بيــت املــال عــن دعــوى املدعــي وكالــة أجــاب قائــا إن‬\n‫بيــت املــال هــو وارث مبوجــب صــك حصــر الورثــة الصــادر مــن احملكمــة‬\n‫العامــة يف ‪1430/7/29‬ه ـ وهــو ورث الربــع مــن تركــة زوجتــه املتوفــاة‬\n\n                                                                                    ‫‪114‬‬\n\f      ‫قبلــه مبوجــب صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة يف‬\n      ‫‪1430/3/5‬ه ـ والتــي خلفــت العقــار الواقــع باملعابــدة حــارة ‪ .....‬واحملــدود‬\n      ‫واملــذروع مبوجــب صــك التملــك الصــادر مــن احملكمــة الكبــرى يف‬\n      ‫‪1395/5/3‬ه ـ وأمــا طلــب املدعــي وكالــة ببيــع العقــار باملــزاد العلنــي‬\n      ‫فأطلــب إمهالــي للرجــوع إلــى مرجعــي وإلحضــار اإلجابــة هــذه إجابتــي‬\n      ‫فطلبــت مــن املدعــي وكالــة صــك التملــك فطلــب إمهالــه ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي أصالــة ووكالــة كمــا حضــر منــدوب بيــت املــال‬\n      ‫باحملكمــة وجــرى االطــاع علــى صــك التملــك فوجدتــه صــادر مــن‬\n      ‫هــذه احملكمــة يف ‪1395/05/03‬ه ـ ويتضمــن ثبــوت متلــك لكامــل‬\n      ‫ـاء الواقــع مبحلــة املعابــدة حــارة ‪ .....‬واحملــدود شــرقا‬\n                                                                   ‫احملــدود أرضــا وبنـ ً‬\n      ‫ملــك وغربــا الســكة النافــذة وبهــا البــاب وشــما ًال ملــك وجنوبــا ملــك‪،‬‬\n      ‫واملــذروع شــماال بطــول عشــرة أمتــار وأربعــون ســنتمترا والضلــع اجلنوبــي‬\n      ‫مختلــف يبــدأ مــن الشــرق بأربعــة أمتــار وخمســن ســنتمترا ثــم ينعطــف‬\n      ‫إلــي اجلنــوب مبتــر واحــد وخمســن ســنتمترا ثــم يســتمر إلــي الغــرب‬\n      ‫مبتريــن وســتني ســنتمترا ثــم ينعطــف إلــي اجلنــوب بخمســة وعشــرين‬\n      ‫ســنتمترا ثــم يســتمر إلــي الغــرب مبتــر واحــد وســبعني ســنتمترا‪،‬‬\n      ‫والضلــع الشــرقي مختلــف يبــدأ مــن اجلنــوب بأربعــة أمتــار وســبعني‬\n      ‫ســنتمترا ثــم ينحــرف إلــي الشــمال بخــط منحنــي بقــدر ثالثــة أمتــار‬\n      ‫وســبعني ســنتمترا‪ ،‬والضلــع الغربــي مختلــف يبــدأ مــن الشــمال بســبعة‬\n      ‫أمتــار وخمســة وثالثــن ســنتمترا ثــم ينحــرف إلــي اجلنــوب مبتــر واحــد‬\n      ‫وســتني ســنتمترا ثــم ينعطــف إلــي الشــرق بعشــرة ســنتمترات ثــم يســتمر‬\n      ‫إلــى اجلنــوب مبتــر واحــد وخمســة وســبعني ســنتمترا وعــرض الســكة‬\n      ‫الغربيــة النافــذة مــن جهــة الشــمال متــران وخمســة وأربعــون ســنتمترا‬\n\n\n‫‪115‬‬\n\f‫ومــن جهــة اجلنــوب ســبعة أمتــار وتســعون ســنتمترا ‪،‬واملســاحة اإلجماليــة‬\n‫( ‪ )100.32‬م‪ 2‬مائــة متــر مربــع واثنــان وثالثــون باملائــة من املتــر املربــع ا‪.‬هـ‬\n‫كمــا جــرى اطالعــي علــى صــك حصــر الورثــة الصــادر مــن احملكمــة‬\n‫العامــة بالريــاض يف ‪1430/3/5‬ه ـ فوجدتــه يتضمــن ثبــوت وفــاة منــذ‬\n‫ثالثــن عامــا تقريبــا وانحصــار إرثهــا يف زوجهــا ويف ابنتيهــا ويف أختهــا‬\n‫ألب ال وارث لهــا ســواهم كمــا جــرى اطالعــي علــى صــك حصــر الورثــة‬\n‫الصــادر مــن احملكمــة العامــة بالريــاض يف ‪1430/7/29‬ه ـ فوجدتــه‬\n‫يتضمــن ثبــوت وفــاة وانحصــار إرثــه يف بيــت املــال أه ـ وســألت املدعــي‬\n‫عــن ســبب اختــاف اســم مورثتهــم يف الصــك عــن اســمها يف صــك‬\n‫حصــر الورثــة فقــال أننــي اطلــب إمهالــي لتصحيــح االســم ‪،‬هكــذا‬\n‫قــرر ‪ ،‬وحلــن تصحيــح االســم رفعــت اجللســة ثــم يف جلســة أخــرى حضــر‬\n‫املدعــي وكالــة كمــا حضــر مديــر بيــت املــال وقــرر املدعــي وكالــة‬\n‫قائــا لقــد مت تصحيــح اســم مورثــة موكلــي يف صــك حصــر الورثــة‬\n‫وباالطــاع علــى صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة‬\n‫بالريــاض يف ‪1430/3/5‬ه ـ فوجدتــه قــد أحلــق بــه أن صحــة اســم املتوفــاة‬\n‫هــو أه ـ وقــد جــرى االستفســار عــن ســجل صــك امللكيــة بخطابــي يف‬\n‫‪1433/3/15‬ه ـ فــوردت اإلفــادة مــن مديــر الســجالت باحملكمــة برقــم‬\n‫يف ‪1433/3/20‬ه ـ واملتضمــن مطابقــة الصــك لســجله أه ـ وبســؤال‬\n‫مديــر بيــت املــال عــن إجابتــه علــى طلــب املدعــي وكالــة بيــع العقــار‬\n‫باملــزاد العلنــي قــرر قائــا إننــا رفعنــا خطابــا بذلــك إلــى وزارة العــدل‬\n‫ولــم تردنــا اإلفــادة حتــى اآلن وأنــا أطلــب إمهالــي‪ ،‬ثــم يف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة كمــا حضــر مديــر بيــت املــال باحملكمــة وقــرر‬\n‫مديــر بيــت املــال قائــا لقــد مت رفــع اخلطــاب رقــم يف ‪1431/3/21‬ه ـ‬\n\n\n                                                                                         ‫‪116‬‬\n\f      ‫مــن احملكمــة الــى معالــي وزيــر العــدل بخصــوص طلــب املدعــن‬\n      ‫فــوردت اإلجابــة مــن فضيلــة وكيــل وزارة العــدل برقــم يف‪1434/3/6‬ه ـ‬\n      ‫وبرفقتهــا برقيــة خــادم احلرمــن الشــريفني يف‪1434/2/25‬ه ـ املتضمــن‬\n      ‫املوافقــة علــى بيــع العقــار وفقــا للتعليمــات إ‪.‬ه ـ وباالطــاع علــى برقيــة‬\n      ‫خــادم احلرمــن الشــريفني املرفقــة وجــدت هــذا نصهــا ( معالــي وزيــر‬\n      ‫العــدل الســام عليكــم ورحمــة اهلل وبركاتــه وبعــد‪ :‬اطلعنــا علــى‬\n      ‫خطــاب الــوزارة يف ‪1433/6/9‬ه ـ بخصــوص الدعــوى املقامــة مــن ضــد‬\n      ‫بيــت املــال بشــأن العقــار الواقــع يف حــي العائــد ة ملكيتــه للمتوفــاة‬\n      ‫مبوجــب حجــة االســتحكام الصــادرة مــن احملكمــة العامــة مبكــة‬\n      ‫املكرمــة بالصــك ه ـ البالغــة مســاحته (‪100/32‬م‪ )2‬مائــة متــر مربــع‬\n      ‫واثنــن وثالثــن يف املائــة مــن املتــر املربــع وحيــث ان بيــت املــال يــرث مــع‬\n      ‫ورثــة املتوفــاة الربــع يف كامــل العقــار لقــاء نصيــب زوجهــا املتــويف الــذي‬\n      ‫ال يوجــد لــه وارث ســوى بيــت املــال مبوجــب صــك حصــر اإلرث الصــادر‬\n      ‫مــن احملكمــة العامــة بالريــاض يف ‪1430/7/29‬ه ـ وتطلــب املدعيــة يف‬\n      ‫دعواهــا بيــع العقــار باملــزاد العلنــي ليأخــذ كل وارث نصيبــه وتطلــب‬\n      ‫الــوزارة التوجيــه حيــال اإلذن ببيــع العقــار املذكــور نخبركــم بأنــه ال‬\n      ‫مانــع مــن بيــع العقــار مــدار البحــث وفقــا للتعليمــات)‪ ،‬وقــرر مديــر بيــت‬\n      ‫املــال قائــا حيــث صــدرت املوافقــة علــى بيــع العقــار باملــزاد العلنــي فــان‬\n      ‫إدارة بيــت املــال موافقــة علــى ذلــك إذا كان يف البيــع غبطــة ومصلحــة‬\n      ‫هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع‬\n      ‫علــى صكــوك امللكيــة وحصــر الورثــة ولصــدور املوافقــة علــى بيــع‬\n      ‫العقــار فقــد حكمــت ببيــع العقــار املذكــور بعاليــة باملــزاد العلنــي‬\n      ‫وقســمة ثمنــه بــن الورثــة حســب الفريضــة الشــرعية وبعــرض احلكــم‬\n\n\n‫‪117‬‬\n\f‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر مديــر بيــت املــال عــدم‬\n‫القناعــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‪،‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/4/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ..‬وبعــد ‪،‬ثــم‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف بشــرح فضيلــة الرئيــس يف‬\n‫‪1434/5/28‬ه ـ علــى خطــاب رئيــس محكمــة االســتئناف مبنطقــة‬\n‫برقــم يف ‪1434/5/25‬ه ـ برفقهــا قــرار التصديــق مبوجــب القــرار يف‬\n‫‪1434/5/5‬ه ـ وهــذا نصــه ‪ -:‬احلمــد هلل والصــاة والســام علــى رســول‬\n‫اهلل وبعــد نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة جرى‬\n‫منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس‬\n‫احملكمــة العامــة وتاريــخ ‪1434/4/21‬ه ـ املشــتملة علــى الصــك وتاريــخ‬\n‫‪1434/4/17‬ه ــالصادر مــن فضيلــة الشــيخ‪ ..........‬القاضــي باحملكمــة‬\n‫العامــة املتضمــن اإلذن للمنهــي وكالــة ببيــع العقــار املذكــور يف‬\n‫االنهــاء‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،‬‬\n‫قاضــي اســتئناف ‪ ..........‬ختــم وتوقيــع ‪ ،‬قاضــي اســتئناف ‪ ..........‬ختــم‬\n‫وتوقيــع ‪ ،‬رئيــس الدائــرة ختــم وتوقيــع ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/7‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n‫املــال يف محكمــة االســتئناف جــرى منــا االطــاع املعاملــة الــواردة إلينــا‬\n\n\n                                                                                    ‫‪118‬‬\n\f      ‫شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة وتاريــخ ‪1434/4/21‬ه ـ‬\n      ‫املشــتملة علــى الصــك وتاريــخ ‪1434/4/17‬ه ـ الصــادر مــن فضيلــة‬\n      ‫الشــيخ القاضــي باحملكمــة العامــة اإلذن للمنهــي وكالــة ببيــع العقــار‬\n      ‫املذكــور يف اإلنهــاء وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                                 ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪119‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":113,"source_page_end":119,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"66c17040e9f53679df8983c8936e4222c1d5ac1477aba7f46f872c93159b7fd6","normalized_text_hash":"1087d7f3353e99019b8bf4c4bea278e7010d3fc81bfe48b34d7056ae95b1afe5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p113-34190721"},{"id":"5166c429-afb5-5271-b7e4-ae2bbb5983f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبه بيت املال -املطالبة برفع اليد عن عقار مملوك ملورث املدعي وتسليمه وأجرته إليه -تقدمي املدعي صك يؤيد دعواه -إيجابية قرار هيئة النظر للمدعي -موافقة بيت املال على تسليم العقار وأجرته للمدعن حال ثبوت احلق -إلزام بيت املال برفع يده عن العقار وتسليمه وأجرته للمدعن .","document_number":"34314669","case_number":"33141773","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/8","year":"1434","subject":"مطالبه بيت املال -املطالبة برفع اليد عن عقار مملوك ملورث املدعي وتسليمه وأجرته إليه -تقدمي املدعي صك يؤيد دعواه -إيجابية قرار هيئة النظر للمدعي -موافقة بيت املال على تسليم العقار وأجرته للمدعن حال ثبوت احلق -إلزام بيت املال برفع يده عن العقار وتسليمه وأجرته للمدعن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/9/8 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34314669 :‬‬\n                   ‫َر ْق ُم الدعوى‪33141773 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n         ‫‪ 34367263‬تاريخه‪1434/11/24 :‬هـ‬\n\n\n‫مطالبــه بيــت املــال‪ -‬املطالبــة برفــع اليــد عــن عقار مملوك ملــورث املدعي‬\n‫وتســليمه وأجرتــه إليــه‪ -‬تقــدمي املدعــي صــك يؤيــد دعــواه‪ -‬إيجابيــة‬\n‫قــرار هيئــة النظــر للمدعــي‪ -‬موافقــة بيــت املــال علــى تســليم العقــار‬\n‫وأجرتــه للمدعــن حــال ثبــوت احلــق ‪ -‬إلــزام بيــت املــال برفــع يــده عــن‬\n                                         ‫العقــار وتســليمه وأجرتــه للمدعــن ‪.‬‬\n\n\n\n\n                  ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n‫أقــام وكيــل ورثــة دعــوى علــى بيــت املــال يطالبــه برفــع يــده التــي وضعهــا‬\n‫علــى عقــار لينتقــل إلــى موكليــه بــاإلرث وتســليم العقار وأجرتــه املاضية‬\n‫إليهــم ‪ -‬قــرر املدعــى عليــه منــدوب بيــت املال موافقته على تســليم العقار‬\n‫وأجرتــه إذا ثبــت لــدى احملكمــة اســتحقاق املدعــن‪ -‬قــدم املدعــي‬\n‫صكــوك التملــك وحصــر الورثــة وبعــد اطــاع احملكمــة عليهــا تبــن‬\n‫أنهــا مطابقــة ملــا يدعــي بــه املدعــي فكتبــت احملكمــة لهيئــة النظــر‬\n‫للوقــوف علــى العقــار وتطبيــق الصــك عليــه بحضــور الطرفــن وقــد‬\n‫قــررت هيئــة النظــر أن الصــك مطابــق للواقــع لــذا حكمــت احملكمــة‬\n‫برفــع يــد بيــت املــال عــن العقــار املذكــور يف الدعــوى وتســليم أجرتــه‬\n\n                                                                                       ‫‪120‬‬\n\f      ‫للمدعــن لــم يقنــع مديــر بيــت املــال يف احلكــم فتــم رفعــه إلــى محكمــة‬\n                                                       ‫االســتئناف ومت تصديقــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنا من فضيلة رئيس احملكمة العامة وتاريخ‬\n      ‫‪1433/02/24‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/02/24‬ه ـ‬\n      ‫ففــي يــوم اإلثنــن املوافق‪1433/04/12‬ه ـ افتتحــت اجللســة وفيهــا حضر‬\n      ‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي ‪ ..........‬بصفتــه وكيــا‬\n      ‫عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n      ‫برقــم يف ‪1432/3/30‬ه ـ املخولــة لــه املرافعــة واملدافعــة والصلــح وعــن‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n      ‫يف ‪1432/3/30‬ه ـ املخولــة لــه املرافعــة واملدافعــة واإلقــرار والصلــح‬\n      ‫والتنــازل وعــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة املكرمــة برقــم يف ‪1431/1/18‬ه ـ وعــن و و مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة برقــم يف ‪1428/4/25‬ه ـ املخولــة‬\n      ‫لــه املرافعــة واملدافعــة واإلقــرار يف ‪1431/1/13‬ه ـ املخولــة لــه املرافعــة‬\n      ‫واملدافعــة واإلقــرار والصلــح وعــن أصالــة عــن نفســها وبواليتهــا عــن‬\n      ‫أصالــة عــن نفســها وبواليتهــا علــى أبنائهــا القصــر مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة برقــم يف ‪1427/7/1‬ه ـ املخولــة لــه‬\n      ‫املرافعــة واملدافعــة واإلقــرار وحضــر حلضــوره مدير بيت املــال باحملكمة‬\n      ‫وبســؤال املدعــي وكالــة عــن دعــواه ادعــى بقولــه إن مورثــة موكلــي‬\n      ‫خلفــت مــن ضمــن تركتهــا القطعــة الكائنــة ‪ .....‬واململوكــة بالصــك‬\n\n‫‪121‬‬\n\f‫الصــادر مــن هــذه احملكمــة يف ‪1386/5/11‬ه ـ واملقــام عليهــا عمــارة‬\n‫وحدودهــا بحســب الصــك شــرقا دار وغربــا الشــارع وبــه البــاب وواجهــة‬\n‫الــدار وأطوالهــا مــن الشــمال إلــى اجلنــوب ممــا يلــي الغــرب ثالثــة أمتــار ثم‬\n‫ينعطــف إلــى جهــة الشــرق بقــدر متــر واحــد وخمســة عشــر ســنتم يســتمر‬\n‫يف الطــول الغربــي إلــى جهــة اجلنــوب بقــدر متــر واحــد وســتني ســم ثــم‬\n‫ينعطــف إلــى جهــة الشــرق بقــدر متــر واحــد وعشــرين ســم ثــم يســتمر يف‬\n‫الطــول الغربــي إلــى جهــة اجلنــوب بقــدر ثالثــة أمتــار وثالثــن ســم وممــا‬\n‫يلــي الشــرق ســتة أمتــار وخمســة وســبعون ســم وعرضــا مــن الشــرق إلــى‬\n‫الغــرب ممــا يلــي اجلنــوب ســبعة أمتــار وســبعون ســم وممــا يلــي الشــمال‬\n‫عشــرة أمتــار وســتون ســم ومجمــوع مســاحته ســبعة وســتون متــرا مربعــا‬\n‫وأربعــة وأربعــون باملائــة مــن املتــر املربــع وقــد وضــع بيــت املــال باحملكمــة‬\n‫يــده علــى هــذا العقــار وقــام بتأجيــره وهــو يســتلم أجرتــه حتــى اآلن أطلــب‬\n‫احلكــم عليــه برفــع يــده عــن العقــار وتســليمه ملوكلــي وإلزامــه بتســليم‬\n‫اإليجــارات الســابقة ملوكلــي هــذه دعــواي وبعرضهــا علــى املدعــى عليــه‬\n‫طلــب اإلمهــال لإلجابــة فأجبتــه لطلبــه كمــا طلبــت مــن املدعــي إحضــار‬\n‫صكــوك حصــر اإلرث فاســتعد بذلــك وعليــه رفعــت اجللســة ويف جلســة‬\n‫أخــرى حضــر فيهــا الطرفــان وبســؤال املدعــي عــن صكــوك حصــر‬\n‫اإلرث أبــرز الصــك الصــادر مــن هــذه احملكمــة يف ‪1388/10/8‬ه ـ‬\n‫وباالطــاع عليــه وجــد يتضمــن وفــاة بتاريــخ ‪1388/8/4‬ه ـ وانحصــار‬\n‫إرثهــا يف بناتهــا كمــا أبــرز الصــك الصــادر مــن هــذه احملكمــة يف‬\n‫‪1396/6/21‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة ‪ ..........‬تاريــخ‬\n‫‪1396/5/10‬ه ـ وانحصــار إرثهــا يف زوجهــا ويف أوالدهــا املرزوقــن منــه‬\n‫وهــم كمــا أبــرز الصــك الصــادر مــن احملكمــة العامــة باملدينــة املنــورة‬\n\n\n                                                                                          ‫‪122‬‬\n\f      ‫يف ‪1432/1/19‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1431/4/6‬ه ـ وانحصــار إرثهــا يف أوالدهــا و ‪ ..........‬وأوالد ‪..........‬‬\n      ‫وأوالد ‪ ..........‬كمــا أبــرز الصــك الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫يف ‪1424/11/26‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1424/11/3‬ه وانحصــار إرثــه يف أوالده و ‪ ..........‬و ‪ ..........‬و ‪..........‬‬\n      ‫و ‪ ..........‬واملرزوقــن لــه مــن زوجتــه املتوفــاة حــال حياتــه ويف أوالده‬\n      ‫أيضــا املرزوقــن لــه مــن مطلقتــه كمــا أبــرز الصــك الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 11/30/28‬يف ‪1420/7/14‬ه ـ وباالطــاع عليــه وجــد‬\n      ‫يتضمــن ثبــوت وفــاة ‪ ..........‬بتاريــخ ‪1420/6/15‬ه ـ وانحصــار إرثــه يف‬\n      ‫والــده ويف زوجتــه ويف أوالده منهــا والبالغــن والقاصريــن كمــا أبــرز‬\n      ‫الصــك الصــادر مــن هــذه احملكمــة يف ‪1425/2/14‬ه ـ وباالطــاع‬\n      ‫عليــه وجــد يتضمــن ثبــوت وفــاة ‪ ..........‬بتاريــخ ‪1415/7/11‬ه ـ وانحصار‬\n      ‫إرثهــا يف أوالدهــا البالغــن املتوفــى قبلهــا كمــا أبــرز الصــك الصــادر‬\n      ‫مــن هــذه احملكمــة يف ‪1425/2/6‬ه ـ وباالطــاع عليــه وجــد يتضمــن‬\n      ‫ثبــوت وفــاة كمــا أبــزر الصــك الصــادر مــن هــذه احملكمــة برقــم ‪24‬‬\n      ‫يف ‪1425/2/9‬ه ـ وباالطــاع عليــه وجــد أنــه يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1402/4/25‬ه ـ وانحصــار إرثهــا يف والدتهــا ويف اخوتهــا األشــقاء كل‬\n      ‫مــن كمــا أبــرز الصــك الصــادر مــن هــذه احملكمــة برقــم ‪12/170‬‬\n      ‫يف ‪1397/8/3‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1397/6/24‬ه ـ وانحصــر إرثــه الشــرعي يف زوجتــه الباقيــة يف عصمــة‬\n      ‫نكاحــه إلــى حــن وفاتــه ويف أوالده منهــا وهــم البالغــون القاصــران‬\n      ‫وبســؤال املدعــى عليــه عمــا اســتمهل مــن أجلــه قــال إنــه مت البحــث عــن‬\n      ‫مســتند اســتالم بيــت املــال للعقــار وحتــى اآلن لــم جنــده نظــرا لكــون‬\n\n\n‫‪123‬‬\n\f‫االســتالم قــد مضــى عليــه حوالــي أربعــن ســنة وأطلــب إعطائــي مهلــة‬\n‫أخــرى لإلجابــة فأجيــب لطلبــه وعليــه رفعــت اجللســة ويف جلســة أخــرى‬\n‫حضــر الطرفــان وبســؤال املدعــى عليــه عمــا اســتمهل مــن أجلــه قــال إنــه‬\n‫بعــد البحــث وجــد أن املبالــغ التــي مت اســتالمها مــن قبــل بيــت املــال مائــة‬\n‫وثالثــون ألفــا وتســعمائة وأربعــة وســتون ريــاال وعشــرون هللــة أمــا ســند‬\n‫اســتالم بيــت املــال للعقــار فقــد مت البحــث عنــه مــرارا ولــم نعثــر عليــه‬\n‫علمــا أن االســم املســجل لدينــا مالكــة العقــار هــو كمــا هــو مذكــور‬\n‫يف صــك امللكيــة كمــا أن املســتأجر للعقــار هــو مــن ضمــن الورثــة‬\n‫وكبيــر يف الســن وأطلــب حضــوره لســماع مــا لديــه هكــذا أجــاب‬\n‫وبــرد ذلــك علــى املدعــي وكالــة قــال ال علــم لــي مبقــدار املبالــغ املســتلمة‬\n‫وموكلــي راضــون باملبلــغ املذكــور وأمــا اختــاف االســم بــن الصــك‬\n‫ومــا هــو لــدى بيــت املــال فــا عالقــة ملوكلــي بــه وأمــا مــا ذكــره عــن‬\n‫املســتأجر فصحيــح وأنــا مســتعد بإحضــاره متــى طلبتــم هكــذا أجــاب‬\n‫وعنــد وصــول القضيــة إلــى هــذا احلــد وملزيــد مــن التحقــق فقــد قــررت‬\n‫رفــع اجللســة للكتابــة لهيئــة النظــر باحملكمــة للوقــوف علــى العقــار‬\n‫املذكــور بحضــور ممثــل للطرفــن وتطبيــق الصــك عليــه واإلفــادة عــن‬\n                  ‫مطابقتــه مــن عدمــه وتأجلــت اجللســة حتــى ورود اجلــواب‪.‬‬\n‫ويف جلســة أخــرى لــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة خلــف‬\n‫فضيلــة الشــيخ ‪ ..........‬بنــاء علــى خطــاب فضيلــة رئيــس احملكمــة يف‬\n‫‪1434/04/27‬ه ـ املبنــي علــى قــرار رئيــس املجلــس األعلــى للقضــاء‬\n‫رقــم يف ‪1434/04/23‬ه ـ واملبنــي علــى قــرار املجلــس األعلــى للقضــاء‬\n‫رقــم يف ‪1434/4/13‬ه ـ عليــه افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه أصالــة وبتــاوة مــا مت ضبطــه ســابقا عليهمــا‬\n\n\n                                                                                        ‫‪124‬‬\n\f      ‫صادقــا عليــه ثــم طلبــت مــن املدعــي وكالــة احضــار صكــوك وكاالتــه‬\n      ‫وصكــوك حصــر اإلرث علــى مــا ذكــر ســابقا عليــه رفعــت اجللســة ويف‬\n      ‫جلســة أخــرى حضــر فيهــا املدعــي وكالــة كمــا حضــر مديــر بيــت‬\n      ‫املــال وبســؤال املدعــي وكالــة عمــا اســتمهل مــن أجلــه أبــرز صكــوك‬\n      ‫حصــر اإلرث وصكــوك الــوكاالت املذكــورة ســابقا وباالطــاع‬\n      ‫عليهــا وجدتهــا مطابقــة ملــا ذكــر كمــا وردنــا يف هــذه اجللســة قــرار‬\n      ‫هيئــة النظــر يف ‪1434/05/19‬ه ـ واملتضمــن مــا نصــه (جــرى الوقــوف‬\n      ‫بالطبيعــة علــى املوقــع محــل النــزاع بحضــور الطرفــن وبرفقــة عمــدة‬\n      ‫حــي املســفلة ومعرفــن منتخبــن مــن قبلــه وجــرى أخــذ تعريفهــم املرفــق‬\n      ‫علــى الصــك رقــم ‪ 10/15‬يف ‪1386/5/11‬ه ـ ومبقارنــة مــا ذكــره‬\n      ‫املعرفــن باحلــدود املذكــورة بالصــك واحلــدود مبوجــب الطبيعــة تبــن‬\n      ‫مطابقــة الصــك املذكــور علــى العقــار محــل الدعــوى اخلــاص بورثــة ‪....‬‬\n      ‫وجــرى إعــداد الرفــع املســاحي املرفــق املعــد واملعتمــد مــن قبــل مكتــب‬\n      ‫‪ ....‬لالستشــارات الهندســية ) وبعــرض مــا جــاء يف قــرار هيئــة النظــر على‬\n      ‫مديــر بيــت املــال احلاضــر أجــاب قائــا إن بيــت املال يضع يــده على العقار‬\n      ‫املذكــور يف قــرار هيئــة النظــر وال أعلــم عــن مطابقــة الصــك لــه من عدم‬\n      ‫ذلــك كمــا يضــع يــده علــى مبلــغ وقــدره مائــة وثالثــون ألفــا وتســعمائة‬\n      ‫وأربعــة وســتون ريــاال وعشــرون هللــة متثــل أجــرة هــذا العقــار حتــى تاريــخ‬\n      ‫‪1433/01/22‬ه ـ وال مانــع لــدى بيــت املــال مــن تســليم العقــار املذكــور‬\n      ‫وأجرتــه املذكــورة للمدعيــن أصالــة متــى مــا ثبــت اســتحقاقهم كمــا‬\n      ‫جــرى االطــاع علــى صــك امللكيــة املشــار إليــه يف الدعــوى فوجدتــه‬\n      ‫يتضمــن مــا ذكــر ســابقا كمــا جــرى االستفســار عنــه مبوجــب خطابنــا‬\n      ‫رقــم يف ‪1433/5/22‬ه ـ فوردنــا جــواب مديــر الســجالت باحملكمــة‬\n\n\n‫‪125‬‬\n\f‫املتضمــن ( ال يوجــد علــى ســجل الصــورة الضوئيــة املرفقــة ســوى مــا‬\n‫أحلــق عليــه ) فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا جــاء يف‬\n‫قــرار هيئــة النظــر وملــا جــاء يف إقــرار كل مــن املدعيــان جلميــع مــا ســبق‬\n‫حكمــت علــى بيــت املــال برفــع يــده عــن العقــار املذكــور يف الدعــوى‬\n‫وتســليمه وتســليم أجرتــه البالــغ قدرهــا مائــة وثالثــون ألفــا وتســعمائة‬\n‫وأربعــة وســتون ريــاال وعشــرون هللــة للمدعيــن وبعــرض احلكــم علــى‬\n‫الطرفــن قنــع بــه املدعــي وكالــة ولــم يقنــع بــه املدعــى عليــه بــدون الئحــة‬\n‫اعتراضيــة عليــه أمــرت برفــع كامــل املعاملــة حملكمــة االســتئناف‬\n‫لتمييــز احلكــم حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس املوافــق ‪1434/12/26‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــي املعاملــة مــن محكمــة االســتئناف يف‬\n‫‪1434/12/18‬ه ـ مرفقــا بهــا القــرار رقــم يف ‪1434/11/24‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة‬\n‫علــى احلكــم واهلل املوفــق قاضــي اســتئناف ‪ ..........‬توقيعــه وختمــه‬\n‫قاضــي اســتئناف ‪ ..........‬توقيعــه وختمــه رئيــس الدائــرة ‪ ..........‬توقيعــه‬\n‫وختمــه) لــذا جــرى حتريــره حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/26‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبكــة املكرمــة برقــم وتاريــخ ‪1434/10/18‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة العامــة مبكــة‬\n\n\n                                                                                        ‫‪126‬‬\n\f      ‫املكرمــة وتاريــخ ‪1434/9/8‬ه ـ ‪ ،‬املتضمــن دعــوى وكالــة ضــد بيــت‬\n      ‫املــال‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                   ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪127‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":120,"source_page_end":127,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"73933f7c684e39cb93b28bc748283d440faeb3d9c82b71814805baf20f50c079","normalized_text_hash":"dd323e5b03e464a1147329b16b7cc8f6258ced8185b7986a5966a58c1962d850","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p120-34314669"},{"id":"e3915450-d807-5f14-bf10-ccc106db6ae1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -قيام املدعي بوضع بضاعة لدى شركة مقابل قيام الشركة ببيع البضاعة بنسبة ربح -هروب أصحاب الشركة وترك البضاعة داخل احملات -أخذ بيت املال البضاعة تنفيذ ا حلكم -مطالبة املدعي بيت املال بتسليمه البضاعة -شهادة الشهود العدول -إلزام بيت املال بتسليم البضاعة للمدعي .","document_number":"341325","case_number":"33305874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة والقائم بعمل فضيلة الشيخ","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/3","year":"1434","subject":"مطالبة بيت املال -قيام املدعي بوضع بضاعة لدى شركة مقابل قيام الشركة ببيع البضاعة بنسبة ربح -هروب أصحاب الشركة وترك البضاعة داخل احملات -أخذ بيت املال البضاعة تنفيذ ا حلكم -مطالبة املدعي بيت املال بتسليمه البضاعة -شهادة الشهود العدول -إلزام بيت املال بتسليم البضاعة للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫تاريخه‪1434/1/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪341325 :‬‬\n                   ‫َر ْق ُم الدعوى‪33305874 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34203439‬تاريخه‪1434/5/1 :‬هـ‬\n\n\n‫مطالبــة بيــت املــال‪ -‬قيــام املدعــي بوضــع بضاعــة لــدى شــركة مقابــل‬\n‫قيــام الشــركة ببيــع البضاعــة بنســبة ربــح‪ -‬هــروب أصحــاب الشــركة‬\n‫وتــرك البضاعــة داخــل احملــات‪ -‬أخــذ بيــت املــال البضاعــة تنفيــذ ًا‬\n‫حلكــم‪ -‬مطالبــة املدعــي بيــت املــال بتســليمه البضاعــة‪ -‬شــهادة الشــهود‬\n                 ‫العــدول‪ -‬إلــزام بيــت املــال بتســليم البضاعــة للمدعــي ‪.‬‬\n\n\n\n\n                      ‫‪-1‬قوله صلى اهلل عليه وسلم(ال ضرر وال ضرار)‬\n                                          ‫‪-2‬قاعدة الضرر يزال ويرفع‬\n‫‪-3‬املــادة ‪76‬مــن نظــام املرافعــات الشــرعية الفقــرة ‪ 8‬مــن الالئحــة‬\n                                                           ‫ا لتنفيذ يــة‬\n\n\n\n\n‫أقــام رجــل دعــوى علــى بيــت املــال يطالبــه بتســليم البضاعــة عبــارة عــن‬\n‫أقمشــة نســائية وديكــور خشــبي وضــع بيــت املــال يــده عليهــا مبوجــب‬\n‫صــك مكتســب للقطعيــة يتضمــن احلكــم بفتــح احملــات التــي توجــد‬\n‫بهــا البضاعــة وجــرد محتوياتهــا وحفظهــا وبيــع مــا يخشــى تلفــه‪ ،‬صــادق‬\n‫املدعــى عليــه علــى وجــود املنقــوالت لــدى بيــت املــال وال يعلــم مــن هــو‬\n‫مســتحقها وقــرر أنــه إذا ثبــت لــدى احملكمــة أنهــا للمدعــي فــا مانــع‬\n\n                                                                                    ‫‪128‬‬\n\f      ‫لديــه مــن تســليمها لــه‪ ،‬بطلــب البينــة مــن املدعــي‪ ،‬أحضــر شــهود ًا‬\n      ‫شــهدوا بصحــة دعــوى املدعــى ومت تزكيــة الشــهود‪ ،‬كمــا جــرى اطالع‬\n      ‫احملكمــة علــى الصكــوك ومحاضــر اجلــرد اخلاصــة بالبضاعة فوجدت‬\n      ‫مطابقــة ملــا يدعــي بــه املدعــي وحيــث قــرر مديــر بيــت املــال أن البضاعــة‬\n      ‫موجــودة لديــه وشــهدت البينــة بذلــك لــذا حكمــت احملكمــة علــى بيــت‬\n      ‫املــال بتســليم املدعــى بضاعتــه‪ ،‬اعتــرض املدعــى عليــه‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد اهلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة العامــة‬\n      ‫مبكــة املكرمــة والقائــم بعمــل فضيلــة الشــيخ ‪ ..........‬وبناء على املعاملة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n      ‫وتاريــخ ‪1433/05/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ ..........‬وتاريــخ‬\n      ‫‪1433/05/02‬ه ـ يف يــوم الســبت ‪1433/06/14‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 20‬وفيهــا حضــر ‪ ..........‬ســعودي بالســجل املدنــي رقــم‬\n      ‫ا عــن ‪ ..........‬ســعودي مبوجــب الوكالــة الصــادرة‬    ‫‪ ..........‬بصفتــه وكيـ ً‬\n      ‫مــن كتابــة العــدل الثانيــة برقــم ‪ ..........‬يف ‪1432/10/16‬ه ـ جلــد ‪3550‬‬\n      ‫وحضــر حلضــوره ‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬وبســؤال‬\n      ‫املدعــي عــن دعــواه قــال لقــد قــام موكلــي بوضــع بضاعتــه وهــي عبــارة‬\n      ‫عــن أقمشــة نســائية باملوقــع باإلضافــة إلــى تخشــيبة ديكــور مقابــل‬\n      ‫أن تقــوم الشــركة ببيــع البضاعــة مقابــل نســبة ‪ %30‬مــن الربــح وفعــا‬\n      ‫قامــت الشــركة ببيــع بعــض األقمشــة إال أن الشــركة املدعــى عليهــا‬\n      ‫شــركة ‪ .....‬قــد تركــوا احملــات ولــم يعثــر لهــم علــى أثــر والبضاعــة‬\n      ‫املذكــورة وغيرهــا ال تــزال يف محــل الشــركة الواقــع يف ‪ ........‬وقــد‬\n\n‫‪129‬‬\n\f‫صــدر صــك مــن ‪ ....‬يف ‪1431/7/8‬ه ـ وصــدق مــن محكمــة االســتئناف‬\n‫برقــم يف ‪1432/2/6‬ه ـ يتضمــن احلكــم علــى املدعــى عليهــا بفتــح‬\n‫احملــات وجــرد محتوياتهــا وحفظهــا وبيــع مــا هــذه احملكمــة يخشــى‬\n‫تلفــه وإن البضاعــة حالي ـ ًا لــدى بيــت املــال يف احملكمــة العامــة يف‬\n‫أطلــب إلزامهــم بتســليمي البضاعــة وهــي عبــارة عــن أقمشــة نســائية‬\n‫وديكــور خشــبي هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n‫مــا ذكــره املدعــي يف دعــواه غيــر صحيــح حيــث أنــه يوجــد منقــوالت‬\n‫كثيــرة غيرهــا مت جردهــا مبوجــب محضــر اســتالم املنقــوالت برقــم‬\n‫‪ ..........‬يف ‪1432/08/29‬ه ـ تنفيــذ ًا للصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ......‬يف ‪1431/7/8‬ه ـ وال نعلــم عــن صحــة دعــوى املدعــي فيمــا يدعــي‬\n‫بــه لكونهــا حفظــت لــدى بيــت املــال باســم الشــركة املدعــى عليهــا بنــاء‬\n‫علــى الصــك املذكــور ولكــن إذا ثبــت لــدى فضيلتكــم أن لــه حــق فيما‬\n‫يدعــي بــه فــا مانــع مــن تســليمه بعــد صــدور احلكــم الشــرعي مــن ذلــك‬\n‫وتصديــق احلكــم مــن محكمــة االســتئناف وأمــا بالنســبة للديكــورات‬\n‫الثابتــة فلــم تســتلم مــن قبــل بيــت املــال مبوجــب احملضــر املعــد مــن قبــل‬\n‫مندوبيهــا رقــم بــدون بتاريــخ ‪1432/2/29‬ه ـ املبنــي علــى مشــهد مديــر‬\n‫عــام املبيعــات والتســويق بشــركة إدارة وإمنــاء املشــاريع رقــم بــدون‬\n‫وتاريــخ ‪1432/07/05‬ه ـ املرفــق صورتــه املتضمــن مــن إن املكيفــات‬\n‫والســلم الكهربائــي وجميــع التجهيــزات واألنــوار والديكــورات الثابتــة‬\n‫املوجــودة باحملــات تعتبــر حــق للطــرف األول (املؤجــر) وتــؤل ملكيتهــا‬\n‫إليــه كمــا مت االتفــاق عليــه مبوجــب عقــد اإليجــار هــذه إجابتــي ثــم‬\n‫رفعــت اجللســة ويف جلســة الحقــه لــدي أنــا القاضــي يف احملكمــة العامــة‬\n‫وفيهــا حضــر املدعــي وكالــه كمــا حضــر منــدوب بيــت املــال وبســؤال‬\n\n\n                                                                                       ‫‪130‬‬\n\f      ‫املدعــي عــن بينتــه قــال لقــد أحضــرت بينتــي وهــم شــهود أطلــب ســماع مــا‬\n      ‫ا أشــهد بــأن‬ ‫لديهــم ثــم حضــر [وشــهد كل واحــد منهمــا مبفــرده قائ ـ ً‬\n      ‫املدعــي قــد اســتأجر مــن الشــركة املدعــى عليها ‪ ........‬مــن محلهم الذي‬\n      ‫اســتأجروه يف أبــراج البيــت بجــوار احلــرم وذلــك لبيــع أقمشــة نســائية مــع‬\n      ‫وضعهــم للديكــور علــى أن تكــون األربــاح ثالثــن باملائــة للمدعى عليها‬\n      ‫وقــد تركــت الشــركة املوقــع وأقفلــت احملــل وبداخلــه البضاعــة وال‬\n      ‫يوجــد أقمشــة نســائية غيرهــا يف املوقــع هــذا مــا لــدي وبــه أشــهد ثــم عدل‬\n      ‫الشــهود مــن قبــل مينــي اجلنســية مبوجــب اإلقامــة ومينــي اجلنســية مبوجــب‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث قــرر مديــر‬  ‫اإلقامــة فبنـ ً‬\n      ‫بيــت املــال مــن أن املوجــودات لديــه هــي البضاعــة فقــط دون الديكــور‬\n      ‫وخــاف هــو ملــا جــاء يف شــهادة الشــهود املعدلــن التعديــل الشــرعي وملــا‬\n      ‫جــاء يف قــرار محكمــة االســتئناف رقــم يف ‪1433/3/12‬ه ـ واملتضمــن‬\n      ‫أن للمدعــي أن يقيــم دعــوى ضــد بيــت املــال وملــا تضمنــه الصــك املشــار‬\n      ‫لــه أعــاه مــن احلكــم بالبيــع وجــرد احملتويات‪....‬الــخ وملــا روي عــن النبــي‬\n      ‫صلــى اهلل عليــه وســلم أنــه قــال (ال ضــرر وال ضــرار ) أخرجــه مالــك‬\n      ‫وأحمــد والدارقطنــي ولــه طــرق يشــد بعضهــا بعض ـ ًا وألن الضــرر يــزال‬\n      ‫ويرفــع لذلــك كلــه فقــد حكمــت علــى بيــت املــال بتســليم املدعــي‬\n      ‫بضاعتــه وهــي األقمشــة النســائية املوجــودة يف املوقــع املذكــور أعاله يف‬\n      ‫دعــواه واحملفوظــة لــدى بيــت املــال وبعــرض احلكــم علــى الطرفــن قنــع‬\n      ‫بــه املدعــي ولــم يقنــع مديــر بيــت املــال وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫ـاء علــى املــادة ‪ 8/76‬مــن‬  ‫لتدقيقــه بــدون الئحــة وعليــه أمــرت برفعــه بنـ ً‬\n      ‫نظــام املرافعــات الشــرعية وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                  ‫محمــد وآلــه وصحبــه حــرر يف ‪1434/01/03‬هــ‪.‬‬\n\n\n‫‪131‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫ففــي يــوم األحــد املوافــق ‪1434/4/21‬ه افتتحــت اجللســة الســاعة ‪09:20‬‬\n‫وفيهــا عــادت املعاملــة مــن محكمــة اإلســتئناف مبكــة املكرمــة‬\n‫وبرفقهــا قــرار املالحظــة يف ‪1434/01/19‬ه ـ املتضمن وبدراســة الصك‬\n‫وصــورة ضبطــه تقــرر باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي‪:‬‬\n‫‪ -1‬اإلطــاع علــى محضــر اســتالم املنقــوالت ورصــد مضمونــه وأخــذ‬\n‫مــا لــدى طــريف القضيــة عنــه ‪ -2‬اإلشــارة إلــى تعميــد منــدوب بيــت املــال‬\n‫‪ -3‬اإلطــاع علــى عقــد اإليجــار املبــرم بــن املدعــي وشــركة بــال ورصــد‬\n‫مضمونــه ‪ -4‬البــد أن تكــون الدعــوى محــررة التحريــر الشــرعي الــذي‬\n‫يعلــم مبوجبــه املدعــى فيــه قاضــي اســتئناف ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف موافــق علــى احلكــم ختمــه وتوقيعــه رئيــس الدائــرة ختمــه‬\n‫وجوابــا علــى مــا ذكــره أصحــاب الفضيلــة وفقنــي اهلل وإياهــم‬\n                                                                ‫ً‬     ‫وتوقيعــه‬\n‫لــكل خيــر أقــول لقــد جــرى اإلطــاع علــى عقــد اإليجــار املبــرم بــن‬\n‫الطرفــن ومرفــق صــورة منــه يف أوراق املعاملــة وقــد جــرت الكتابــة‬\n‫ملديــر بيــت املــال فوردنــا خطابهــم يف ‪1434/4/20‬ه ـ ونصــه [إشــارة إلى‬\n‫كتــاب فضيلتكــم رقــم ‪34/842527‬يف ‪1434/4/7‬ه ـ بشــأن الدعــوى‬\n‫املقامــة لــدى فضيلتكــم مــن املدعــي ضــد املنقــوالت التــي مت جردهــا‬\n‫مــن قبلنــا يف احملــل الكائــن يف أبــراج البيــت مبكــة املكرمــة املؤجــر‬\n‫مــن قبــل شــركة علــى شــركة الغائبــة والصــادر فيهــا الصــك رقــم يف‬\n‫‪1434/1/4‬ه ـ وطلــب فضيلتكــم إجــراء مــا يلــزم حيــال قــرار محكمــة‬\n‫اإلســتئناف املرفــق صورتــه برقــم يف ‪1434/1/19‬ه ـ ‪...‬الــخ عليــه‬\n‫ـبقا جــرد إجمالــي مبوجــب اجلــرد رقــم‬   ‫نفيدكــم بأنــه مت جردهــا مسـ ً‬\n‫‪ 7/470‬يف ‪1432/8/29‬ه ـ املرفــق صورتــه بنــاء علــى الصــك الصــادر‬\n\n\n                                                                                    ‫‪132‬‬\n\f      ‫ـابقا الشــيخ يف ‪1431/7/8‬ه ـ‬  ‫مــن فضيلــة القاضــي بهــذه احملكمــة سـ ً‬\n      ‫املتضمــن احلكــم بفتــح احملــل وجــرد مــا فيــه مــن احملتويــات وحفظهــا يف‬\n      ‫ببيــت املــال وبيــع مــا يخشــى تلفــه وحفــظ قيمتــه حلــن مراجعــة صاحبــه‬\n      ‫ولكــون املدعــي يدعــي باألقمشــة عليــه فقــد جــرى بعــث مندوبــي بيــت‬\n      ‫املــال بحضــور املدعــي وكالــة املذكــورة أســماؤهم يف احملضــر املرفــق‬\n      ‫حلصــر عــدد األقمشــة املدعــى بهــا فوجــد أن عددهــا (‪ )751‬ســبعمائة‬\n      ‫وواحــد وخمســون لفــة قمــاش فقــط مبوجــب احملضــر املرفــق وأنهــا‬\n      ‫الزالــت حتــت يــد بيــت املــال حتــى تاريخــه ] ومرفــق بــه محضــر هــذا‬\n      ‫نصــه [ احلمــد هلل رب العاملــن والصــاة والســام علــى خيــر خلــق اهلل‬\n      ‫أجمعــن أمــا بعــد فإنــه يف يــوم الســبت املوافــق ‪1434/4/13‬ه ـ ويف متــام‬\n      ‫صباحــا مت فتــح املســتودع املســتأجر مــن قبــل شــركة‬‫ً‬      ‫الســاعة التاســعة‬\n      ‫حلفــظ مخلفــات وذلــك حلصــر وعــد مــا يخــص املدعــي وكالــة مبوجــب‬\n      ‫الوكالــة يف ‪1432/10/16‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫وقــد مت فتــح املشــروع بحضــور كل مــن مندوبــي بيــت املــال ومنــدوب‬\n      ‫شــركة و والوكيــل الشــرعي بنــاء علــى خطــاب فضيلــة القاضــي‬\n                                                           ‫ً‬\n      ‫وحفظــا للواقــع جــرى اعــداد هــذا احملضــر وبــاهلل‬       ‫يف ‪1434/4/7‬ه ـ‬\n      ‫علمــا بــأن نتيجــة هــذا العــد هــي ‪ 751‬لفــة قمــاش واهلل ولــي‬ ‫التوفيــق ً‬\n      ‫أيضــا صــورة مــن محضــر اســتالم املنقــوالت اخلــاص‬ ‫التوفيــق] ومرفــق بــه ً‬\n      ‫بشــركة‪ ...‬وعليــه فلــم يظهــر لــي مــا يوجــب العــدول عمــا حكمــت بــه‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/04/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫خلــف الشــيخ يــوم األحــد املوافــق‪ 1434/05/19‬ه ـ افتتحــت اجللســة‬\n\n\n‫‪133‬‬\n\f‫الســاعة ‪ 10.15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫قــرار التصديــق وتاريــخ ‪1434/05/01‬ه ـ املتضمــن وبدراســة احلكــم‬\n‫وصــورة ضبطــه والئحتهــا االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف لــي وجهــة‬\n‫نظــر ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه واهلل املوفــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه حــرر يف ‪1434/05/19‬هــ‪.‬‬\n‫احلمد هلل وحده وبعد لدي أنا ‪ ..........‬القاضي باحملكمة العامة مبكة‬\n‫املكرمــة خلــف الشــيخ ففــي يــوم الســبت املوافق‪1434/07/15‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪10.15‬بنــاء علــى اخلطــاب الــوارد إلينــا مــن‬\n‫مديــر بيــت املــال يف ‪1434/06/04‬ه ـ املتضمــن أنــه قــد حضــر لــدى بيــت‬\n‫املــال الوكيــل ‪ .....‬وقــرر تســليمه جميــع مــا يخــص موكلــه الــذي مت‬\n‫جردهــا مبوجــب محضــر اجلــرد يف ‪1432/08/29‬ه ـ عليــه فقــد أمــرت‬\n‫بإحلاقــه يف الصــك وســجله وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                          ‫محمــد وآلــه وصحبــه حــرر يف ‪1434/07/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة وتاريــخ ‪1434/4/23‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪ .........‬القاضــي باحملكمــة العامــة وتاريــخ ‪1434/1/4‬هــ‪،‬‬\n‫املتضمــن دعــوى ضــد ‪ ،..........‬وبدراســة الصــك وصــورة ضبطــه تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n                                                                                  ‫‪134‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":128,"source_page_end":134,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dac2356b2aed419abb861ca602d32b7ab07b5ce3578d39588422ca06bbee6a28","normalized_text_hash":"128eff7fc155b5510f0492758ddffa58250f66352fbfef332d44b76601ae3129","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p128-341325"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"38eeea7b-7b60-53b8-b13f-ba69528e03d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -مطالبة ورثة لبيت املال بدفع دية -وفاة املورث نتيجة حادث مروري -إدانة التحقيقات قائد السيارة املتسبب يف احلادث -املتسبب يف احلادث مجهول -موافقة املقام السامي على سماع الدعوى ضد بيت املال -إلزام بيت املال بدفع الدية .","document_number":"34214049","case_number":"3418342","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/15","year":"1434","subject":"مطالبة بيت املال -مطالبة ورثة لبيت املال بدفع دية -وفاة املورث نتيجة حادث مروري -إدانة التحقيقات قائد السيارة املتسبب يف احلادث -املتسبب يف احلادث مجهول -موافقة املقام السامي على سماع الدعوى ضد بيت املال -إلزام بيت املال بدفع الدية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/5/15 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34214049 :‬‬\n                         ‫َر ْق ُم الدعوى‪3418342 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34386020‬تاريخه‪1434/12/24 :‬هـ‬\n\n\n     ‫مطالبــة بيــت املــال ‪ -‬مطالبــة ورثــة لبيــت املــال بدفــع ديــة‪ -‬وفــاة املــورث‬\n     ‫نتيجــة حــادث مــروري‪ -‬إدانــة التحقيقــات قائــد الســيارة املتســبب يف‬\n     ‫احلــادث‪ -‬املتســبب يف احلــادث مجهــول‪ -‬موافقــة املقــام الســامي علــى‬\n              ‫ســماع الدعــوى ضــد بيــت املــال‪ -‬إلــزام بيــت املــال بدفــع الديــة ‪.‬‬\n\n\n\n\n     ‫‪-1‬قــول علــى رضــي اهلل عنــه لعمــر رضــي اهلل عنــه يــا أميــر املؤمنــن( ال‬\n      ‫يعطــل دم امــرئ مســلم فــإن علمــت قاتلــه وإال فأعطــه مــن بيــت املــال)‬\n     ‫‪ _2‬قــول الفقهــاء (إن مــن هلــك بفعــل نفســه وفعــل صاحبــه فيهــدر‬\n                                              ‫فعــل نفســه) الشــرح الكبيــر ‪336/25‬‬\n     ‫‪-3‬قــول الفقهــاء (امليــت يف زحمــة كجمعــة وطــواف فيفــدى مــن بيــت‬\n                                             ‫املــال إلــخ ‪)...‬كشــاف القنــاع ‪482/13‬‬\n     ‫‪-4‬ماقــرره الفقهــاء انــه يف حالــة ثبــوت الوفــاة بســبب جنايــة ادمــي‬\n     ‫مجهــول فــإن الضمــان يكــون يف بيت املال )شــرح منتهــى اإلرادات ‪136/6‬‬\n                             ‫‪ -5‬املادة ‪ ،179‬واملادة ‪ 39‬من نظام املرافعات الشرعية‬\n\n\n\n     ‫أقــام وكيــل ورثــة دعــوى علــى ممثــل بيــت املــال يطالبــه بديــة مــورث‬\n     ‫موكليــه الــذي تــويف يف حــادث دهــس بســيارة أثبــت التحقيقــات إدانــة‬\n\n‫‪89‬‬\n\f‫قائــد الســيارة بنســبة خمســه وســبعني باملائــة وقائــد الســيارة املتســبب‬\n‫بالوفــاة مختفــي وطلــب إلــزام بيــت مــال املســلمني بدفــع خمــس وســبعني‬\n‫باملائــة مــن الدية‪-‬صــدرت املوافقــة الســامية يف ســماع الدعــوى وعليــه‬\n‫أجــاب مديــر بيــت املــال بأنــه ال مانــع لــدى بيــت املــال مــن دفــع الديــه نظــرا‬\n‫لعــدم معرفــة اجلانــي ‪-‬نظــرا الن نســبة اخلطــأ يف احلــادث املذكور خمســة‬\n‫وســبعون باملائــة ونظــرا ملــا قــرره الفقهــاء ان مــن هلــك بفعــل نفســه وفعــل‬\n‫صاحبــه فيهــدر فعــل نفســه‪ -‬وان الوفــاة بســبب جنايــة مجهــول فــإن‬\n‫الضمــان يكــون يف بيــت املــال‪ -‬ونظــرا ملوافقــة املقــام الســامي لــذا‬\n‫حكمــت احملكمــة الــزام بيــت املــال بدفــع خمســه وســبعني باملائــة مــن‬\n    ‫لديــة لورثــة املتوفــى ‪ -‬اعتــرض مديــر بيــت املــال ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬رئيــس احملكمــة العامــة‬\n‫ـاء علــى املعاملــة احملالــة لنــا بتاريــخ ‪1434/01/11‬ه ـ‬\n                                                          ‫مبحافظــة وبنـ ً‬\n‫املقيــدة باحملكمــة بتاريــخ ‪1434/01/11‬ه ـ ففــي يــوم األحــد‬\n‫املوافق‪1434/01/11‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬صباحــا‬\n‫وفيهــا ‪ ..........‬حضــر هنــدي اجلنســية مبوجــب رخصــة االقامــة رقــم ‪......‬‬\n‫تنتهــي بتاريــخ ‪1434/6/19‬ه ـ بالوكالــة عــن حامــل الرقــم االنتخابــي‬\n‫الهندي ‪ 300557/051/07 .....‬و حامل رخصة القيادة الهندية مبوجب‬\n‫الوكالــة الصــادرة مــن كاتــب عــدل مقاطعــة بــاالكاد واليــة كيــراال‬\n‫بالهنــد برقــم وتاريــخ ‪ /16‬مايــو‪2010/‬م واملخولــة له مبراجعة احملكمة‬\n‫الســتالم ديــة املتوفــى واســتالم أي تعويضــات أخــرى تخــص املتوفــى ‪...‬‬\n‫الــخ املصدقــة مــن فــرع وزارة اخلارجيــة برقــم ‪ 25‬وتاريــخ ‪1431/6/2‬ه ـ‬\n\n                                                                                             ‫‪90‬‬\n\f     ‫وكذلــك املصدقــة مــن فــرع وزارة العــدل مبنطقــة جــازان بتاريــخ‬\n     ‫‪1433/11/9‬ه ـ وموكلــي املدعــي أصالــه همــا ورثــة ‪ ............‬املتوفــى‬\n     ‫بتاريــخ ‪1431/5/25‬ه ـ والدتــه و والــده مبوجــب الوكالــة املشــار إليهــا‬\n     ‫أعــاه وحضــر حلضــوره ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫ممثــل بيــت املــال بفــرع وزارة املاليــة مبنطقــة مبوجــب خطــاب التكليــف‬\n     ‫الصــادر مــن مديــر عــام فــرع وزارة املاليــة املكلــف يف ‪1434/1/11‬ه ـ‬\n     ‫وقــد صــدر األمــر الســامي رقــم ‪/14323‬م ب وتاريــخ ‪1433/5/2‬ه ـ‬\n     ‫باملوافقــة علــى ســماع دعــوى املطالبــة بالديــة يف مواجهــة منــدوب عــن‬\n     ‫بيــت املــال وفقــا لألمــر الســامي رقــم ‪ 13400‬وتاريــخ ‪1402/6/6‬ه ـ‬\n     ‫وبســؤال املدعــي عــن دعــواه أنــه بتاريــخ ‪1431/5/25‬ه ـ حصــل ملــورث‬\n     ‫موكلــي حــادث دهــس جنــم عــن وفاتــه وقــد أدانــت التحقيقــات قائــد‬\n     ‫الســيارة املتســببة بالدهــس بنســبة خمســة وســبعني باملائــة ولــم يعــرف‬\n     ‫املتســبب بوفــاة مــورث موكلــي حتــى تاريخــه لــذا أطلــب إلــزام بيــت مــال‬\n     ‫املســلمني بدفــع الديــة ملوكلــي وقدرهــا مائتــان وخمســة وعشــرون ألــف‬\n     ‫ريــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا‬\n     ‫بنــاء علــى صــدور املوافقــة الســامية برقــم ‪ 14323‬يف ‪1433/2/2‬ه ـ عــن‬\n     ‫ســماع الدعــوى فــا مانــع مــن دفــع الديــة من بيــت املال نظرا لعــدم معرفة‬\n     ‫اجلانــي هكــذا أجــاب ويف يــوم الســبت ‪1433/1/24‬ه ـ الســاعة التاســعة‬\n     ‫والنصــف صباحــا افتتحــت اجللســة الثانيــة وفيهــا حضر الطرفــان‪ ،‬فبناء‬\n     ‫علــى مــا تقــدم مــن الدعــوى واالجابــة ونظــرا لكــون نســبة اخلطــأ علــى‬\n     ‫املدهــوس خمســة وعشــرون باملائــة ونظــرا ملــا قــرره الفقهــاء أن مــن هلــك‬\n     ‫بفعــل نفســه وفعــل صاحبــه فيهــدر فعــل نفســه انظــر كشــاف القنــاع‬\n     ‫‪ 325/13‬والشــرح الكبيــر ‪ 336/25‬ونظــرا لكــون الديــة يف هــذه‬\n\n\n‫‪91‬‬\n\f‫احلالــة مائتــان وخمســة وعشــرون الــف ريــال ونظــرا ملــا قــرره الفقهــاء أن‬\n‫يف حالــة ثبــوت الوفــاة بســبب جنايــة آدمــي مجهــول فــإن الضمــان يكــون‬\n‫يف بيــت املــال فقــد جــاء يف شــرح منتهــى االيــرادات ‪( 136/6‬كميــت يف‬\n‫زحمــة كجمعــة وطــواف فيفــدى مــن بيــت املــال نصــا واحتــج مبــا روي‬\n‫عــن عمــر وعلــي ومنــه مــا روى ســعيد يف ســننه عــن قــال قتــل رجــل يف‬\n‫زحــام النــاس بعرفــة فجــاء أهلــه إلــى عمــر فقــال بينتكــم علــى مــن قتلــه‬\n‫فقــال علــي يــا أميــر املؤمنــن ال يطــل دم أمــرئ مســلم فــإن علمــت قاتلــه‬\n‫وإال فأعطيتــه مــن بيــت املــال ) أ ه ــو أنظــر كذلــك كشــاف القنــاع‬\n‫‪ 482/13‬ونظــرا ملوافقــة املقــام الســامي علــى ســماع هــذه الدعــوى لــذا‬\n‫فقــد أمــرت بــأن يدفــع بيــت املــال بــوزارة املاليــة لورثــة ‪ ........‬مبلــغ وقــدره‬\n‫مائتــان وخمســة وعشــرون الــف ريــال ألمــه مبلــغ وقــدره خمســة وســبعون‬\n‫الــف ريــال ولوالــده مبلــغ وقــدره مائــة وخمســون الــف ريــال وبــه حكمــت‬\n‫وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم املعارضــة وأمــرت برفــع‬\n‫كامــل املعاملــة إلــى محكمــة اإلســتئناف مبنطقــة عســير اســتنادا‬\n‫للمــادة التاســعة والســبعون بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n‫واهلل املوفــق وقــد اغلقــت اجللســة الســاعة العاشــرة صباحــا وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم األربعــاء ‪1434/4/17‬ه ـ افتتحــت اجللســة‬\n‫الثالثــة الســاعة الثامنــة والنصــف صباحــا وفيهــا حضــر الطرفــان وقــد‬\n‫جــرى منــا رفــع املعاملــة إلــى محكمــة االســتئناف وقــد أعيــدت إلينــا‬\n‫مــن رئيــس محكمــة االســتئناف مبنطقــة عســير برقــم ‪ 34404378‬يف‬\n‫‪1434/8/11‬ه ـ واملقيــدة باحملكمــة يف ‪1434/3/17‬ه ـ واملرفــق بهــا‬\n‫قــرار املالحظــة يف ‪1434/2/26‬ه ـ الصــادر مــن قضــاة الدائــرة الثالثــة‬\n\n\n                                                                                             ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":89,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3a92eb253e4c9334774759f3d55bdd01c1a4388257664e9a7c5ef14d08dc02f1","normalized_text_hash":"b0055edd38390170f4b89b1563ecfd50ddb0be1521d1048669ad5db729422bb9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p89-34214049"},{"id":"18988786-44f4-5fa1-8fa9-30be0e11d08d","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى ضد بيت املال -مطالبة أمن بيت املال بتسليم مبلغ مالي من الدولة لصالح املدعن -شراء عقار لقاصر -استعانة برأي اخلبراء -سداد الديون مقدم على حقوق الورثة -ثبوت الدعوى - وجوب تزكية الشهود -رعاية الدولة ألسر الشهداء -إمتام عقد البيع أمام المحكمة صونا حلقوق القصر.","document_number":"3427561","case_number":"3453148","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"دعوى ضد بيت املال -مطالبة أمن بيت املال بتسليم مبلغ مالي من الدولة لصالح املدعن -شراء عقار لقاصر -استعانة برأي اخلبراء -سداد الديون مقدم على حقوق الورثة -ثبوت الدعوى - وجوب تزكية الشهود -رعاية الدولة ألسر الشهداء -إمتام عقد البيع أمام المحكمة صونا حلقوق القصر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3427561 :‬‬\n                    ‫َر ْق ُم الدعوى‪3453148 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34241417‬تاريخه‪1434/6/14 :‬هـ‬\n\n\n‫دعــوى ضــد بيــت املــال‪ -‬مطالبــة أمــن بيــت املــال بتســليم مبلــغ مالــي‬\n‫مــن الدولــة لصالــح املدعــن‪ -‬شــراء عقــار لقاصــر‪ -‬اســتعانة بــرأي‬\n‫اخلبــراء‪ -‬ســداد الديــون مقــدم علــى حقــوق الورثــة ‪ -‬ثبــوت الدعــوى ‪-‬‬\n‫وجــوب تزكيــة الشــهود ‪ -‬رعايــة الدولــة ألســر الشــهداء ‪ -‬إمتــام عقــد‬\n                             ‫البيــع أمــام احملكمــة صونــا حلقــوق القصــر‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة املســتقر‬\n                                                   ‫عليهــا يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــون أن الدولــة قــد أودعــت يف بيــت مــال احملكمــة املبلــغ‬\n‫املذكــور يف الدعــوى لصالــح أســرة مورثهــم لتأمــن منــزل وســداد ديونــه‬\n‫وأنهــم وجــدوا منــز ًال مناســب ًا ويرغبــون شــرائه‪ ،‬لــذا طلبــوا إلــزام بيــت‬\n‫مــال احملكمــة بتســليمهم املبلــغ املذكــور ليقومــوا بتســليمه لصاحــب‬\n‫املنــزل‪ -‬أقــر أمــن بيــت مــال احملكمــة بإيــداع املبلــغ املذكــور لصالــح‬\n‫املدعــن وأنــه ال مانــع مــن تســليمه لهــم إذا صــدر حكــم قضائــي‬\n‫بذلــك‪ -‬قــرر املدعــون بأنــه ال يوجــد ديــون علــى املــورث وأنهــم ســيتحملون‬\n‫ســدادها لــو وجــدت‪ -‬حتققــت احملكمــة مــن وجــود غبطــة ومصلحــة‬\n\n                                                                                      ‫‪98‬‬\n\f     ‫للقاصريــن مــن الورثــة يف شــراء املنــزل املذكــور لهــم واطلعــت علــى‬\n     ‫املســتندات الالزمــة للســير يف الدعــوى‪ -‬قضــت احملكمــة بإلــزام بيــت‬\n     ‫املــال باحملكمــة بدفــع املبلــغ املذكــور لصالــح الورثــة املدعــن ويســلم‬\n     ‫ملالــك املنــزل‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم بعــد‬\n                                                                 ‫االجــراء األخيــر‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي باحملكمــة العامــة بأبــو‬\n     ‫عريــش وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بأبــو عريــش برقــم ‪ 3453148‬وتاريــخ ‪ 1434/02/02‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34263523‬وتاريــخ ‪ 1434/02/02‬ه ـ ففــي يــوم‬\n     ‫الســبت املوافق‪1434/02/02‬ه ـ افتتحــت اجللســة األولــى يف متام الســاعة‬\n     ‫الثانيــة عشــر والنصــف وفيهــا حضــرت ‪ .....‬ســعودية اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال صامطــة أصالــة عــن نفســها‬\n     ‫وبالواليــة عــن ‪ .....‬و ‪ .....‬و ‪ ..... .....‬و ‪ .....‬و ‪ .....‬مبوجــب صــك الواليــة رقــم‬\n     ‫‪ 10‬و تاريــخ ‪1432/11/20‬ه ـ الصــادر مــن احملكمــة العامــة باحلــرث‬\n     ‫كمــا حضــرت‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n     ‫‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و‪ .....‬ســعودية‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و‪ .....‬ســعودية اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ .....‬و املعــرف بهــم مــن قبــل ‪ .....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال صامطــة وحضــر‬\n     ‫حلضورهــم أمــن بيــت املــال باحملكمــة‪ .....‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ .....‬وقــرروا يف دعواهــم قائلــن إن مورثنــا ‪ .....‬تــويف‬\n\n‫‪99‬‬\n\f‫بتاريخ ‪1432/2/28‬هـ و أنحصر إرثه يف زوجته ‪ .....‬ويف أوالده البالغني‬\n‫وهــم ‪.....‬و ‪.....‬و ‪ .....‬و‪ .....‬ويف القاصريــن وهــم ‪.....‬و ‪ .....‬و‪ .....‬و‪ .....‬و‪.....‬‬\n‫مبوجــب صــك حصــر الورثــة رقم ‪ 3/9‬وتاريــخ ‪1432/3/2‬هـ الصادر من‬\n‫احملكمــة العامــة مبحافظــة صامطــة وقــد صــدرت توجيهــات صاحــب‬\n‫الســمو امللكــي مســاعد وزيــر الداخليــة للشــؤون األمنيــة مبســاعدة‬\n‫أســرة الشــهيد ‪ .....‬بتأمــن منــزل وســداد ديونــه مببلــغ وقــدره مليــون‬\n‫وثالثمائــة ألــف ريالــ‪ 1300000‬وقــد جــرى البحــث عــن منــزل مــن أجــل‬\n‫شــرائه ووجــد مبحافظــة أبــو عريــش مببلــغ وقــدره مليــون ومائتــا ألــف‬\n‫ريــال ‪ 1200000‬وقــد أودع املبلــغ يف بيــت مــال احملكمــة أطلــب إلــزام‬\n‫بيــت مــال احملكمــة بتســليمنا مبلــغ وقــدره مليــون ومائتــا ألــف ريــال‬\n‫‪ 1200000‬لتســليمه لصاحــب املنــزل املشــترى هكــذا ادعــوا عقــب ذلــك‬\n‫طلبــت مــن املدعيــات صــك حصــر الورثــة وصــك الواليــة فأبــرزن صــك‬\n‫حصــر الورثــة رقــم ‪ 3/9‬و تاريــخ ‪1432/3/2‬ه ـ الصــادر مــن احملكمــة‬\n‫العامــة بصامطــة و املتضمــن وفــاة ‪ .‬و انحصــار إرثــه يف زوجتــه ‪ .....‬ويف‬\n‫أوالده البالغــن وهــم ‪ .....‬و ‪ .....‬و ‪ ..........‬و‪ .....‬ويف القاصريــن وهــم ‪ .....‬و‬\n‫‪...... .....‬و‪ ....‬و‪.....‬و‪ .....‬وصــك الواليــة رقــم ‪ 10‬وتاريــخ ‪1432/11/20‬ه ـ‬\n‫الصــادر مــن احملكمــة العامــة باحلــرث و املتضمــن إقامــة ‪ .....‬وليــة‬\n‫علــى أوالدهــا القصــر ‪ .....‬و ‪ .....‬و ‪ .....‬و ‪ .....‬و ‪ .....‬و باالطــاع عليــه‬\n‫وجدتــه طبقــا ملــا ذكــر وبعــرض دعــوى املدعيــات علــى أمــن بيــت املــال‬\n‫باحملكمــة أجــاب قائــا مــا ذكرتــه املدعيــات مــن إيــداع مبلــغ وقــدره‬\n‫مليــون وثالثمائــة الــف ريالــ‪ 1300000‬فصحيــح وذلــك مبوجــب الســند‬\n‫رقــم ‪ 2/589347‬و تاريــخ ‪1433/5/26‬ه ـ و احلــاوي مبلــغ وقــدره مليــون‬\n‫وثالثمائــة ألــف ريالــ‪ 1300000‬مبوجــب الشــيكني رقــم ‪873418‬‬\n\n\n                                                                                          ‫‪100‬‬\n\f      ‫و ‪ 873419‬وتاريــخ ‪1433/5/21‬ه ـ و العائــد لورثــة املتوفــى ‪ .....‬وال‬\n      ‫مانــع لــدي مــن تســليم املبلــغ بعــد صــدور حكــم بذلــك علــى بيــت املــال‬\n      ‫هكــذا أجــاب عقــب ذلــك جــرى االطــاع خطــاب مديــر عــام الشــؤون‬\n      ‫العســكرية رقــم ‪ 47105‬وتاريــخ ‪1433/4/26‬ه ـ و املوجــه إلــى رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة أبــو عريــش املتضمــن آمــل مــن فضيلتكــم‬\n      ‫التكــرم بســداد الديــون التــي يف ذمــة الشــهيد ويف حــال عــدم وجــود‬\n      ‫ديــون علــى الشــهيد يأخــذ إقــرار بذلــك ويتــم تأمــن ســكن ألســرة‬\n      ‫الشــهيد و تســجيله باســم زوجة الشــهيد ‪ .....‬و أبنائه ‪ .....‬و‪ .....‬و‪ .....‬و‪.....‬‬\n      ‫و‪ .....‬و‪ ..... .....‬و‪ .....‬و‪.....‬و‪ .....‬بالتســاوي علــى أن يهمــش علــى الصــك‬\n      ‫بعــدم بيــع املنــزل حتــى بلــوغ القصــر ســن الرشــد و تزويدنــا بنســخه مــن‬\n      ‫ملكيــة املنــزل عليــه جــرى ســؤال املدعيــات هــل يوجــد علــى مورثكــم‬\n      ‫املتوفــى أي ديــون فأجابــت كل واحــدة مبفردهــا قائلــة ال يوجــد عليــه‬\n      ‫أي ديــون ويف حــال ظهــور ذلــك نتحمــل ســدادها وقــد مت أخــذ إقــرار‬\n      ‫بذلــك عليهــم مرفــق باملعاملــة هكــذا أجابــت كل واحــده مبفردهــا‬\n      ‫عقــب ذلــك ســألت املدعيــات عــن املنــزل الذيــن يرغبــون يف شــرائه‬\n      ‫فأجــن قائــات أن املنــزل يقــع يف محافظــة أبــو عريــش شــمال للشــقق‬\n      ‫املفروشــة و اململــوك ل‪ .....‬مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n      ‫أبــو عريــش برقــم ‪ 105‬وتاريــخ ‪1408/6/14‬ه ـ جلــد ‪ 41‬صحيفــة رقــم‬\n      ‫‪ 156-155‬مببلــغ وقــدره مليــون و مائتــا ألــف ريــال ‪ 1200000‬هكــذا‬\n      ‫أجــن عليــه فقــد حضــرت ‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....‬واملعــرف بهــا مــن قبــل زوجهــا س‪ .....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال جــازان و بســؤالها عمــا‬\n      ‫ذكــرت املدعيــات أجابــت قائلــة أنــه مت االتفــاق مــع ورثــة ‪ .....‬علــى بيــع‬\n\n\n‫‪101‬‬\n\f‫املنــزل عليهــم مببلــغ وقــدره مليــون و مائتــا ألــف ريــال ‪ 1200000‬وال مانــع‬\n‫لــدي مــن بيعــه عليهــم هكــذا أجابــت عقــب ذلــك جــرى عقــد البيــع يف‬\n‫مجلــس احلكــم بقــول أنــا ف‪ .....‬بعــت املنــزل اململــوك لــي بالصــك رقــم‬\n‫‪ 105‬و وتاريــخ ‪1408/6/14‬ه ـ جلــد ‪ 41‬صحيفــة رقــم ‪ 156-155‬مببلــغ‬\n‫وقــدره مليــون و مائتــا ألــف ريــال ‪ 1200000‬علــى ورثــة ‪ .....‬و حصــل‬\n‫القبــول مــن املدعيــات بقولهــن قبلنــا هــذا البيــع و رضينــا بــه وقــد اطلعنــا‬\n‫وشــاهدنا املنــزل املذكــور و كان ذلــك بحضــور و شــهادة ‪ .....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال ‪ .....‬و ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي ‪ .....‬الصــادر مــن أحــوال ‪.....‬‬\n‫ذلــك جــرى ســؤال البائعــة عــن صــك املنــزل فأبــرزت الصــك رقــم ‪105‬‬\n‫وتاريــخ ‪1408/6/14‬ه ـ واحلــاوي لقطعــة األرض رقــم ‪ 5‬مــن مخطــط‬\n‫أرضــه املعتمــد واحلــدود و األطــوال و املســاحة كالتالــي شــماال القطعــة‬\n‫رقــم ‪ 3‬و طــول الضلــع ‪ 21‬متــر جنوبــا شــارع مقتــرح عــرض ‪ 10‬متــر‬\n‫وطــول الضلــع ‪ 18‬شــرقا شــارع عــرض ‪ 10‬متــر و طــول الضلــع ‪ 13,5‬ثــم‬\n‫ينحنــي بطــول ‪ 4‬متــر غربــا القطعــة رقــم ‪ 4‬وطــول الضلــع ‪ 16.5‬متــر و‬\n‫املســاحة الكليــة ‪ 340,5‬ثالثمائــة وأربعــون متــر و نصــف املتــر وجــرى‬\n‫االستفســار عــن ســامة الصــك فــورد اجلــواب برقــم ‪/134/879‬ج و‬\n‫تاريــخ ‪1433/7/22‬ه ـ و املتضمــن أن الصــك ســليم و مطابــق لســجله‬\n‫وســاري املفعــول كمــا جــرى الكتابــة لهيئــة النظــر باحملكمــة‬\n‫باخلطــاب رقــم ‪ 2/2362‬وتاريــخ ‪1433/7/29‬ه ـ لالستفســار هــل يف‬\n‫شــرائه مبلــغ وقــدره مليــون ومائتــا ألــف ريــال غبطــة و مصلحــه للقصــر‬\n‫فوردنــا جوابهــم باخلطــاب رقــم ‪/156‬ه ـ يف ‪1433/8/4‬ه ـ واملتضمــن أنــه‬\n‫مت الوقــوف علــى املنــزل الواقــع باحلــي ‪ ..........‬مبحافظــة أبــو عريــش وهــو‬\n\n\n                                                                                        ‫‪102‬‬\n\f      ‫عبــارة عــن عمــاره ســكنية دوريــن وملحــق حتتــوي علــى خمــس شــقق‬\n      ‫ومحاطــة بســور مــن جميــع اجلهــات وقيمــة الشــراء مببلــغ وقــدره مليــون‬\n      ‫ومائتــا ألــف ريــال بــه غبطــة ومصلحــه للقصــر ويجــود بالســكن جميــع‬\n      ‫اخلدمــات مــن كهربــاء ومــاء و خالفــه أ‪.‬ه ـ كمــا جــرت الكتابــة ملديــر‬\n      ‫عــام الشــؤون العســكرية بــوزارة الداخليــة باخلطــاب رقــم ‪331983767‬‬\n      ‫وتاريــخ ‪1433/11/10‬ه ـ لإلفــادة عــن باقــي املبلغ فورد اجلــواب باخلطاب‬\n      ‫رقــم ‪ 3411‬وتاريــخ ‪1434/1/7‬ه ـ و املتضمــن أنــه بعــد تأمــن املنــزل بنــاء‬\n      ‫علــى البرقيــة الســابقة بعــث املبلــغ املتبقــي بشــيك باســم اإلدارة العامــة‬\n      ‫للنفقــات األمنيــة ليتــم توزيعــه مــن قبــل اجلهــة املختصــة بالــوزارة فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى و اإلجابــة ومبــا أن املدعيــات طلــن إلــزام‬\n      ‫أمــن بيــت املــال باحملكمــة بتســليم مبلــغ وقــدره مليــون ومائتــا ألــف ريال‬\n      ‫لصاحلهــم مقابــل شــراء املنــزل مــن البائعــة ف‪ .....‬و مبــا أن أمــن بيــت‬\n      ‫املــال أقــر بوجــود املبلــغ ببيــت مــال احملكمــة وال مانــع لديــه مــن تســليمه‬\n      ‫بعــد صــدور حكــم عليــه و مبــا أن البائعــة قــد حضــرت و مت إجــراء عقــد‬\n      ‫البيــع مبجلــس احلكــم علــى مبلــغ وقــدره مليــون ومائتــا ألــف ريــال و بعــد‬\n      ‫االطــاع علــى صــك حصــر الورثــة وصــك الواليــة وصــك ملكيــة العقــار‬\n      ‫املــدون بعاليــه و خطــاب هيئــة النظــر و خطــاب مديــر عــام الشــؤون‬\n      ‫العســكرية بــوزارة الداخليــة وطلبــه بعــث باقــي املبلــغ باســم اإلدارة‬\n      ‫العامــة للنفقــات األمنيــة لذلــك كلــه و لــكل مــا تقــدم فقــد ألزمــت‬\n      ‫أمــن بيــت املــال باحملكمــة ‪ .....‬أوال بدفــع مبلــغ وقــدره مليــون مائتــا‬\n      ‫ألــف ريــال لصالــح ورثــة ‪ .....‬و يســلم للبائعــة ‪ .....‬ثانيــا دفــع مبلــغ وقــدره‬\n      ‫مائــة ألــف ريــال لــإدارة العامــة للنفقــات األمنيــة وأمــرت بالتهميــش علــى‬\n      ‫صــك املنــزل بانتقــال امللكيــة ل‪ .....‬و ‪ .....‬و‪ .....‬و‪ .....‬و‪..... .....‬و ‪ .....‬و‪.....‬و‬\n\n\n‫‪103‬‬\n\f‫‪ .....‬و‪ .....‬أبنــاء ‪ .....‬بالتســاوي وعــدم بيــع املنــزل حتــى بلــوغ القصــر ســن‬\n‫الرشــد وبــه حكمــت و بعــرض احلكــم علــى املدعيــات قــررن القناعــة‬\n‫بــه وقــرر أمــن بيــت املــال عــدم القناعــة بــدون الئحــة اعتراضيــة عليــه‬\n‫أمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف لتدقيــق‬\n‫احلكــم و حتــى ال يخفــى جــرى تدوينــه و بــاهلل التوفيــق و أقفلــت اجللســة‬\n‫يف متــام الســاعة الواحــدة و خمســة وأربعــون دقيقــة وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد و علــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/2/2‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي باحملكمــة العامــة بأبــو‬\n‫عريــش ففــي يــوم الســبت املوافــق‪ 1434/03/28‬ه ـ افتتحــت اجللســة‬\n‫الثانيــة يف متــام الســاعة احلاديــة عشــر و النصــف وفيها حضــرت املدعيات‬\n‫و املعــرف بهــن املثبــت هوياتهــم يف اجللســة األولــى بنــاء علــى املعاملــة‬\n‫الــواردة إلينــا مــن محكمــة االســتئناف برقــم ‪ 34348433‬وتاريــخ‬\n‫‪1434/3/10‬ه ـ و املرفــق بهــا قــرار املالحظــة رقــم ‪ 3454869‬وتاريــخ‬\n‫‪1434/3/3‬ه ـ و املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه و أوراق‬\n‫املعاملــة لوحــظ مــا يلــي لــم يطلــب فضيلــة ناظــر القضيــة بينــة مــن أهــل‬\n‫اخلبــرة تشــهد بــأن يف شــراء الــدار املوصوفــة بالصــك غبطــه ومصلحــة‬\n‫للقصــر والبــد مــن ذلــك فلمالحظــة مــا ذكــر و إحلــاق مــا يســتجد‬\n‫بالضبــط وصورتــه وخالصتــه بالصــك وســجله و اهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد و آلــه وصحبــه وســلم دائــرة األحــوال الشــخصية و‬\n‫األوقــاف و الوصايــا والقصــار وبيــوت املــال قاضــي اســتئناف ‪ .....‬ختمــه‬\n‫و توقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .....‬ختمــه‬\n‫وتوقيعــه أ‪.‬ه ـ عليــه أجيــب أصحــاب الفضيلة نفعني اهلل بعلمهم أنه جرى‬\n‫إحضــار كال مــن ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n\n\n                                                                                        ‫‪104‬‬\n\f      ‫الصــادر أحــوال أبــو عريــش وبســؤاله عــن عمــره و عملــه ومحــل إقامتــه‬\n      ‫ا عمــري ثالثــة وخمســون عام ـ ًا و‬       ‫وصلــة قرابتــه باملدعــن أجــاب قائ ـ ً‬\n      ‫أعمــل صاحــب مكتــب عقــار ومــن ســكان أبــو عريــش وال توجــد بينــي‬\n      ‫وبــن املدعــن أي صلــة قرابــة كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .....‬الصــادر مــن أحــوال أبــو عريــش وبســؤاله عــن‬\n      ‫ا عمري‬    ‫عمــره و عملــه ومحــل إقامتــه وصلــة قرابتــه باملدعــن أجــاب قائـ ً‬\n      ‫واحــد وأربعــون عامـ ًا وأعمــل موظــف يف وزارة العــدل وصاحــب مكتــب‬\n      ‫عقــار وأســكن محافظــة أبــو عريــش وال يوجــد بينــي وبــن املدعــن أي‬\n      ‫صلــة قرابــة وبســؤال كل واحــد منهمــا مبفــرده هــل يف شــراء الــدار‬\n      ‫املوصوفــة بالصــك غبطــه ومصلحــة للقصــر أم ال أجــاب كل واحــد‬\n      ‫منهمــا مبفــرده قائــا نعــم يوجــد يف شــراء املنــزل املذكــور بعاليــة‬\n      ‫مصلحــة و غبطــه للقصــر هكــذا أجــاب كل واحــد منهمــا مبفــرده‬\n      ‫عليــه أمــرت بإحلــاق ذلــك علــى الصــك وســجله وصــورة الضبــط و أمــرت‬\n      ‫بإعــادة كامــل أوراق املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكم‬\n      ‫و بــاهلل التوفيــق وحتــى ال يخفــى جــرى تدوينــه و أقفلــت اجللســة يف متــام‬\n           ‫الســاعة الثانيــة عشــر و صلــى اهلل وســلم حــرر يف ‪28/03/1434‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n      ‫فلــدي أنــا ‪ .....‬القاضــي باحملكمــة العامــة بأبــو عريــش ففــي يــوم األحــد‬\n      ‫املوافق‪1434/05/12‬ه ـ افتتحــت اجللســة الثالثــة يف متــام الســاعة احلاديــة‬\n      ‫عشــر والنصــف بنــاء علــى املعاملــة الــواردة إلينا من محكمة االســتئناف‬\n      ‫مبوجــب خطــاب فضيلــة رئيســها رقــم ‪ 34875185‬وتاريخ‪1434/5/1‬ه ـ‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 34875185‬وتاريخ ‪1434/5/8‬هـ واملرفق به‬\n      ‫قــرار املالحظــة الصــادر مــن دائــرة األحوال الشــخصية رقــم ‪34194860‬‬\n\n\n‫‪105‬‬\n\f‫وتاريــخ ‪1434/4/22‬ه ـ واملتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة لوحــظ مــا يلــي لــم جنــد أن فضيلتــه طلــب تزكيــة‬\n‫الشــاهدين والبــد مــن ذلــك فلمالحظــة مــا ذكــر وإحلــاق مــا يســتجد‬\n‫يف الضبــط وصورتــه وملخصــه بالصــك وســجله واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم دائــرة األحــوال الشــخصية‬\n‫واألوقــاف والقصــار وبيــوت املــال قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه‬\n‫قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .....‬ختمــه وتوقيعــه‬\n‫عليــه أجيــب أصحــاب الفضيلــة نفعنــي اهلل بعلمهــم أن القرائــن مــن‬\n‫شــهادة الشــاهدين وخطــاب قســم اخلبــراء جــاء فيــه مــا يحقــق الغبطــة‬\n‫واملصلحــة ولطلــب أصحــاب الفضيلــة تزكيــة الشــاهدين فقــد حضــر‬\n‫كال مــن ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬الصــادر‬\n‫مــن أحــوال أبــو عريــش و‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬الصــادر مــن أحــوال أبــو عريــش وبســؤال كل واحــد مبفــرده‬\n‫عــن الشــاهدين أجــاب قائــا الشــاهدين عدلــن مرضيــي الشــهادة‬\n‫هكــذا أجــاب كل واحــد مبفــرده عليــه أمــرت بإحلــاق ذلــك بالصــك‬\n‫وســجله وإعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف وأقفلــت‬\n‫اجللســة يف متــام الســاعة الثانيــة عشــر وحتــى ال يخفــى جــرى تدوينــه‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                  ‫حــرر يف ‪121434/05/‬ه ـ ‪.‬‬\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34241417‬وتاريــخ‬\n                                               ‫‪1434/6/14‬هـ ‪.‬‬\n\n\n\n                                                                                  ‫‪106‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":98,"source_page_end":106,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9fee818b7a7042a261942c5a0ed7a4319389945425e7f8fd3057012f9a35f77d","normalized_text_hash":"4b09ed31c7d1ad3632238303b01df629a8248c409f4b851cdea8c62988a503af","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p98-3427561"},{"id":"9230a9eb-9560-56c3-927e-28d0866de844","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -نزع ملكية عقار لتوسعة احلرم -إيداع قيمة تعويض ببيت املال -مطالبة بيت املال باملبلغ -إقرار بيت املال بحيازته املبلغ -إلزام بيت املال بتسليم املبلغ للمدعن .","document_number":"34227320","case_number":"3456138","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"مطالبة بيت املال -نزع ملكية عقار لتوسعة احلرم -إيداع قيمة تعويض ببيت املال -مطالبة بيت املال باملبلغ -إقرار بيت املال بحيازته املبلغ -إلزام بيت املال بتسليم املبلغ للمدعن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34227320 :‬‬\n                          ‫َر ْق ُم الدعوى‪3456138 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34388622‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n      ‫مطالبــة بيــت املــال‪ -‬نــزع ملكيــة عقــار لتوســعة احلــرم‪ -‬إيــداع قيمــة‬\n      ‫تعويــض ببيــت املــال‪ -‬مطالبــة بيــت املــال باملبلــغ‪ -‬إقــرار بيــت املــال‬\n               ‫بحيازتــه املبلــغ‪ -‬إلــزام بيــت املــال بتســليم املبلــغ للمدعــن ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫أقــام رجــل دعــوى يطالــب بيــت املــال بنصيــب موكليــه مــن العقــار املنزوع‬\n      ‫لصالــح توســعة الســاحة الشــمالية للحــرم ‪ -‬أقــر مندوب بيــت املال بوجود‬\n      ‫مــال مــودع يف بيــت املــال لصالــح مــورث املدعــن وأنــه ال مانــع لــدى بيــت‬\n      ‫املــال مــن دفعــه ملســتحقه إذا ثبــت لــدى احملكمــة اســتحقاق املدعــي‬\n      ‫مبــا يطالــب بــه اطلعــت احملكمــة علــى كافــة األوراق واملســتندات‬\n      ‫والصكــوك فثبــت لديهــا اســتحقاق املدعــي ملــا يطالــب بــه فحكمــت‬\n      ‫علــى بيــت املــال بتســليم املدعــي حقــوق موكليــه والن احلكــم علــى بيــت‬\n                ‫املــال رفــع هــذا اإلجــراء حملكمــة االســتئناف وصــدق احلكــم‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n‫العامــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة برقــم وتاريــخ ‪1434/02/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪1434/02/03‬ه ـ حضــر بصفتــه وكيــا عــن كل مــن‬\n‫واملســتكملة للتصديقــات الرســمية مــن فـ ـ ـ ـ ــرع وزارة اخلارجيــة برقـ ـ ــم‬\n‫يف ‪1433/7/1‬ه ـ ومــن فـ ـ ـ ــرع وزارة الع ـ ـ ــدل مبكـ ــة املكرمـ ـ ـ ــة يف‬\n‫‪1433/7/1‬ه بصفتهــم أوالد وبصفتــه وكيــا وهــم ورثــة ‪ ......‬مبوجــب‬\n‫صــك حصــر االرث يف ‪ 12‬اغســطس ‪2010‬م والصــادر مــن رئيــس ناحيــة‬\n‫بوكيتكتشــيل بجمهوريــة اندونيســيا وذلــك بالوكالــة يف ‪ 8‬أغســطس‬\n‫‪2011‬م والصــادرة مــن كتابــة عــدل أريانــي كومــا إلســاري بجمهوريــة‬\n‫اندونيســيا واملســتكملة للتصديقــات الرســمية مــن فــرع وزارة اخلارجيــة‬\n‫مبكــة يف ‪1433/7/14‬ه ـ ومــن فــرع وزارة العــدل مبكــة املكرمــة‬\n‫يف ‪1433/7/12‬ه ـ واملخولــة لــه حــق املتابعــة واالســتالم والتســليم‬\n‫الــخ وادعــى قائــا انــه كان مــن اجلــاري يف العقــار الواقــع يف الفلــق‬\n‫واحملــدود شــما ًال ملــك وجنوب ـ ًا ســكة نافــذة و شــرق ًا جــاء فــارغ ومتــام‬\n‫احلــد الرحبــة العامــة وغرب ـ ًا ســكة غيــر نافــذة والواقــع بحــي الششــة‬\n‫مبكــة وقــد نــزع هــذا العقــار لصالــح توســعة الســاحات الشــمالية للحــرم‬\n‫وعــوض عنــه ثــم تــويف وانحصــر ارثــه يف زوجتــه ويف ابنتــه لــه مــن زوجتــه‬\n‫املطلقــة منــه حــال حياتــه ويف أخيــه الشــقيق وذلــك مبوجــب صــك حصــر‬\n‫اإلرث يف ‪1407/6/2‬ه ـ الصــادر مــن هــذه احملكمــة ثــم تــويف وانحصــر‬\n‫ارثــه يف زوجتــه ويف أوالده منهــا وذلــك مبوجــب صــك حصــر اإلرث يف‬\n\n                                                                                      ‫‪108‬‬\n\f      ‫‪ 2‬ابريــل ‪2012‬م والصــادر مــن كاتــب عــدل أريانــي كومــا إلســاري ثــم‬\n      ‫توفيــت وانحصــر ارثهــا وذلــك مبوجــب صــك حصــر اإلرث يف ‪ 2‬ابريــل‬\n      ‫‪2012‬م والصــادر مــن كاتــب عــدل أريانــي كومــا إلســاري بجمهوريــة‬\n      ‫اندونيســيا ثــم تــويف وانحصــر إرثــه يف زوجتــه وذلــك مبوجــب صــك‬\n      ‫حصــر اإلرث الصــادر مــن رئيــس ناحيــة بوكيــت كتشــيل بجمهوريــة‬\n      ‫اندونيســيا يف ‪ 12‬أغســطس ‪2010‬م وقــد أزيــل العقــار املذكــور ويخــص‬\n      ‫موكلــي مــن التعويــض ‪ ....‬أطلــب احلكــم علــى املدعــى عليــه بتســليمها‬\n      ‫لــي واســأله اجلــواب هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال مــا‬\n      ‫ذكــره املدعــي وكالــه يف دعــواه أن املبلــغ املذكــور مــودع يف بيــت‬\n      ‫مــال احملكمــة فهــذا صحيــح وقــد مت إيداعــه بنــاء علــى خطــاب رئيــس‬\n      ‫كتابــة العــدل األولــى مبكــة املكرمــة يف ‪1432/2/21‬ه ـ لصالــح‬\n      ‫الغائــب ‪ .....‬باعتبــار أنــه غائــب وليــس متوفــى وإذا اتضــح لكــم وفاتــه‬\n      ‫وورثتــه فــا مانــع لــدى بيــت املــال مــن تســليمه للورثــة أو لوكيلهــم إذا‬\n      ‫صــدر حكــم مــن احملكمــة بذلــك هكــذا أجــاب ثــم اطلعــت علــى‬\n      ‫الصــك فوجدتــه كمــا ذكــر املدعــي يتضمــن ‪ ....‬يف ‪1406/11/27‬ه ـ‬\n      ‫وانحصــار إرثــه فيمــن ذكرهــم املدعــي كمــا اطلعــت علــى صــك‬\n      ‫حصــر اإلرث واملســتكمل للتصديقــات الرســمية مــن فــرع وزارة‬\n      ‫اخلارجيــة مبكــة يف ‪1433/7/1‬ه ـ ومــن فــرع وزارة العــدل مبكــة يف‬\n      ‫‪1433/7/1‬ه ـ ومــن ســفارة اململكــة العربيــة الســعودية يف جاكرتــا يف‬\n      ‫‪1433/6/2‬ه ـ وصــك حصــر اإلرث يف ‪ 2‬ابريــل ‪2012‬م واملســتكمل‬\n      ‫للتصديقــات الرســمية مــن فــرع وزارة اخلارجيــة مبكــة يف ‪1433/7/1‬هـ‬\n      ‫ومــن فــرع وزارة العــدل مبكــة يف ‪1433/7/1‬ه ـ ومــن ســفارة اململكــة‬\n      ‫العربيــة الســعودية يف جاكرتــا يف ‪1433/6/2‬ه ـ والصــك حلصــر ورثــة‬\n\n\n‫‪109‬‬\n\f‫يف ‪ 12‬أغســطس ‪2010‬م واملســتكمل للتصديقــات الرســمية مــن‬\n‫فــرع وزارة اخلارجيــة ‪ 30‬يف ‪1433/7/14‬ه ـ ومــن فــرع وزارة العــدل‬\n‫مبكــة يف ‪1433/7/12‬ه ـ ومــن ســفارة اململكــة العربيــة الســعودية‬\n‫يف جاكرتــا يف ‪1431/11/10‬ه ـ ثــم اطلعــت علــى ايصــال االســتالم يف‬\n‫‪1432/3/19‬ه ـ الصــادر مــن بيــت املــال بهــذه احملكمــة لصالــح الغائــب‬\n‫بنــاء علــى خطــاب رئيــس كتابــة العــدل األولى مبكــة يف ‪1432/2/21‬ه‬\n‫وبعــد النظــر يف الدعــوى واإلجابــة ومــا تضمنــه إقــرار املدعــى عليــه‬\n‫أن بيــت املــال يف هــذه احملكمــة يف حوزتــه املبلــغ املدعــى بــه ونظــرا‬\n‫ملــا ثبــت شــرعا تــويف و مــن ضمــن ورثتــه أخــوه الشــقيق وهــو املدعــى‬\n‫بنصيبــه ونظــرا ملــا أفــادت بــه كتابــة العــدل أن املبلــغ املرصــود ونظــرا‬\n‫لثبــوت وفاتــه وانحصــار إرثــه فيمــن ذكــر بعاليــه وألن بيــت املــال جهــة‬\n‫حافظــة ألمــوال الغيــب واملفقوديــن واملتوفــن وألنــه ظهــر لهــذا الغائــب‬\n‫وارث مبوجــب الصكــوك املشــار إليهــا وهــم املــدون فلــذا يجــب شــرعا‬\n‫علــى بيــت املــال تســليم املدعــن هــذا املبلــغ النتقالــه إليهــم بــاإلرث لذلــك‬\n‫كلــه فقــد حكمــت علــى بيــت املــال بهــذه احملكمــة بتســليم املدعــن‬\n‫املبلــغ احملفــوظ لديــه لصالــح مــورث املدعــن وبعرضــه علــى منــدوب بيت‬\n‫املــال قــرر عــدم القناعــة وطلــب رفعهــا حملكمــة االســتئناف دون الئحــة‬\n‫فأجبتــه لطلبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/27‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء ‪1434/11/11‬ه ـ‬\n‫فتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف يف‬\n‫‪1434/10/7‬ه ـ وبرفقهــا القــرار يف ‪1434/9/17‬ه ـ واملتضمــن أنــه‬\n‫بدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر مالحظــة‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫مــا يلــي ‪ -1 :‬القضيــة ســبق نظرهــا من فضيلــة القاضي مبكة املكرمة‬\n      ‫مبوجــب الصــك يف ‪1433/8/5‬ه ـ وانتهــت بنقــض احلكــم مــن محكمــة‬\n      ‫االســتئناف يف ‪1434/1/4‬ه ـ علــى أن حتــال لقــاض آخــر مــع مراعــاة‬\n      ‫مــا جــاء يف قــرارات محكمــة االســتئناف ولــم يشــر فضيلتــه لذلــك يف‬\n      ‫ضبــط القضيــة وال يف الصــك ولــم يــراع مــا جــاء يف قــرارات محكمــة‬\n      ‫االســتئناف ‪ -2‬لــم يطلــب مــن املدعــي اثبــات متلــك املتــويف املذكــور‬\n      ‫لهــذا العقــار ومقــدار التعويــض والبــد مــن ذلــك قبــل احلكــم علــى بيــت‬\n      ‫املــال ‪ -3‬لــم يوضــح نصيــب كل وارث واهلل املوفــق وعليــه أجيــب بانــه‬\n      ‫ســبق نظــر هــذه الدعــوى مــن فضيلــة الشــيخ بهــذه احملكمــة بالصــك‬\n      ‫املذكــور ونقــض مبوجــب قــرار محكمــة االســتئناف املشــار إليــه وأمــا‬\n      ‫مراعــاة مــا جــاء يف قــرار محكمــة االســتئناف فغيــر الزم مالــم يقنــع بــه‬\n      ‫ناظــر القضيــة علمــا أننــي طلبــت صــك التملــك وأجلــت النظــر واحلكــم‬\n      ‫لذلــك ورصــدت مضمونــه وهــو ضمــن أهــم مالحظــات الدائــرة علــى‬\n      ‫احلكــم املنقــوض وأزيــد بيانــا هنــا أنــه جــرى اطالعــي علــى صــك العقــار‬\n      ‫املنــزوع فوجدتــه يف ‪1393/6/14‬ه ـ الصــادر مــن كاتــب عــدل مكــة‬\n      ‫فوجدتــه كمــا جــاء يف دعــوى املدعــي ســوى وقــد أقحــم يف ضمــن دعــواه‬\n      ‫أنــه واقــع يف الششــه وهــذا ســهو والصــواب مــا ذكــره يف أول دعــواه‬\n      ‫أنــه واقــع يف الفلــق وأيضــا فقــد رصــدت حصــر وأمــا مقــدار التعويــض‬\n      ‫فقــد ذكرتــه يف ضمــن إجابــة مديــر بيــت املــال أنــه يخــص وأمــا قســمة‬\n      ‫املبلــغ بــن الورثــة فلــم يطلبــه املدعــي ومعلــوم أن القاضــي إمنــا يتبــع دعــوى‬\n      ‫املدعــي وال يخــرج يف النظــر عنهــا ثــم إن قســمة املبلــغ ال تخضــع للنظــر‬\n      ‫القضائــي مــا لــم تدخلهــا اخلصومــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/11/11‬هــ‪.‬‬\n\n\n‫‪111‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثاءاملوافــق‪ 1435/01/16‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11.30‬وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف يف ‪1435/1/4‬ه ـ وبرفقهــا القــرار يف ‪1434/12/25‬ه ـ‬\n‫واملتضمــن املوافقــة باألكثريــة املوافقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر‪ .‬وبــاهلل التوفيــق ‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1435/1/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء ‪1435/1/30‬ه ـ فتحــت‬\n‫اجللســة وفيهــا وردنــا خطــاب مديــر بيــت املــال يف ‪1435/1/30‬ه ـ‬\n‫واملتضمــن مــا نصــه‪ :‬نرفــق لكــم الشــيك يف ‪1435/1/30‬ه ـ الصــادر‬\n‫مــن فــرع مؤسســة النقــد مبكــة مقابــل للشــيك الصــادر مــن بيــت املــال‬\n‫يف ‪1435/1/29‬ه ـ ألمــر الوكيــل ‪ ....‬وذلــك لقــاء املبلــغ املــودع لصالــح‪.‬‬\n‫مــع أصــل الصــك الصــادر مــن فضيلتــك يف ‪1434/5/29‬ه ـ ونأمــل مــن‬\n‫فضيلتكــم التكــرم بإعادتــه إلينــا حلفظــه بعــد إكمــال الــازم أ‪.‬ه ـ‬\n‫لــذا فقــد جــرى تســليم الشــيك املذكــور لوكيــل وســوف يهمــش علــى‬\n      ‫صكــه وســجله مبوجبــه وبــاهلل التوفيــق حــرر يف ‪1435/1/30‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ‪ ..........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫وتاريــخ ‪1434/5/29‬ه ـ املتضمــن دعــوى‪ ..........‬ضــد‪ .....‬احملكــوم‬\n‫في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة ضبط ــه تق ــرر‬\n‫باألكثريــة املوافق ــة عل ــى احلكــم بعــد االجــراء االخيــر ‪ .‬وبــاهلل التوفيق‬\n                  ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n                                                                                       ‫‪112‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":107,"source_page_end":112,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f8859c669641a639433796704887f41b446545f69bb5738ba41af811765f077a","normalized_text_hash":"9c3b0f60faf575055bcd6e2120b1bd2d834c5911d0579b197d9acdf12c6c372f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p107-34227320"},{"id":"f415271f-b443-5a7d-b1d6-70ee70a46bb2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -مطالبة ورثة بيت املال ببيع عقار باملزاد العلني- بيت املال أحد الورثة -موافقة اجلهات احلكومية على البيع باملزاد العلني لكون أحد الورثة جهة حكومية -احلكم ببيع العقار باملزاد العلني وقسمة الثمن بن الورثة حسب الفريضة الشرعية .","document_number":"34190721","case_number":"33103300","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"مطالبة بيت املال -مطالبة ورثة بيت املال ببيع عقار باملزاد العلني- بيت املال أحد الورثة -موافقة اجلهات احلكومية على البيع باملزاد العلني لكون أحد الورثة جهة حكومية -احلكم ببيع العقار باملزاد العلني وقسمة الثمن بن الورثة حسب الفريضة الشرعية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34190721 :‬‬\n                         ‫َر ْق ُم الدعوى‪33103300 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34205479‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n      ‫مطالبــة بيــت املــال ‪ -‬مطالبــة ورثــة بيــت املــال ببيع عقار باملــزاد العلني‪-‬‬\n      ‫بيــت املــال أحــد الورثــة‪ -‬موافقــة اجلهــات احلكوميــة علــى البيــع باملــزاد‬\n      ‫العلنــي لكــون أحــد الورثــة جهــة حكوميــة ‪ -‬احلكــم ببيــع العقــار باملــزاد‬\n                 ‫العلنــي وقســمة الثمــن بــن الورثــة حســب الفريضــة الشــرعية ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫أقــام الورثــة دعــوى علــى بيــت املــال إللزامــه ببيــع عقــار ال ينقســم مبــزاد‬\n      ‫علنــي ألن بيــت املــال أحــد الورثــة حيــث توفيــت املــرأة التــي كانــت متلــك‬\n      ‫العقــار وانحصــر إرثهــا يف زوجهــا وابنتيهــا مبوجــب صــك حصــر ورثــه‬\n      ‫صــادر مــن احملكمــة ثــم تــويف زوجهــا وانحصــر إرثــه يف بيــت املــال وذلــك‬\n      ‫مبوجــب صــك صــادر مــن احملكمــة حضــر املدعــى عليــه منــدوب بيــت‬\n      ‫املــال وأقــر بصحــة الدعــوى وقــرر بأنــه ال مانــع لديــه مــن بيــع العقــار‬\n      ‫إذا وافقــت اجلهــات الرســمية‪ -‬اطلعــت احملكمــة علــى صــك امللكيــة‬\n      ‫وصكــوك حصــر الورثــة فوجدتهــا مطابقــة ملــا جــاء يف الدعــوى‪ -‬قــررت‬\n      ‫احملكمــة الكتابــة للجهــات الرســمية لإلفــادة عــن موافقتهــا علــى بيــع‬\n      ‫العقــار فــورد األمــر الســامي باملوافقــة علــى البيــع مبــزاد علنــي وقســمة‬\n\n‫‪113‬‬\n\f‫الثمــن بــن الورثــة حســب الفريضــة الشــرعية‪ -‬حكمــت احملكمــة ببيــع‬\n‫العقــار مبــزاد علنــي وقســمة ثمنــه بــن الورثــة ومــن ضمنهــم بيــت املــال‬\n               ‫رفــع هــذا اإلجــراء حملكمــة االســتئناف وجــرى تصديقــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪ 1433/02/09‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/02/09‬ه ـ‬\n‫حضــر بوكالتــه بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة يف‬\n‫‪1430/3/26‬ه ـ والتــي تخولــه إقامــة وســماع الدعــاوي واملرافعــة‬\n‫واملدافعــة والبيــع واإلفــراغ واســتالم الثمــن ‪ ...‬ادعــى علــى احلاضــر معــه‬\n‫مديــر بيــت املــال قائــا يف دعــواه عليــه إن مورثــة موكلــي كانــت متلــك‬\n‫العقــار الواقــع مبحلــة املعابــدة حــارة بنــي عامــر واحملــدود واملــذروع‬\n‫مبوجــب الصــك الصــادر مــن احملكمــة الكبــرى يف ‪14395/5/3‬ه ـ‬\n‫وقــد توفيــت منــذ ثالثــن ســنة وأنحصــر إرثهــا يف زوجهــا ويف بنتيهــا‬\n‫ال وارث لهــا ســواهم ‪،‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن‬\n‫احملكمــة العامــة يف ‪1430/3/5‬ه ـ ثــم تــويف يف عــام ‪1409‬ه ـ وأنحصــر‬\n‫إرثــه يف بيــت املــال وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن‬\n‫احملكمــة العامــة برقــم ‪ 3/100/224‬يف ‪1430/7/29‬ه ـ وألن العقــار‬\n‫ال ينقســم بــن الورثــة فأطلــب احلكــم ببيعــه باملــزاد العلنــي هــذه دعــواي‬\n‫وبســؤال مديــر بيــت املــال عــن دعــوى املدعــي وكالــة أجــاب قائــا إن‬\n‫بيــت املــال هــو وارث مبوجــب صــك حصــر الورثــة الصــادر مــن احملكمــة‬\n‫العامــة يف ‪1430/7/29‬ه ـ وهــو ورث الربــع مــن تركــة زوجتــه املتوفــاة‬\n\n                                                                                    ‫‪114‬‬\n\f      ‫قبلــه مبوجــب صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة يف‬\n      ‫‪1430/3/5‬ه ـ والتــي خلفــت العقــار الواقــع باملعابــدة حــارة ‪ .....‬واحملــدود‬\n      ‫واملــذروع مبوجــب صــك التملــك الصــادر مــن احملكمــة الكبــرى يف‬\n      ‫‪1395/5/3‬ه ـ وأمــا طلــب املدعــي وكالــة ببيــع العقــار باملــزاد العلنــي‬\n      ‫فأطلــب إمهالــي للرجــوع إلــى مرجعــي وإلحضــار اإلجابــة هــذه إجابتــي‬\n      ‫فطلبــت مــن املدعــي وكالــة صــك التملــك فطلــب إمهالــه ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي أصالــة ووكالــة كمــا حضــر منــدوب بيــت املــال‬\n      ‫باحملكمــة وجــرى االطــاع علــى صــك التملــك فوجدتــه صــادر مــن‬\n      ‫هــذه احملكمــة يف ‪1395/05/03‬ه ـ ويتضمــن ثبــوت متلــك لكامــل‬\n      ‫ـاء الواقــع مبحلــة املعابــدة حــارة ‪ .....‬واحملــدود شــرقا‬\n                                                                   ‫احملــدود أرضــا وبنـ ً‬\n      ‫ملــك وغربــا الســكة النافــذة وبهــا البــاب وشــما ًال ملــك وجنوبــا ملــك‪،‬‬\n      ‫واملــذروع شــماال بطــول عشــرة أمتــار وأربعــون ســنتمترا والضلــع اجلنوبــي‬\n      ‫مختلــف يبــدأ مــن الشــرق بأربعــة أمتــار وخمســن ســنتمترا ثــم ينعطــف‬\n      ‫إلــي اجلنــوب مبتــر واحــد وخمســن ســنتمترا ثــم يســتمر إلــي الغــرب‬\n      ‫مبتريــن وســتني ســنتمترا ثــم ينعطــف إلــي اجلنــوب بخمســة وعشــرين‬\n      ‫ســنتمترا ثــم يســتمر إلــي الغــرب مبتــر واحــد وســبعني ســنتمترا‪،‬‬\n      ‫والضلــع الشــرقي مختلــف يبــدأ مــن اجلنــوب بأربعــة أمتــار وســبعني‬\n      ‫ســنتمترا ثــم ينحــرف إلــي الشــمال بخــط منحنــي بقــدر ثالثــة أمتــار‬\n      ‫وســبعني ســنتمترا‪ ،‬والضلــع الغربــي مختلــف يبــدأ مــن الشــمال بســبعة‬\n      ‫أمتــار وخمســة وثالثــن ســنتمترا ثــم ينحــرف إلــي اجلنــوب مبتــر واحــد‬\n      ‫وســتني ســنتمترا ثــم ينعطــف إلــي الشــرق بعشــرة ســنتمترات ثــم يســتمر‬\n      ‫إلــى اجلنــوب مبتــر واحــد وخمســة وســبعني ســنتمترا وعــرض الســكة‬\n      ‫الغربيــة النافــذة مــن جهــة الشــمال متــران وخمســة وأربعــون ســنتمترا‬\n\n\n‫‪115‬‬\n\f‫ومــن جهــة اجلنــوب ســبعة أمتــار وتســعون ســنتمترا ‪،‬واملســاحة اإلجماليــة‬\n‫( ‪ )100.32‬م‪ 2‬مائــة متــر مربــع واثنــان وثالثــون باملائــة من املتــر املربــع ا‪.‬هـ‬\n‫كمــا جــرى اطالعــي علــى صــك حصــر الورثــة الصــادر مــن احملكمــة‬\n‫العامــة بالريــاض يف ‪1430/3/5‬ه ـ فوجدتــه يتضمــن ثبــوت وفــاة منــذ‬\n‫ثالثــن عامــا تقريبــا وانحصــار إرثهــا يف زوجهــا ويف ابنتيهــا ويف أختهــا‬\n‫ألب ال وارث لهــا ســواهم كمــا جــرى اطالعــي علــى صــك حصــر الورثــة‬\n‫الصــادر مــن احملكمــة العامــة بالريــاض يف ‪1430/7/29‬ه ـ فوجدتــه‬\n‫يتضمــن ثبــوت وفــاة وانحصــار إرثــه يف بيــت املــال أه ـ وســألت املدعــي‬\n‫عــن ســبب اختــاف اســم مورثتهــم يف الصــك عــن اســمها يف صــك‬\n‫حصــر الورثــة فقــال أننــي اطلــب إمهالــي لتصحيــح االســم ‪،‬هكــذا‬\n‫قــرر ‪ ،‬وحلــن تصحيــح االســم رفعــت اجللســة ثــم يف جلســة أخــرى حضــر‬\n‫املدعــي وكالــة كمــا حضــر مديــر بيــت املــال وقــرر املدعــي وكالــة‬\n‫قائــا لقــد مت تصحيــح اســم مورثــة موكلــي يف صــك حصــر الورثــة‬\n‫وباالطــاع علــى صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة‬\n‫بالريــاض يف ‪1430/3/5‬ه ـ فوجدتــه قــد أحلــق بــه أن صحــة اســم املتوفــاة‬\n‫هــو أه ـ وقــد جــرى االستفســار عــن ســجل صــك امللكيــة بخطابــي يف‬\n‫‪1433/3/15‬ه ـ فــوردت اإلفــادة مــن مديــر الســجالت باحملكمــة برقــم‬\n‫يف ‪1433/3/20‬ه ـ واملتضمــن مطابقــة الصــك لســجله أه ـ وبســؤال‬\n‫مديــر بيــت املــال عــن إجابتــه علــى طلــب املدعــي وكالــة بيــع العقــار‬\n‫باملــزاد العلنــي قــرر قائــا إننــا رفعنــا خطابــا بذلــك إلــى وزارة العــدل‬\n‫ولــم تردنــا اإلفــادة حتــى اآلن وأنــا أطلــب إمهالــي‪ ،‬ثــم يف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة كمــا حضــر مديــر بيــت املــال باحملكمــة وقــرر‬\n‫مديــر بيــت املــال قائــا لقــد مت رفــع اخلطــاب رقــم يف ‪1431/3/21‬ه ـ‬\n\n\n                                                                                         ‫‪116‬‬\n\f      ‫مــن احملكمــة الــى معالــي وزيــر العــدل بخصــوص طلــب املدعــن‬\n      ‫فــوردت اإلجابــة مــن فضيلــة وكيــل وزارة العــدل برقــم يف‪1434/3/6‬ه ـ‬\n      ‫وبرفقتهــا برقيــة خــادم احلرمــن الشــريفني يف‪1434/2/25‬ه ـ املتضمــن‬\n      ‫املوافقــة علــى بيــع العقــار وفقــا للتعليمــات إ‪.‬ه ـ وباالطــاع علــى برقيــة‬\n      ‫خــادم احلرمــن الشــريفني املرفقــة وجــدت هــذا نصهــا ( معالــي وزيــر‬\n      ‫العــدل الســام عليكــم ورحمــة اهلل وبركاتــه وبعــد‪ :‬اطلعنــا علــى‬\n      ‫خطــاب الــوزارة يف ‪1433/6/9‬ه ـ بخصــوص الدعــوى املقامــة مــن ضــد‬\n      ‫بيــت املــال بشــأن العقــار الواقــع يف حــي العائــد ة ملكيتــه للمتوفــاة‬\n      ‫مبوجــب حجــة االســتحكام الصــادرة مــن احملكمــة العامــة مبكــة‬\n      ‫املكرمــة بالصــك ه ـ البالغــة مســاحته (‪100/32‬م‪ )2‬مائــة متــر مربــع‬\n      ‫واثنــن وثالثــن يف املائــة مــن املتــر املربــع وحيــث ان بيــت املــال يــرث مــع‬\n      ‫ورثــة املتوفــاة الربــع يف كامــل العقــار لقــاء نصيــب زوجهــا املتــويف الــذي‬\n      ‫ال يوجــد لــه وارث ســوى بيــت املــال مبوجــب صــك حصــر اإلرث الصــادر‬\n      ‫مــن احملكمــة العامــة بالريــاض يف ‪1430/7/29‬ه ـ وتطلــب املدعيــة يف‬\n      ‫دعواهــا بيــع العقــار باملــزاد العلنــي ليأخــذ كل وارث نصيبــه وتطلــب‬\n      ‫الــوزارة التوجيــه حيــال اإلذن ببيــع العقــار املذكــور نخبركــم بأنــه ال‬\n      ‫مانــع مــن بيــع العقــار مــدار البحــث وفقــا للتعليمــات)‪ ،‬وقــرر مديــر بيــت‬\n      ‫املــال قائــا حيــث صــدرت املوافقــة علــى بيــع العقــار باملــزاد العلنــي فــان‬\n      ‫إدارة بيــت املــال موافقــة علــى ذلــك إذا كان يف البيــع غبطــة ومصلحــة‬\n      ‫هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع‬\n      ‫علــى صكــوك امللكيــة وحصــر الورثــة ولصــدور املوافقــة علــى بيــع‬\n      ‫العقــار فقــد حكمــت ببيــع العقــار املذكــور بعاليــة باملــزاد العلنــي‬\n      ‫وقســمة ثمنــه بــن الورثــة حســب الفريضــة الشــرعية وبعــرض احلكــم‬\n\n\n‫‪117‬‬\n\f‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر مديــر بيــت املــال عــدم‬\n‫القناعــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‪،‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/4/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ..‬وبعــد ‪،‬ثــم‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف بشــرح فضيلــة الرئيــس يف‬\n‫‪1434/5/28‬ه ـ علــى خطــاب رئيــس محكمــة االســتئناف مبنطقــة‬\n‫برقــم يف ‪1434/5/25‬ه ـ برفقهــا قــرار التصديــق مبوجــب القــرار يف‬\n‫‪1434/5/5‬ه ـ وهــذا نصــه ‪ -:‬احلمــد هلل والصــاة والســام علــى رســول‬\n‫اهلل وبعــد نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة جرى‬\n‫منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس‬\n‫احملكمــة العامــة وتاريــخ ‪1434/4/21‬ه ـ املشــتملة علــى الصــك وتاريــخ‬\n‫‪1434/4/17‬ه ــالصادر مــن فضيلــة الشــيخ‪ ..........‬القاضــي باحملكمــة‬\n‫العامــة املتضمــن اإلذن للمنهــي وكالــة ببيــع العقــار املذكــور يف‬\n‫االنهــاء‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،‬‬\n‫قاضــي اســتئناف ‪ ..........‬ختــم وتوقيــع ‪ ،‬قاضــي اســتئناف ‪ ..........‬ختــم‬\n‫وتوقيــع ‪ ،‬رئيــس الدائــرة ختــم وتوقيــع ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/7‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n‫املــال يف محكمــة االســتئناف جــرى منــا االطــاع املعاملــة الــواردة إلينــا‬\n\n\n                                                                                    ‫‪118‬‬\n\f      ‫شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة وتاريــخ ‪1434/4/21‬ه ـ‬\n      ‫املشــتملة علــى الصــك وتاريــخ ‪1434/4/17‬ه ـ الصــادر مــن فضيلــة‬\n      ‫الشــيخ القاضــي باحملكمــة العامــة اإلذن للمنهــي وكالــة ببيــع العقــار‬\n      ‫املذكــور يف اإلنهــاء وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                                 ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪119‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":113,"source_page_end":119,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"66c17040e9f53679df8983c8936e4222c1d5ac1477aba7f46f872c93159b7fd6","normalized_text_hash":"1087d7f3353e99019b8bf4c4bea278e7010d3fc81bfe48b34d7056ae95b1afe5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p113-34190721"},{"id":"5166c429-afb5-5271-b7e4-ae2bbb5983f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبه بيت املال -املطالبة برفع اليد عن عقار مملوك ملورث املدعي وتسليمه وأجرته إليه -تقدمي املدعي صك يؤيد دعواه -إيجابية قرار هيئة النظر للمدعي -موافقة بيت املال على تسليم العقار وأجرته للمدعن حال ثبوت احلق -إلزام بيت املال برفع يده عن العقار وتسليمه وأجرته للمدعن .","document_number":"34314669","case_number":"33141773","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/8","year":"1434","subject":"مطالبه بيت املال -املطالبة برفع اليد عن عقار مملوك ملورث املدعي وتسليمه وأجرته إليه -تقدمي املدعي صك يؤيد دعواه -إيجابية قرار هيئة النظر للمدعي -موافقة بيت املال على تسليم العقار وأجرته للمدعن حال ثبوت احلق -إلزام بيت املال برفع يده عن العقار وتسليمه وأجرته للمدعن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/9/8 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34314669 :‬‬\n                   ‫َر ْق ُم الدعوى‪33141773 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n         ‫‪ 34367263‬تاريخه‪1434/11/24 :‬هـ‬\n\n\n‫مطالبــه بيــت املــال‪ -‬املطالبــة برفــع اليــد عــن عقار مملوك ملــورث املدعي‬\n‫وتســليمه وأجرتــه إليــه‪ -‬تقــدمي املدعــي صــك يؤيــد دعــواه‪ -‬إيجابيــة‬\n‫قــرار هيئــة النظــر للمدعــي‪ -‬موافقــة بيــت املــال علــى تســليم العقــار‬\n‫وأجرتــه للمدعــن حــال ثبــوت احلــق ‪ -‬إلــزام بيــت املــال برفــع يــده عــن‬\n                                         ‫العقــار وتســليمه وأجرتــه للمدعــن ‪.‬‬\n\n\n\n\n                  ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n‫أقــام وكيــل ورثــة دعــوى علــى بيــت املــال يطالبــه برفــع يــده التــي وضعهــا‬\n‫علــى عقــار لينتقــل إلــى موكليــه بــاإلرث وتســليم العقار وأجرتــه املاضية‬\n‫إليهــم ‪ -‬قــرر املدعــى عليــه منــدوب بيــت املال موافقته على تســليم العقار‬\n‫وأجرتــه إذا ثبــت لــدى احملكمــة اســتحقاق املدعــن‪ -‬قــدم املدعــي‬\n‫صكــوك التملــك وحصــر الورثــة وبعــد اطــاع احملكمــة عليهــا تبــن‬\n‫أنهــا مطابقــة ملــا يدعــي بــه املدعــي فكتبــت احملكمــة لهيئــة النظــر‬\n‫للوقــوف علــى العقــار وتطبيــق الصــك عليــه بحضــور الطرفــن وقــد‬\n‫قــررت هيئــة النظــر أن الصــك مطابــق للواقــع لــذا حكمــت احملكمــة‬\n‫برفــع يــد بيــت املــال عــن العقــار املذكــور يف الدعــوى وتســليم أجرتــه‬\n\n                                                                                       ‫‪120‬‬\n\f      ‫للمدعــن لــم يقنــع مديــر بيــت املــال يف احلكــم فتــم رفعــه إلــى محكمــة‬\n                                                       ‫االســتئناف ومت تصديقــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنا من فضيلة رئيس احملكمة العامة وتاريخ‬\n      ‫‪1433/02/24‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/02/24‬ه ـ‬\n      ‫ففــي يــوم اإلثنــن املوافق‪1433/04/12‬ه ـ افتتحــت اجللســة وفيهــا حضر‬\n      ‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي ‪ ..........‬بصفتــه وكيــا‬\n      ‫عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n      ‫برقــم يف ‪1432/3/30‬ه ـ املخولــة لــه املرافعــة واملدافعــة والصلــح وعــن‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n      ‫يف ‪1432/3/30‬ه ـ املخولــة لــه املرافعــة واملدافعــة واإلقــرار والصلــح‬\n      ‫والتنــازل وعــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة املكرمــة برقــم يف ‪1431/1/18‬ه ـ وعــن و و مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة برقــم يف ‪1428/4/25‬ه ـ املخولــة‬\n      ‫لــه املرافعــة واملدافعــة واإلقــرار يف ‪1431/1/13‬ه ـ املخولــة لــه املرافعــة‬\n      ‫واملدافعــة واإلقــرار والصلــح وعــن أصالــة عــن نفســها وبواليتهــا عــن‬\n      ‫أصالــة عــن نفســها وبواليتهــا علــى أبنائهــا القصــر مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة برقــم يف ‪1427/7/1‬ه ـ املخولــة لــه‬\n      ‫املرافعــة واملدافعــة واإلقــرار وحضــر حلضــوره مدير بيت املــال باحملكمة‬\n      ‫وبســؤال املدعــي وكالــة عــن دعــواه ادعــى بقولــه إن مورثــة موكلــي‬\n      ‫خلفــت مــن ضمــن تركتهــا القطعــة الكائنــة ‪ .....‬واململوكــة بالصــك‬\n\n‫‪121‬‬\n\f‫الصــادر مــن هــذه احملكمــة يف ‪1386/5/11‬ه ـ واملقــام عليهــا عمــارة‬\n‫وحدودهــا بحســب الصــك شــرقا دار وغربــا الشــارع وبــه البــاب وواجهــة‬\n‫الــدار وأطوالهــا مــن الشــمال إلــى اجلنــوب ممــا يلــي الغــرب ثالثــة أمتــار ثم‬\n‫ينعطــف إلــى جهــة الشــرق بقــدر متــر واحــد وخمســة عشــر ســنتم يســتمر‬\n‫يف الطــول الغربــي إلــى جهــة اجلنــوب بقــدر متــر واحــد وســتني ســم ثــم‬\n‫ينعطــف إلــى جهــة الشــرق بقــدر متــر واحــد وعشــرين ســم ثــم يســتمر يف‬\n‫الطــول الغربــي إلــى جهــة اجلنــوب بقــدر ثالثــة أمتــار وثالثــن ســم وممــا‬\n‫يلــي الشــرق ســتة أمتــار وخمســة وســبعون ســم وعرضــا مــن الشــرق إلــى‬\n‫الغــرب ممــا يلــي اجلنــوب ســبعة أمتــار وســبعون ســم وممــا يلــي الشــمال‬\n‫عشــرة أمتــار وســتون ســم ومجمــوع مســاحته ســبعة وســتون متــرا مربعــا‬\n‫وأربعــة وأربعــون باملائــة مــن املتــر املربــع وقــد وضــع بيــت املــال باحملكمــة‬\n‫يــده علــى هــذا العقــار وقــام بتأجيــره وهــو يســتلم أجرتــه حتــى اآلن أطلــب‬\n‫احلكــم عليــه برفــع يــده عــن العقــار وتســليمه ملوكلــي وإلزامــه بتســليم‬\n‫اإليجــارات الســابقة ملوكلــي هــذه دعــواي وبعرضهــا علــى املدعــى عليــه‬\n‫طلــب اإلمهــال لإلجابــة فأجبتــه لطلبــه كمــا طلبــت مــن املدعــي إحضــار‬\n‫صكــوك حصــر اإلرث فاســتعد بذلــك وعليــه رفعــت اجللســة ويف جلســة‬\n‫أخــرى حضــر فيهــا الطرفــان وبســؤال املدعــي عــن صكــوك حصــر‬\n‫اإلرث أبــرز الصــك الصــادر مــن هــذه احملكمــة يف ‪1388/10/8‬ه ـ‬\n‫وباالطــاع عليــه وجــد يتضمــن وفــاة بتاريــخ ‪1388/8/4‬ه ـ وانحصــار‬\n‫إرثهــا يف بناتهــا كمــا أبــرز الصــك الصــادر مــن هــذه احملكمــة يف‬\n‫‪1396/6/21‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة ‪ ..........‬تاريــخ‬\n‫‪1396/5/10‬ه ـ وانحصــار إرثهــا يف زوجهــا ويف أوالدهــا املرزوقــن منــه‬\n‫وهــم كمــا أبــرز الصــك الصــادر مــن احملكمــة العامــة باملدينــة املنــورة‬\n\n\n                                                                                          ‫‪122‬‬\n\f      ‫يف ‪1432/1/19‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1431/4/6‬ه ـ وانحصــار إرثهــا يف أوالدهــا و ‪ ..........‬وأوالد ‪..........‬‬\n      ‫وأوالد ‪ ..........‬كمــا أبــرز الصــك الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫يف ‪1424/11/26‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1424/11/3‬ه وانحصــار إرثــه يف أوالده و ‪ ..........‬و ‪ ..........‬و ‪..........‬‬\n      ‫و ‪ ..........‬واملرزوقــن لــه مــن زوجتــه املتوفــاة حــال حياتــه ويف أوالده‬\n      ‫أيضــا املرزوقــن لــه مــن مطلقتــه كمــا أبــرز الصــك الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 11/30/28‬يف ‪1420/7/14‬ه ـ وباالطــاع عليــه وجــد‬\n      ‫يتضمــن ثبــوت وفــاة ‪ ..........‬بتاريــخ ‪1420/6/15‬ه ـ وانحصــار إرثــه يف‬\n      ‫والــده ويف زوجتــه ويف أوالده منهــا والبالغــن والقاصريــن كمــا أبــرز‬\n      ‫الصــك الصــادر مــن هــذه احملكمــة يف ‪1425/2/14‬ه ـ وباالطــاع‬\n      ‫عليــه وجــد يتضمــن ثبــوت وفــاة ‪ ..........‬بتاريــخ ‪1415/7/11‬ه ـ وانحصار‬\n      ‫إرثهــا يف أوالدهــا البالغــن املتوفــى قبلهــا كمــا أبــرز الصــك الصــادر‬\n      ‫مــن هــذه احملكمــة يف ‪1425/2/6‬ه ـ وباالطــاع عليــه وجــد يتضمــن‬\n      ‫ثبــوت وفــاة كمــا أبــزر الصــك الصــادر مــن هــذه احملكمــة برقــم ‪24‬‬\n      ‫يف ‪1425/2/9‬ه ـ وباالطــاع عليــه وجــد أنــه يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1402/4/25‬ه ـ وانحصــار إرثهــا يف والدتهــا ويف اخوتهــا األشــقاء كل‬\n      ‫مــن كمــا أبــرز الصــك الصــادر مــن هــذه احملكمــة برقــم ‪12/170‬‬\n      ‫يف ‪1397/8/3‬ه ـ وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة بتاريــخ‬\n      ‫‪1397/6/24‬ه ـ وانحصــر إرثــه الشــرعي يف زوجتــه الباقيــة يف عصمــة‬\n      ‫نكاحــه إلــى حــن وفاتــه ويف أوالده منهــا وهــم البالغــون القاصــران‬\n      ‫وبســؤال املدعــى عليــه عمــا اســتمهل مــن أجلــه قــال إنــه مت البحــث عــن‬\n      ‫مســتند اســتالم بيــت املــال للعقــار وحتــى اآلن لــم جنــده نظــرا لكــون‬\n\n\n‫‪123‬‬\n\f‫االســتالم قــد مضــى عليــه حوالــي أربعــن ســنة وأطلــب إعطائــي مهلــة‬\n‫أخــرى لإلجابــة فأجيــب لطلبــه وعليــه رفعــت اجللســة ويف جلســة أخــرى‬\n‫حضــر الطرفــان وبســؤال املدعــى عليــه عمــا اســتمهل مــن أجلــه قــال إنــه‬\n‫بعــد البحــث وجــد أن املبالــغ التــي مت اســتالمها مــن قبــل بيــت املــال مائــة‬\n‫وثالثــون ألفــا وتســعمائة وأربعــة وســتون ريــاال وعشــرون هللــة أمــا ســند‬\n‫اســتالم بيــت املــال للعقــار فقــد مت البحــث عنــه مــرارا ولــم نعثــر عليــه‬\n‫علمــا أن االســم املســجل لدينــا مالكــة العقــار هــو كمــا هــو مذكــور‬\n‫يف صــك امللكيــة كمــا أن املســتأجر للعقــار هــو مــن ضمــن الورثــة‬\n‫وكبيــر يف الســن وأطلــب حضــوره لســماع مــا لديــه هكــذا أجــاب‬\n‫وبــرد ذلــك علــى املدعــي وكالــة قــال ال علــم لــي مبقــدار املبالــغ املســتلمة‬\n‫وموكلــي راضــون باملبلــغ املذكــور وأمــا اختــاف االســم بــن الصــك‬\n‫ومــا هــو لــدى بيــت املــال فــا عالقــة ملوكلــي بــه وأمــا مــا ذكــره عــن‬\n‫املســتأجر فصحيــح وأنــا مســتعد بإحضــاره متــى طلبتــم هكــذا أجــاب‬\n‫وعنــد وصــول القضيــة إلــى هــذا احلــد وملزيــد مــن التحقــق فقــد قــررت‬\n‫رفــع اجللســة للكتابــة لهيئــة النظــر باحملكمــة للوقــوف علــى العقــار‬\n‫املذكــور بحضــور ممثــل للطرفــن وتطبيــق الصــك عليــه واإلفــادة عــن‬\n                  ‫مطابقتــه مــن عدمــه وتأجلــت اجللســة حتــى ورود اجلــواب‪.‬‬\n‫ويف جلســة أخــرى لــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة خلــف‬\n‫فضيلــة الشــيخ ‪ ..........‬بنــاء علــى خطــاب فضيلــة رئيــس احملكمــة يف‬\n‫‪1434/04/27‬ه ـ املبنــي علــى قــرار رئيــس املجلــس األعلــى للقضــاء‬\n‫رقــم يف ‪1434/04/23‬ه ـ واملبنــي علــى قــرار املجلــس األعلــى للقضــاء‬\n‫رقــم يف ‪1434/4/13‬ه ـ عليــه افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه أصالــة وبتــاوة مــا مت ضبطــه ســابقا عليهمــا‬\n\n\n                                                                                        ‫‪124‬‬\n\f      ‫صادقــا عليــه ثــم طلبــت مــن املدعــي وكالــة احضــار صكــوك وكاالتــه‬\n      ‫وصكــوك حصــر اإلرث علــى مــا ذكــر ســابقا عليــه رفعــت اجللســة ويف‬\n      ‫جلســة أخــرى حضــر فيهــا املدعــي وكالــة كمــا حضــر مديــر بيــت‬\n      ‫املــال وبســؤال املدعــي وكالــة عمــا اســتمهل مــن أجلــه أبــرز صكــوك‬\n      ‫حصــر اإلرث وصكــوك الــوكاالت املذكــورة ســابقا وباالطــاع‬\n      ‫عليهــا وجدتهــا مطابقــة ملــا ذكــر كمــا وردنــا يف هــذه اجللســة قــرار‬\n      ‫هيئــة النظــر يف ‪1434/05/19‬ه ـ واملتضمــن مــا نصــه (جــرى الوقــوف‬\n      ‫بالطبيعــة علــى املوقــع محــل النــزاع بحضــور الطرفــن وبرفقــة عمــدة‬\n      ‫حــي املســفلة ومعرفــن منتخبــن مــن قبلــه وجــرى أخــذ تعريفهــم املرفــق‬\n      ‫علــى الصــك رقــم ‪ 10/15‬يف ‪1386/5/11‬ه ـ ومبقارنــة مــا ذكــره‬\n      ‫املعرفــن باحلــدود املذكــورة بالصــك واحلــدود مبوجــب الطبيعــة تبــن‬\n      ‫مطابقــة الصــك املذكــور علــى العقــار محــل الدعــوى اخلــاص بورثــة ‪....‬‬\n      ‫وجــرى إعــداد الرفــع املســاحي املرفــق املعــد واملعتمــد مــن قبــل مكتــب‬\n      ‫‪ ....‬لالستشــارات الهندســية ) وبعــرض مــا جــاء يف قــرار هيئــة النظــر على‬\n      ‫مديــر بيــت املــال احلاضــر أجــاب قائــا إن بيــت املال يضع يــده على العقار‬\n      ‫املذكــور يف قــرار هيئــة النظــر وال أعلــم عــن مطابقــة الصــك لــه من عدم‬\n      ‫ذلــك كمــا يضــع يــده علــى مبلــغ وقــدره مائــة وثالثــون ألفــا وتســعمائة‬\n      ‫وأربعــة وســتون ريــاال وعشــرون هللــة متثــل أجــرة هــذا العقــار حتــى تاريــخ‬\n      ‫‪1433/01/22‬ه ـ وال مانــع لــدى بيــت املــال مــن تســليم العقــار املذكــور‬\n      ‫وأجرتــه املذكــورة للمدعيــن أصالــة متــى مــا ثبــت اســتحقاقهم كمــا‬\n      ‫جــرى االطــاع علــى صــك امللكيــة املشــار إليــه يف الدعــوى فوجدتــه‬\n      ‫يتضمــن مــا ذكــر ســابقا كمــا جــرى االستفســار عنــه مبوجــب خطابنــا‬\n      ‫رقــم يف ‪1433/5/22‬ه ـ فوردنــا جــواب مديــر الســجالت باحملكمــة‬\n\n\n‫‪125‬‬\n\f‫املتضمــن ( ال يوجــد علــى ســجل الصــورة الضوئيــة املرفقــة ســوى مــا‬\n‫أحلــق عليــه ) فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا جــاء يف‬\n‫قــرار هيئــة النظــر وملــا جــاء يف إقــرار كل مــن املدعيــان جلميــع مــا ســبق‬\n‫حكمــت علــى بيــت املــال برفــع يــده عــن العقــار املذكــور يف الدعــوى‬\n‫وتســليمه وتســليم أجرتــه البالــغ قدرهــا مائــة وثالثــون ألفــا وتســعمائة‬\n‫وأربعــة وســتون ريــاال وعشــرون هللــة للمدعيــن وبعــرض احلكــم علــى‬\n‫الطرفــن قنــع بــه املدعــي وكالــة ولــم يقنــع بــه املدعــى عليــه بــدون الئحــة‬\n‫اعتراضيــة عليــه أمــرت برفــع كامــل املعاملــة حملكمــة االســتئناف‬\n‫لتمييــز احلكــم حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس املوافــق ‪1434/12/26‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــي املعاملــة مــن محكمــة االســتئناف يف‬\n‫‪1434/12/18‬ه ـ مرفقــا بهــا القــرار رقــم يف ‪1434/11/24‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة‬\n‫علــى احلكــم واهلل املوفــق قاضــي اســتئناف ‪ ..........‬توقيعــه وختمــه‬\n‫قاضــي اســتئناف ‪ ..........‬توقيعــه وختمــه رئيــس الدائــرة ‪ ..........‬توقيعــه‬\n‫وختمــه) لــذا جــرى حتريــره حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/26‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبكــة املكرمــة برقــم وتاريــخ ‪1434/10/18‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة العامــة مبكــة‬\n\n\n                                                                                        ‫‪126‬‬\n\f      ‫املكرمــة وتاريــخ ‪1434/9/8‬ه ـ ‪ ،‬املتضمــن دعــوى وكالــة ضــد بيــت‬\n      ‫املــال‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                   ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪127‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":120,"source_page_end":127,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"73933f7c684e39cb93b28bc748283d440faeb3d9c82b71814805baf20f50c079","normalized_text_hash":"dd323e5b03e464a1147329b16b7cc8f6258ced8185b7986a5966a58c1962d850","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p120-34314669"},{"id":"e3915450-d807-5f14-bf10-ccc106db6ae1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -قيام املدعي بوضع بضاعة لدى شركة مقابل قيام الشركة ببيع البضاعة بنسبة ربح -هروب أصحاب الشركة وترك البضاعة داخل احملات -أخذ بيت املال البضاعة تنفيذ ا حلكم -مطالبة املدعي بيت املال بتسليمه البضاعة -شهادة الشهود العدول -إلزام بيت املال بتسليم البضاعة للمدعي .","document_number":"341325","case_number":"33305874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة والقائم بعمل فضيلة الشيخ","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/3","year":"1434","subject":"مطالبة بيت املال -قيام املدعي بوضع بضاعة لدى شركة مقابل قيام الشركة ببيع البضاعة بنسبة ربح -هروب أصحاب الشركة وترك البضاعة داخل احملات -أخذ بيت املال البضاعة تنفيذ ا حلكم -مطالبة املدعي بيت املال بتسليمه البضاعة -شهادة الشهود العدول -إلزام بيت املال بتسليم البضاعة للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫تاريخه‪1434/1/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪341325 :‬‬\n                   ‫َر ْق ُم الدعوى‪33305874 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34203439‬تاريخه‪1434/5/1 :‬هـ‬\n\n\n‫مطالبــة بيــت املــال‪ -‬قيــام املدعــي بوضــع بضاعــة لــدى شــركة مقابــل‬\n‫قيــام الشــركة ببيــع البضاعــة بنســبة ربــح‪ -‬هــروب أصحــاب الشــركة‬\n‫وتــرك البضاعــة داخــل احملــات‪ -‬أخــذ بيــت املــال البضاعــة تنفيــذ ًا‬\n‫حلكــم‪ -‬مطالبــة املدعــي بيــت املــال بتســليمه البضاعــة‪ -‬شــهادة الشــهود‬\n                 ‫العــدول‪ -‬إلــزام بيــت املــال بتســليم البضاعــة للمدعــي ‪.‬‬\n\n\n\n\n                      ‫‪-1‬قوله صلى اهلل عليه وسلم(ال ضرر وال ضرار)‬\n                                          ‫‪-2‬قاعدة الضرر يزال ويرفع‬\n‫‪-3‬املــادة ‪76‬مــن نظــام املرافعــات الشــرعية الفقــرة ‪ 8‬مــن الالئحــة‬\n                                                           ‫ا لتنفيذ يــة‬\n\n\n\n\n‫أقــام رجــل دعــوى علــى بيــت املــال يطالبــه بتســليم البضاعــة عبــارة عــن‬\n‫أقمشــة نســائية وديكــور خشــبي وضــع بيــت املــال يــده عليهــا مبوجــب‬\n‫صــك مكتســب للقطعيــة يتضمــن احلكــم بفتــح احملــات التــي توجــد‬\n‫بهــا البضاعــة وجــرد محتوياتهــا وحفظهــا وبيــع مــا يخشــى تلفــه‪ ،‬صــادق‬\n‫املدعــى عليــه علــى وجــود املنقــوالت لــدى بيــت املــال وال يعلــم مــن هــو‬\n‫مســتحقها وقــرر أنــه إذا ثبــت لــدى احملكمــة أنهــا للمدعــي فــا مانــع‬\n\n                                                                                    ‫‪128‬‬\n\f      ‫لديــه مــن تســليمها لــه‪ ،‬بطلــب البينــة مــن املدعــي‪ ،‬أحضــر شــهود ًا‬\n      ‫شــهدوا بصحــة دعــوى املدعــى ومت تزكيــة الشــهود‪ ،‬كمــا جــرى اطالع‬\n      ‫احملكمــة علــى الصكــوك ومحاضــر اجلــرد اخلاصــة بالبضاعة فوجدت‬\n      ‫مطابقــة ملــا يدعــي بــه املدعــي وحيــث قــرر مديــر بيــت املــال أن البضاعــة‬\n      ‫موجــودة لديــه وشــهدت البينــة بذلــك لــذا حكمــت احملكمــة علــى بيــت‬\n      ‫املــال بتســليم املدعــى بضاعتــه‪ ،‬اعتــرض املدعــى عليــه‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد اهلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة العامــة‬\n      ‫مبكــة املكرمــة والقائــم بعمــل فضيلــة الشــيخ ‪ ..........‬وبناء على املعاملة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n      ‫وتاريــخ ‪1433/05/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ ..........‬وتاريــخ‬\n      ‫‪1433/05/02‬ه ـ يف يــوم الســبت ‪1433/06/14‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 20‬وفيهــا حضــر ‪ ..........‬ســعودي بالســجل املدنــي رقــم‬\n      ‫ا عــن ‪ ..........‬ســعودي مبوجــب الوكالــة الصــادرة‬    ‫‪ ..........‬بصفتــه وكيـ ً‬\n      ‫مــن كتابــة العــدل الثانيــة برقــم ‪ ..........‬يف ‪1432/10/16‬ه ـ جلــد ‪3550‬‬\n      ‫وحضــر حلضــوره ‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬وبســؤال‬\n      ‫املدعــي عــن دعــواه قــال لقــد قــام موكلــي بوضــع بضاعتــه وهــي عبــارة‬\n      ‫عــن أقمشــة نســائية باملوقــع باإلضافــة إلــى تخشــيبة ديكــور مقابــل‬\n      ‫أن تقــوم الشــركة ببيــع البضاعــة مقابــل نســبة ‪ %30‬مــن الربــح وفعــا‬\n      ‫قامــت الشــركة ببيــع بعــض األقمشــة إال أن الشــركة املدعــى عليهــا‬\n      ‫شــركة ‪ .....‬قــد تركــوا احملــات ولــم يعثــر لهــم علــى أثــر والبضاعــة‬\n      ‫املذكــورة وغيرهــا ال تــزال يف محــل الشــركة الواقــع يف ‪ ........‬وقــد‬\n\n‫‪129‬‬\n\f‫صــدر صــك مــن ‪ ....‬يف ‪1431/7/8‬ه ـ وصــدق مــن محكمــة االســتئناف‬\n‫برقــم يف ‪1432/2/6‬ه ـ يتضمــن احلكــم علــى املدعــى عليهــا بفتــح‬\n‫احملــات وجــرد محتوياتهــا وحفظهــا وبيــع مــا هــذه احملكمــة يخشــى‬\n‫تلفــه وإن البضاعــة حالي ـ ًا لــدى بيــت املــال يف احملكمــة العامــة يف‬\n‫أطلــب إلزامهــم بتســليمي البضاعــة وهــي عبــارة عــن أقمشــة نســائية‬\n‫وديكــور خشــبي هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n‫مــا ذكــره املدعــي يف دعــواه غيــر صحيــح حيــث أنــه يوجــد منقــوالت‬\n‫كثيــرة غيرهــا مت جردهــا مبوجــب محضــر اســتالم املنقــوالت برقــم‬\n‫‪ ..........‬يف ‪1432/08/29‬ه ـ تنفيــذ ًا للصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ......‬يف ‪1431/7/8‬ه ـ وال نعلــم عــن صحــة دعــوى املدعــي فيمــا يدعــي‬\n‫بــه لكونهــا حفظــت لــدى بيــت املــال باســم الشــركة املدعــى عليهــا بنــاء‬\n‫علــى الصــك املذكــور ولكــن إذا ثبــت لــدى فضيلتكــم أن لــه حــق فيما‬\n‫يدعــي بــه فــا مانــع مــن تســليمه بعــد صــدور احلكــم الشــرعي مــن ذلــك‬\n‫وتصديــق احلكــم مــن محكمــة االســتئناف وأمــا بالنســبة للديكــورات‬\n‫الثابتــة فلــم تســتلم مــن قبــل بيــت املــال مبوجــب احملضــر املعــد مــن قبــل‬\n‫مندوبيهــا رقــم بــدون بتاريــخ ‪1432/2/29‬ه ـ املبنــي علــى مشــهد مديــر‬\n‫عــام املبيعــات والتســويق بشــركة إدارة وإمنــاء املشــاريع رقــم بــدون‬\n‫وتاريــخ ‪1432/07/05‬ه ـ املرفــق صورتــه املتضمــن مــن إن املكيفــات‬\n‫والســلم الكهربائــي وجميــع التجهيــزات واألنــوار والديكــورات الثابتــة‬\n‫املوجــودة باحملــات تعتبــر حــق للطــرف األول (املؤجــر) وتــؤل ملكيتهــا‬\n‫إليــه كمــا مت االتفــاق عليــه مبوجــب عقــد اإليجــار هــذه إجابتــي ثــم‬\n‫رفعــت اجللســة ويف جلســة الحقــه لــدي أنــا القاضــي يف احملكمــة العامــة‬\n‫وفيهــا حضــر املدعــي وكالــه كمــا حضــر منــدوب بيــت املــال وبســؤال‬\n\n\n                                                                                       ‫‪130‬‬\n\f      ‫املدعــي عــن بينتــه قــال لقــد أحضــرت بينتــي وهــم شــهود أطلــب ســماع مــا‬\n      ‫ا أشــهد بــأن‬ ‫لديهــم ثــم حضــر [وشــهد كل واحــد منهمــا مبفــرده قائ ـ ً‬\n      ‫املدعــي قــد اســتأجر مــن الشــركة املدعــى عليها ‪ ........‬مــن محلهم الذي‬\n      ‫اســتأجروه يف أبــراج البيــت بجــوار احلــرم وذلــك لبيــع أقمشــة نســائية مــع‬\n      ‫وضعهــم للديكــور علــى أن تكــون األربــاح ثالثــن باملائــة للمدعى عليها‬\n      ‫وقــد تركــت الشــركة املوقــع وأقفلــت احملــل وبداخلــه البضاعــة وال‬\n      ‫يوجــد أقمشــة نســائية غيرهــا يف املوقــع هــذا مــا لــدي وبــه أشــهد ثــم عدل‬\n      ‫الشــهود مــن قبــل مينــي اجلنســية مبوجــب اإلقامــة ومينــي اجلنســية مبوجــب‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث قــرر مديــر‬  ‫اإلقامــة فبنـ ً‬\n      ‫بيــت املــال مــن أن املوجــودات لديــه هــي البضاعــة فقــط دون الديكــور‬\n      ‫وخــاف هــو ملــا جــاء يف شــهادة الشــهود املعدلــن التعديــل الشــرعي وملــا‬\n      ‫جــاء يف قــرار محكمــة االســتئناف رقــم يف ‪1433/3/12‬ه ـ واملتضمــن‬\n      ‫أن للمدعــي أن يقيــم دعــوى ضــد بيــت املــال وملــا تضمنــه الصــك املشــار‬\n      ‫لــه أعــاه مــن احلكــم بالبيــع وجــرد احملتويات‪....‬الــخ وملــا روي عــن النبــي‬\n      ‫صلــى اهلل عليــه وســلم أنــه قــال (ال ضــرر وال ضــرار ) أخرجــه مالــك‬\n      ‫وأحمــد والدارقطنــي ولــه طــرق يشــد بعضهــا بعض ـ ًا وألن الضــرر يــزال‬\n      ‫ويرفــع لذلــك كلــه فقــد حكمــت علــى بيــت املــال بتســليم املدعــي‬\n      ‫بضاعتــه وهــي األقمشــة النســائية املوجــودة يف املوقــع املذكــور أعاله يف‬\n      ‫دعــواه واحملفوظــة لــدى بيــت املــال وبعــرض احلكــم علــى الطرفــن قنــع‬\n      ‫بــه املدعــي ولــم يقنــع مديــر بيــت املــال وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫ـاء علــى املــادة ‪ 8/76‬مــن‬  ‫لتدقيقــه بــدون الئحــة وعليــه أمــرت برفعــه بنـ ً‬\n      ‫نظــام املرافعــات الشــرعية وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                  ‫محمــد وآلــه وصحبــه حــرر يف ‪1434/01/03‬هــ‪.‬‬\n\n\n‫‪131‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫ففــي يــوم األحــد املوافــق ‪1434/4/21‬ه افتتحــت اجللســة الســاعة ‪09:20‬‬\n‫وفيهــا عــادت املعاملــة مــن محكمــة اإلســتئناف مبكــة املكرمــة‬\n‫وبرفقهــا قــرار املالحظــة يف ‪1434/01/19‬ه ـ املتضمن وبدراســة الصك‬\n‫وصــورة ضبطــه تقــرر باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي‪:‬‬\n‫‪ -1‬اإلطــاع علــى محضــر اســتالم املنقــوالت ورصــد مضمونــه وأخــذ‬\n‫مــا لــدى طــريف القضيــة عنــه ‪ -2‬اإلشــارة إلــى تعميــد منــدوب بيــت املــال‬\n‫‪ -3‬اإلطــاع علــى عقــد اإليجــار املبــرم بــن املدعــي وشــركة بــال ورصــد‬\n‫مضمونــه ‪ -4‬البــد أن تكــون الدعــوى محــررة التحريــر الشــرعي الــذي‬\n‫يعلــم مبوجبــه املدعــى فيــه قاضــي اســتئناف ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف موافــق علــى احلكــم ختمــه وتوقيعــه رئيــس الدائــرة ختمــه‬\n‫وجوابــا علــى مــا ذكــره أصحــاب الفضيلــة وفقنــي اهلل وإياهــم‬\n                                                                ‫ً‬     ‫وتوقيعــه‬\n‫لــكل خيــر أقــول لقــد جــرى اإلطــاع علــى عقــد اإليجــار املبــرم بــن‬\n‫الطرفــن ومرفــق صــورة منــه يف أوراق املعاملــة وقــد جــرت الكتابــة‬\n‫ملديــر بيــت املــال فوردنــا خطابهــم يف ‪1434/4/20‬ه ـ ونصــه [إشــارة إلى‬\n‫كتــاب فضيلتكــم رقــم ‪34/842527‬يف ‪1434/4/7‬ه ـ بشــأن الدعــوى‬\n‫املقامــة لــدى فضيلتكــم مــن املدعــي ضــد املنقــوالت التــي مت جردهــا‬\n‫مــن قبلنــا يف احملــل الكائــن يف أبــراج البيــت مبكــة املكرمــة املؤجــر‬\n‫مــن قبــل شــركة علــى شــركة الغائبــة والصــادر فيهــا الصــك رقــم يف‬\n‫‪1434/1/4‬ه ـ وطلــب فضيلتكــم إجــراء مــا يلــزم حيــال قــرار محكمــة‬\n‫اإلســتئناف املرفــق صورتــه برقــم يف ‪1434/1/19‬ه ـ ‪...‬الــخ عليــه‬\n‫ـبقا جــرد إجمالــي مبوجــب اجلــرد رقــم‬   ‫نفيدكــم بأنــه مت جردهــا مسـ ً‬\n‫‪ 7/470‬يف ‪1432/8/29‬ه ـ املرفــق صورتــه بنــاء علــى الصــك الصــادر‬\n\n\n                                                                                    ‫‪132‬‬\n\f      ‫ـابقا الشــيخ يف ‪1431/7/8‬ه ـ‬  ‫مــن فضيلــة القاضــي بهــذه احملكمــة سـ ً‬\n      ‫املتضمــن احلكــم بفتــح احملــل وجــرد مــا فيــه مــن احملتويــات وحفظهــا يف‬\n      ‫ببيــت املــال وبيــع مــا يخشــى تلفــه وحفــظ قيمتــه حلــن مراجعــة صاحبــه‬\n      ‫ولكــون املدعــي يدعــي باألقمشــة عليــه فقــد جــرى بعــث مندوبــي بيــت‬\n      ‫املــال بحضــور املدعــي وكالــة املذكــورة أســماؤهم يف احملضــر املرفــق‬\n      ‫حلصــر عــدد األقمشــة املدعــى بهــا فوجــد أن عددهــا (‪ )751‬ســبعمائة‬\n      ‫وواحــد وخمســون لفــة قمــاش فقــط مبوجــب احملضــر املرفــق وأنهــا‬\n      ‫الزالــت حتــت يــد بيــت املــال حتــى تاريخــه ] ومرفــق بــه محضــر هــذا‬\n      ‫نصــه [ احلمــد هلل رب العاملــن والصــاة والســام علــى خيــر خلــق اهلل‬\n      ‫أجمعــن أمــا بعــد فإنــه يف يــوم الســبت املوافــق ‪1434/4/13‬ه ـ ويف متــام‬\n      ‫صباحــا مت فتــح املســتودع املســتأجر مــن قبــل شــركة‬‫ً‬      ‫الســاعة التاســعة‬\n      ‫حلفــظ مخلفــات وذلــك حلصــر وعــد مــا يخــص املدعــي وكالــة مبوجــب‬\n      ‫الوكالــة يف ‪1432/10/16‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫وقــد مت فتــح املشــروع بحضــور كل مــن مندوبــي بيــت املــال ومنــدوب‬\n      ‫شــركة و والوكيــل الشــرعي بنــاء علــى خطــاب فضيلــة القاضــي‬\n                                                           ‫ً‬\n      ‫وحفظــا للواقــع جــرى اعــداد هــذا احملضــر وبــاهلل‬       ‫يف ‪1434/4/7‬ه ـ‬\n      ‫علمــا بــأن نتيجــة هــذا العــد هــي ‪ 751‬لفــة قمــاش واهلل ولــي‬ ‫التوفيــق ً‬\n      ‫أيضــا صــورة مــن محضــر اســتالم املنقــوالت اخلــاص‬ ‫التوفيــق] ومرفــق بــه ً‬\n      ‫بشــركة‪ ...‬وعليــه فلــم يظهــر لــي مــا يوجــب العــدول عمــا حكمــت بــه‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/04/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫خلــف الشــيخ يــوم األحــد املوافــق‪ 1434/05/19‬ه ـ افتتحــت اجللســة‬\n\n\n‫‪133‬‬\n\f‫الســاعة ‪ 10.15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫قــرار التصديــق وتاريــخ ‪1434/05/01‬ه ـ املتضمــن وبدراســة احلكــم‬\n‫وصــورة ضبطــه والئحتهــا االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف لــي وجهــة‬\n‫نظــر ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه واهلل املوفــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه حــرر يف ‪1434/05/19‬هــ‪.‬‬\n‫احلمد هلل وحده وبعد لدي أنا ‪ ..........‬القاضي باحملكمة العامة مبكة‬\n‫املكرمــة خلــف الشــيخ ففــي يــوم الســبت املوافق‪1434/07/15‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪10.15‬بنــاء علــى اخلطــاب الــوارد إلينــا مــن‬\n‫مديــر بيــت املــال يف ‪1434/06/04‬ه ـ املتضمــن أنــه قــد حضــر لــدى بيــت‬\n‫املــال الوكيــل ‪ .....‬وقــرر تســليمه جميــع مــا يخــص موكلــه الــذي مت‬\n‫جردهــا مبوجــب محضــر اجلــرد يف ‪1432/08/29‬ه ـ عليــه فقــد أمــرت‬\n‫بإحلاقــه يف الصــك وســجله وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                          ‫محمــد وآلــه وصحبــه حــرر يف ‪1434/07/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة وتاريــخ ‪1434/4/23‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪ .........‬القاضــي باحملكمــة العامــة وتاريــخ ‪1434/1/4‬هــ‪،‬‬\n‫املتضمــن دعــوى ضــد ‪ ،..........‬وبدراســة الصــك وصــورة ضبطــه تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n                                                                                  ‫‪134‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":128,"source_page_end":134,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dac2356b2aed419abb861ca602d32b7ab07b5ce3578d39588422ca06bbee6a28","normalized_text_hash":"128eff7fc155b5510f0492758ddffa58250f66352fbfef332d44b76601ae3129","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p128-341325"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
